window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q10"]=window.__LIBQ["pham-nhan-tu-tien"]["q10"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q10"]["map"]={"updatedAt":"2026-07-26","count":514,"nodes":[{"id":"khu-hoang-da","name":"Khu hoang dã","cn":"","capDo":"vuc","parentId":"phong-nguyen-dai-luc","blurb":"Vùng đất rộng lớn và nguy hiểm bên ngoài lãnh địa Nhân–Yêu trên Phong Nguyên Đại Lục.","detail":"Khu vực này có vô số quái vật, mãnh thú và hiểm địa đủ sức khiến tu sĩ cao giai bỏ mạng. Dù vậy, tài liệu quý hiếm vẫn hấp dẫn nhiều tu sĩ tiến vào, trong khi nguy cơ ngã xuống tăng cao theo độ sâu thâm nhập.","theLucLienQuan":["Nhân tộc","Yêu Tộc"],"nguon":["@c1747"]},{"id":"tam-canh-that-dia","name":"Tam cảnh Thất địa","cn":"","capDo":"vuc","parentId":"phong-nguyen-dai-luc","blurb":"Địa phận chung của Nhân tộc và Yêu Tộc, được hệ thống cấm chế cổ đại bảo vệ.","detail":"Toàn bộ Tam cảnh Thất địa được cấm chế do cổ đại tu sĩ bố trí bao quanh. Thiên Uyên Thành là cổng duy nhất có thể dùng để tiến vào địa phận hai tộc.","theLucLienQuan":["Nhân tộc","Yêu Tộc","Liên minh Nhân–Yêu"],"nguon":["@c1747"]},{"id":"loi-minh-dai-luc","name":"Lôi Minh Đại Lục","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Đại lục Hàn Lập rời đi bằng Truyền Tống Trận trước khi trở lại Phong Nguyên Đại Lục.","detail":"Hàn Lập dùng Truyền Tống Trận rời Lôi Minh Đại Lục và xuất hiện tại một vùng hẻo lánh trên Phong Nguyên Đại Lục.","theLucLienQuan":[],"nguon":["@c1748"]},{"id":"ky-han-tuyet-dia","name":"Kỳ Hàn Tuyệt Địa","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Tuyệt địa âm hàn nơi Hàn Lập từng mắc kẹt suốt một năm.","detail":"Quỷ khí âm hàn tại đây suýt đóng băng Hàn Lập vĩnh viễn. Khí lạnh màu lam trong tuyệt địa kích thích Ngũ Sắc Hàn Diễm thăng cấp, giúp hàn diễm hấp thu ngược luồng khí kỳ dị và cứu hắn thoát chết.","theLucLienQuan":[],"nguon":["@c1748"]},{"id":"thanh-nho-minh-toc","name":"Thành nhỏ Minh tộc","cn":"","capDo":"thanh","parentId":"phong-nguyen-dai-luc","blurb":"Thành thị Minh tộc nơi Hàn Lập gặp và giao chiến với Lôi Vân Tử.","detail":"Thành nhỏ không có nhân vật cấp đỉnh giai trấn giữ. Lôi Vân Tử nhìn thấu thân phận ngoại tộc của Hàn Lập tại đây, dẫn tới cuộc giao chiến kéo dài hơn một tháng.","theLucLienQuan":["Minh tộc"],"nguon":["@c1748"]},{"id":"huyen-vu-canh","name":"Huyền Vũ cảnh","cn":"","capDo":"vuc","parentId":"tam-canh-that-dia","blurb":"Một khu vực thuộc địa vực Nhân–Yêu, là nơi xuất thân của tông môn nhóm bốn tu sĩ do Nho sinh dẫn đầu.","detail":"Nhóm Nho sinh cho biết tông môn của họ nằm tại Huyền Vũ cảnh. Họ đã rời Thiên Uyên Thành khoảng nửa năm trước khi gặp Hàn Lập.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1749"]},{"id":"hoang-da-the-gioi","name":"Hoang Dã Thế Giới","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực hoang dã nằm ngoài cổng tương ứng của Thiên Uyên Thành.","detail":"Cổng thành hướng về Hoang Dã Thế Giới không mở trong điều kiện thông thường, nên tu sĩ ra vào Thiên Uyên Thành phải sử dụng các pháp trận truyền tống bên ngoài.","theLucLienQuan":["Thiên Uyên Thành","Thanh Minh Vệ"],"nguon":["@c1749"]},{"id":"dai-sanh-kiem-tra","name":"Đại sảnh kiểm tra","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Khu vực kiểm soát tu sĩ ra vào bên trong Thiên Uyên Thành.","detail":"Đại sảnh rộng khoảng trăm trượng, có Thanh Minh Vệ sử dụng Dị Linh Bàn kiểm tra từng tu sĩ và một Thiên Vệ Luyện Hư trung kỳ trực tiếp giám sát.","theLucLienQuan":["Thanh Minh Vệ","Thiên Uyên Vệ"],"nguon":["@c1750"]},{"id":"xuan-mien-cac","name":"Xuân Miên Các","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi nhóm bốn tu sĩ do Nho sinh đại diện dự định lưu lại sau khi trở về Thiên Uyên Thành.","detail":"Nho sinh cho Hàn Lập biết cả nhóm sẽ tạm trú tại đây và sẵn sàng chờ hắn sai bảo để báo đáp ân cứu mạng.","theLucLienQuan":[],"nguon":["@c1750"]},{"id":"linh-mach-trong-son-mach-gan-thien-uyen-thanh","name":"Linh mạch trong sơn mạch gần Thiên Uyên Thành","cn":"","capDo":"khac","parentId":null,"blurb":"Một linh mạch nhỏ nhưng có linh khí dồi dào trong phạm vi mấy trăm dặm, nằm trong vùng núi gần Thiên Uyên Thành.","detail":"Linh mạch vốn có hơn mười động phủ do hai tu sĩ Nguyên Anh kỳ cùng nhiều tu sĩ Kết Đan và Trúc Cơ chiếm giữ. Hàn Lập chọn nơi này làm địa điểm nghỉ ngơi và chuẩn bị bế quan, sau đó dùng thần niệm buộc toàn bộ cư dân rời đi.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1751"]},{"id":"dien-phu-giao-dich-hai-toc-nhan-yeu","name":"Điện phủ giao dịch hai tộc Nhân Yêu","cn":"","capDo":"khac","parentId":"phuong-thi","blurb":"Điện phủ trung gian nằm giữa hai khu giao dịch của Nhân tộc và Yêu tộc tại Phường thị Thiên Uyên Thành.","detail":"Đây là nơi hai tộc trao đổi những vật phẩm quý giá. Khi đi qua khu vực, Hàn Lập nhớ lại nữ tử Yêu tộc vô danh từng nhiều lần đổi cây giống linh dược quý hiếm cho mình.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1751"]},{"id":"ngon-nui-dat-dong-phu","name":"Ngọn núi đặt động phủ","cn":"","capDo":"khac","parentId":null,"blurb":"Ngọn núi được Hàn Lập chiếm làm nơi dựng động phủ và bế quan.","detail":"Hàn Lập cho Báo Lân Thú tuần tra quanh núi, dùng trận pháp sương mù che kín phạm vi trăm dặm và mở động phủ trực tiếp trong vách đá xanh.","theLucLienQuan":[],"nguon":["@c1752"]},{"id":"dong-phu-trong-thach-bich","name":"Động phủ trong thạch bích","cn":"","capDo":"khac","parentId":"ngon-nui-dat-dong-phu","blurb":"Động phủ được các cự viên khôi lỗi khai mở trong vách đá chỉ sau vài canh giờ.","detail":"Cửa đá của động phủ được ngụy trang hòa làm một với vách núi. Bên trong có dược viên, nhiều lối rẽ, các tầng cấm chế nhỏ và mật thất dùng để bế quan.","theLucLienQuan":[],"nguon":["@c1752"]},{"id":"huc-nhat-phong","name":"Húc Nhật Phong","cn":"","capDo":"khac","parentId":"linh-mach-trong-son-mach-gan-thien-uyen-thanh","blurb":"Ngọn núi bị Hàn Lập chiếm giữ ba ngày trước khi thiên tượng xuất hiện. Động phủ nơi hắn tu luyện nằm tại khu vực này.","detail":"Khi Hàn Lập tu luyện Luyện Thần thuật, vùng trời phía trên Húc Nhật Phong liên tiếp xuất hiện mây đen, cuồng phong, nước lạnh, mưa đá, tuyết lớn, gió nóng và biến đổi nhật quang. Dị tượng khiến nhiều tu sĩ sống quanh đó rời động phủ để quan sát.","theLucLienQuan":["Cốc gia"],"nguon":["@c1753"]},{"id":"bien-suong-mu","name":"Biển sương mù","cn":"","capDo":"khac","parentId":"huc-nhat-phong","blurb":"Vùng sương mù bao quanh nơi Hàn Lập tu luyện tại Húc Nhật Phong. Phần lớn thiên tượng dữ dội tập trung trong phạm vi này.","detail":"Ánh sáng Kim và Ngân cùng các biến đổi thời tiết tập trung quanh biển sương mù, khiến khu vực giống một thế giới thần bí. Khi ra ngoài phạm vi hơn ba trăm dặm, dị tượng không còn quá đặc biệt và chỉ hiện thành quang hà màu bạc mỏng trên bầu trời.","theLucLienQuan":["Cốc gia"],"nguon":["@c1753","@c1755"]},{"id":"ngon-nui-cua-mot-nhanh-coc-gia","name":"Ngọn núi của một nhánh Cốc gia","cn":"","capDo":"khac","parentId":"linh-mach-trong-son-mach-gan-thien-uyen-thanh","blurb":"Ngọn núi nằm cách biển sương mù chưa đầy mười dặm, thuộc khu vực cư trú của một nhánh Cốc gia. Đây là nơi nhóm tu sĩ Cốc gia quan sát thiên tượng.","detail":"Nam tử áo bào trắng cùng hơn mười tộc nhân đứng trên ngọn núi này để theo dõi biến động quanh Húc Nhật Phong. Động phủ của nhánh Cốc gia nằm dưới chân núi, và một thanh niên được để lại trên núi sau khi những người khác trở về.","theLucLienQuan":["Cốc gia"],"nguon":["@c1753"]},{"id":"nui-nguyet-nam","name":"Núi Nguyệt Nam","cn":"","capDo":"khac","parentId":null,"blurb":"Ngọn núi gần thành Trần Vũ, nơi Cốc gia ẩn cư.","detail":"Núi Nguyệt Nam là địa bàn của Cốc gia, một chân linh thế gia truyền thừa từ thượng cổ và rất ít tiếp xúc với bên ngoài. Ngoại giới chỉ lưu truyền rằng có tu sĩ ẩn cư trong núi.","theLucLienQuan":["Cốc gia"],"nguon":["@c1754"]},{"id":"nghiem-han-gioi","name":"Nghiễm Hàn giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Nơi Hàn Lập thu được nhiều truyền thừa, đan dược, linh dược và vật phẩm quý.","detail":"Các thu hoạch được nhắc tới gồm Vạn Kiếm Đồ, Luyện Thần thuật, Hư Linh đan, nhiều linh dược, phù lục và Tinh Không Đồ.","theLucLienQuan":[],"nguon":["@c1755"]},{"id":"ngon-nui-trong-bien-suong-mu","name":"Ngọn núi trong biển sương mù","cn":"","capDo":"khac","parentId":"bien-suong-mu","blurb":"Ngọn núi được Hàn Lập chọn làm trung tâm cho pháp trận hỗ trợ đột phá Hợp Thể kỳ.","detail":"Hàn Lập bố trí pháp trận khổng lồ quanh núi rồi bế quan trong mật thất. Khi thiên tượng hình thành, kim sắc cự viên xuất hiện từ ngọn núi và nghênh chiến tử sắc cự giao.","theLucLienQuan":[],"nguon":["@c1755"]},{"id":"thien-uyen-thanh","name":"Thiên Uyên thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Thành trì mà Hàn Lập tới sau khi hoàn tất ba năm củng cố tu vi Hợp Thể kỳ.","detail":"Hàn Lập mất hai tháng để tới Thiên Uyên thành, sau đó tìm đến nơi ở của nhóm bốn tu sĩ Hóa Thần từng quen biết.","theLucLienQuan":["Nhân tộc","Yêu Tộc"],"nguon":["@c1760","@c1994"]},{"id":"khu-lau-cac-danh-cho-tu-si-ben-ngoai-tai-thien-uyen-thanh","name":"Khu lầu các dành cho tu sĩ bên ngoài tại Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Khu cư trú tạm thời dành cho các tu sĩ từ bên ngoài đến Thiên Uyên thành.","detail":"Khu vực gồm nhiều thạch tháp và lầu các. Tu sĩ cấp thấp thường phải ở ghép, còn tu sĩ từ Luyện Hư trở lên có thể độc chiếm một tòa; nhóm bốn tu sĩ Hóa Thần quen Hàn Lập cùng cư trú tại một lầu các ở đây.","theLucLienQuan":[],"nguon":["@c1760"]},{"id":"thach-thap-cua-thanh-minh-ve","name":"Thạch tháp của Thanh Minh vệ","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Ngọn thạch tháp tại Thiên Uyên thành, nơi Hàn Lập từng đảm nhiệm chức vụ Thanh Minh vệ.","detail":"Sau mấy trăm năm, cảnh vật quanh thạch tháp gần như không thay đổi. Lối vào được hơn mười Hắc Thiết Vệ cùng hai Thanh Minh vệ canh giữ.","theLucLienQuan":["Thanh Minh vệ","Thiên Uyên vệ","Hắc Thiết Vệ"],"nguon":["@c1762"]},{"id":"tu-tien-cac","name":"Tụ Tiên các","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi Hàn Lập lưu lại trong thời gian trở về Thiên Uyên thành.","detail":"Hàn Lập nhờ Đinh huynh báo Hứa Thiên Vũ tới Tụ Tiên các gặp mình sau khi nàng kết thúc chuyến tuần tra ngoài thành.","theLucLienQuan":[],"nguon":["@c1762"]},{"id":"dong-quat-truyen-tong-cua-ngan-toc","name":"Động quật truyền tống của Ngân Tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Động quật bí mật có truyền tống trận và hơn mười giáp sĩ khôi lỗi canh giữ.","detail":"Nằm xa địa phận Nhân Tộc, động quật bị bạch y nữ tử và hắc bào đại hán xâm nhập. Lực lượng khôi lỗi bị phá nát và người canh giữ Ngân Tộc bị sát hại.","theLucLienQuan":["Ngân Tộc"],"nguon":["@c1763"]},{"id":"cung-dien-giua-phong-nguyen-va-loi-minh","name":"Cung điện giữa Phong Nguyên đại lục và Lôi Minh đại lục","cn":"","capDo":"khac","parentId":null,"blurb":"Cung điện bí ẩn nằm trong khu vực giữa Phong Nguyên đại lục và Lôi Minh đại lục.","detail":"Một mật thất phong kín bằng hắc khí bên trong cung điện chứa kén huyết quang, xác mười hai dị thú khô quắt, mười hai cổ đăng đã tắt và thủy tinh cầu hiển thị đài sen bạc.","theLucLienQuan":[],"nguon":["@c1763"]},{"id":"dai-dien-phuong-thi-thien-uyen-thanh","name":"Đại điện phường thị Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Trung tâm giao dịch của Nhân Tộc và Yêu Tộc tại Thiên Uyên thành.","detail":"Hàn Lập tới đây tìm kiếm thêm tài liệu và tình cờ gặp lại nữ tử Yêu tộc từng trao đổi vạn năm linh dược với mình.","theLucLienQuan":["Nhân Tộc","Yêu Tộc"],"nguon":["@c1763"]},{"id":"thien-ho-chi-dia","name":"Thiên hồ chi địa","cn":"","capDo":"khac","parentId":"huyen-vu-canh","blurb":"Một mốc địa lý thuộc Huyền Vũ cảnh, nằm cạnh địa điểm tổ chức Vạn bảo giao dịch hội.","detail":"Vạn bảo giao dịch hội của Nhân tộc và Yêu tộc được ấn định tổ chức tại khu vực nằm giữa Thiên hồ chi địa và Cửu Tiên Sơn.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1764"]},{"id":"cuu-tien-son","name":"Cửu Tiên Sơn","cn":"","capDo":"khac","parentId":"huyen-vu-canh","blurb":"Một vùng núi thuộc Huyền Vũ cảnh, được dùng làm mốc xác định địa điểm tổ chức Vạn bảo giao dịch hội.","detail":"Địa điểm diễn ra Vạn bảo giao dịch hội nằm giữa Cửu Tiên Sơn và Thiên hồ chi địa.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1764","@c1822"]},{"id":"thien-nguyen-canh","name":"Thiên Nguyên cảnh","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực có Hứa gia tọa lạc, là đích đến tiếp theo của Hàn Lập và Hứa Thiên Vũ.","detail":"Hứa Thiên Vũ dự định dẫn Hàn Lập từ Thiên Uyên Thành đến Hứa gia trong Thiên Nguyên cảnh bằng cách sử dụng nhiều lượt Truyền Tống pháp trận.","theLucLienQuan":["Hứa gia"],"nguon":["@c1765"]},{"id":"chan-ma-gioi","name":"Chân Ma giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện nơi Cổ Ma cư trú và đang chuẩn bị chiến tranh xâm lấn Linh giới.","detail":"Mạc Giản Ly từng dùng Tinh bàn tiến vào đây thăm dò, phát hiện hoạt động chuẩn bị chiến tranh quy mô lớn trước khi bị một Thánh tổ Ma giới phát giác.","theLucLienQuan":["Ma tộc"],"nguon":["@c1766"]},{"id":"phong-lam-thanh","name":"Phong Lâm thành","cn":"","capDo":"thanh","parentId":"thien-nguyen-canh","blurb":"Thành thị hẻo lánh thuộc Thiên Nguyên cảnh và là điểm truyền tống gần Hứa gia nhất.","detail":"Phong Lâm thành có khu truyền tống nằm trên sườn núi và được canh phòng nghiêm ngặt. Thành do ba tu sĩ Luyện Hư giữ chức chính phó Thành chủ phụ trách, nhưng từ đây tới nơi cư trú của Hứa gia vẫn cần hơn một tháng hành trình.","theLucLienQuan":["Phong Lâm thành","Thiên Uyên thành","Hứa gia"],"nguon":["@c1767"]},{"id":"dia-ban-hua-gia","name":"Địa bàn Hứa gia","cn":"","capDo":"khac","parentId":"thien-nguyen-canh","blurb":"Sơn mạch nhỏ xanh tươi nằm giữa vùng đồi núi đỏ nghèo linh khí.","detail":"Địa bàn có một linh mạch bình thường và khoảng mười ngọn núi được xây dựng dày đặc kiến trúc. Toàn khu vực được bảo vệ bởi cấm chế pháp trận có dao động huyền diệu.","theLucLienQuan":["Hứa gia"],"nguon":["@c1767"]},{"id":"vung-tinh-dong-khoang-mach","name":"Vùng Tinh Đồng khoáng mạch","cn":"","capDo":"khac","parentId":"thien-nguyen-canh","blurb":"Vùng đất đỏ nghèo linh khí chứa nguồn Tinh Đồng quy mô lớn.","detail":"Đất đá và cây cối trong khu vực dần nhuốm đỏ, không có linh mạch đáng kể nhưng sở hữu Tinh Đồng khoáng mạch trữ lượng không nhỏ. Nguồn tài nguyên này quyết định việc Hứa gia định cư tại đây.","theLucLienQuan":["Hứa gia"],"nguon":["@c1767"]},{"id":"son-mach-hua-gia","name":"Sơn mạch Hứa gia","cn":"","capDo":"khac","parentId":"thien-nguyen-canh","blurb":"Khu vực đặt cơ nghiệp của Hứa gia tại Thiên Nguyên cảnh. Cảnh tượng và vị trí thật của các ngọn núi được Mê Trận Huyễn Cảnh che giấu.","detail":"Sơn mạch có hơn mười ngọn núi cao thấp khác nhau và một tòa cung điện lớn ở khu vực trung tâm để tiếp khách. Đại trận hộ tộc khiến hình ảnh bên ngoài lệch khỏi vị trí thật của các ngọn núi và kiến trúc bên trong.","theLucLienQuan":["Hứa gia"],"nguon":["@c1768"]},{"id":"phuong-thi-di-toc","name":"Phường thị dị tộc","cn":"","capDo":"khac","parentId":"thien-nguyen-dai-luc","blurb":"Phường thị trong khu vực dị tộc mà Hàn Lập từng ghé qua trên đường trở về địa vực Nhân tộc.","detail":"Tại một gian hàng tạp hóa trong phường thị này, Hàn Lập phát hiện điển tịch viết bằng cổ văn Nhân tộc, ghi chép đầy đủ Mê Trận Huyễn Cảnh.","theLucLienQuan":[],"nguon":["@c1768"]},{"id":"mat-that-hua-gia","name":"Mật thất Hứa gia","cn":"","capDo":"khac","parentId":"dia-ban-hua-gia","blurb":"Mật thất nằm phía sau tòa lâu đài của Hứa gia và được nhiều tầng cấm chế bảo vệ.","detail":"Hứa Giao, Hứa Hỏa và những người Hứa gia đưa ngọc giản cùng hộp ngọc vào đây để kiểm tra kim phù. Hứa Giao đã dùng huyết mạch tháo phong ấn trên ngọc giản tại mật thất này.","theLucLienQuan":["Hứa gia"],"nguon":["@c1769"]},{"id":"nui-tong-mieu-cua-hua-gia","name":"Núi Tông Miếu của Hứa gia","cn":"","capDo":"khac","parentId":"son-mach-hua-gia","blurb":"Ngọn núi đặt Tông Miếu của Hứa gia, nơi tiến hành nghi thức đánh thức tia huyết hồn của Băng Phách tiên tử.","detail":"Hứa gia điều động mật vệ và phát động cấm chế để phong tỏa ngọn núi trong đêm. Khi nghi thức diễn ra, huyết quang cùng huyết tinh khí bao phủ khu vực, tạo dao động đủ để Hàn Lập phát hiện từ nơi lưu trú.","theLucLienQuan":["Hứa gia"],"nguon":["@c1770"]},{"id":"hua-gia-tong-mieu","name":"Hứa gia tông miếu","capDo":"khac","parentId":"nui-tong-mieu-cua-hua-gia","blurb":"Tông miếu lớn của Hứa gia nằm sát sườn ngọn núi thường phát ra dao động linh khí. Cổng chính treo bảng bạc viết chữ Hứa bằng cổ văn, lối vào mật điện phải đi qua cửa hông.","detail":"Tông miếu lớn của Hứa gia nằm sát sườn ngọn núi đặt cấm chế. Cổng chính treo bảng bạc viết chữ Hứa bằng cổ văn. Bên trong có mật điện là nơi tiến hành nghi thức gọi hồn, chỉ có thể vào bằng cửa hông. Khu vực được bảo vệ bởi nhiều tầng cấm chế và hơn trăm mật vệ phần lớn Nguyên Anh kỳ canh giữ.","theLucLienQuan":["Hứa gia"],"nguon":["@c1771"]},{"id":"mat-dien-hua-gia","name":"Mật điện Hứa gia","capDo":"khac","parentId":"hua-gia-tong-mieu","blurb":"Không gian bí mật nằm bên trong tông miếu Hứa gia, chỉ có thể tiến vào bằng cửa hông, là nơi tiến hành nghi thức gọi hồn.","detail":"Mật điện nằm trong Hứa gia tông miếu, lối vào duy nhất qua cửa hông. Đây là nơi ba tu sĩ Luyện Hư của Hứa gia đã nhiều lần thất bại trong nghi thức gọi tỉnh huyết hồn của Băng Phách tiên tử.","theLucLienQuan":["Hứa gia"],"nguon":["@c1771"]},{"id":"dai-sanh-ngam-hua-gia","name":"Đại sảnh ngầm dưới hậu điện Hứa gia","cn":"","capDo":"khac","parentId":"nui-tong-mieu-cua-hua-gia","blurb":"Gian đại sảnh rộng ba bốn trăm trượng xây bằng hắc sắc ngọc thạch dưới lòng đất, nơi Hứa gia bố trí pháp trận thức tỉnh Huyết hồn.","detail":"Nằm bên dưới hậu điện của Hứa gia, phải đi qua thông đạo dốc xuống có Nguyệt quang thạch chiếu sáng và mật vệ canh giữ. Bốn phía và đỉnh đại sảnh phủ đầy phù văn, trung tâm là đài lục giác và huyết trì tròn chứa linh dịch cùng Huyết tinh quan. Khi đêm xuống, phù văn trên đỉnh tự kết thành tiểu pháp trận và kích hoạt nghi thức.","theLucLienQuan":["Hứa gia"],"nguon":["@c1772"]},{"id":"huyet-tri-trung-tam-phap-tran","name":"Huyết trì trung tâm pháp trận","cn":"","capDo":"khac","parentId":"dai-sanh-ngam-hua-gia","blurb":"Ao tròn nằm trên đài lục giác, chứa linh dịch đỏ tươi và cất Huyết tinh quan bên trong.","detail":"Huyết trì nằm ở trung tâm đại sảnh ngầm, trên một đài lục giác là bộ phận cốt lõi của pháp trận thức tỉnh Huyết hồn. Khi nghi thức khởi động, linh dịch sôi trào tạo lốc xoáy chứa ngân sắc phù văn, dần dần dẫn Huyết tinh quan lộ ra trong huyết sắc hỏa diễm.","theLucLienQuan":["Hứa gia"],"nguon":["@c1772"]},{"id":"dai-sanh-huyet-tri-cua-hua-gia","name":"Đại sảnh huyết trì của Hứa gia","cn":"","capDo":"khac","parentId":"dia-ban-hua-gia","blurb":"Không gian của Hứa gia dùng để tiến hành nghi thức ngưng hóa và thức tỉnh nữ tử.","detail":"Đại sảnh đặt huyết trì, Huyết tinh quan và hệ thống pháp trận. Các tu sĩ Hứa gia tập trung tại đây để vận hành nghi thức, còn Hàn Lập cùng hai trợ thủ bổ sung linh lực khi pháp lực của họ gần cạn.","theLucLienQuan":["Hứa gia"],"nguon":["@c1773"]},{"id":"huyet-tri","name":"Huyết trì","cn":"","capDo":"khac","parentId":"dai-sanh-huyet-tri-cua-hua-gia","blurb":"Trung tâm của Huyết trì pháp trận, cung cấp huyết ti và huyết sắc phù văn cho quá trình tạo huyết khu.","detail":"Bên trong huyết trì hình thành huyết sắc toàn phong. Khi pháp trận được tăng cường, vô số huyết ti và phù văn tiếp tục tuôn vào Huyết tinh quan, giúp huyết khu ngưng hóa hoàn tất.","theLucLienQuan":["Hứa gia"],"nguon":["@c1773"]},{"id":"ma-gioi","name":"Ma Giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện được nhắc đến như nơi sản sinh Ngọc Ma Hoa.","detail":"Ngọc Ma Hoa là linh dược đặc sản của Ma Giới, hữu dụng đối với việc tu luyện ma công và có độ quý hiếm không kém linh bảo.","theLucLienQuan":[],"nguon":["@c1775"]},{"id":"that-yeu-chi-dia","name":"Thất Yêu chi địa","cn":"","capDo":"vuc","parentId":null,"blurb":"Địa vực Yêu tộc tiếp giáp Huyền Vũ cảnh.","detail":"Vị trí giáp Thất Yêu chi địa khiến Huyền Vũ cảnh thường phải đối mặt với thú triều quy mô lớn, yêu thú cao giai và cả yêu thú đã hóa hình xâm nhập.","theLucLienQuan":["Yêu tộc"],"nguon":["@c1777"]},{"id":"yeu-ho-chi-dia","name":"Yêu hồ chi địa","cn":"","capDo":"vuc","parentId":null,"blurb":"Địa vực của Yêu tộc nằm sát Cửu Tiên Sơn.","detail":"Cửu Tiên Sơn nằm ở khu vực giáp ranh giữa Yêu hồ chi địa và Huyền Vũ cảnh, vì vậy Nhân tộc cùng Yêu tộc đều phái lực lượng tới trấn giữ.","theLucLienQuan":["Yêu tộc","Lực lượng Nhân - Yêu trấn thủ Cửu Tiên Sơn"],"nguon":["@c1777"]},{"id":"nui-hoang-cach-xa-cuu-tien-son","name":"Núi hoang cách xa Cửu Tiên Sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Ngọn núi hoang nằm khá xa Cửu Tiên Sơn, nơi cha con Bạch Hóa Cập bị nhóm Thạch Luân phục kích.","detail":"Thạch Luân cùng hai hắc y tu sĩ dụ Bạch Hóa Cập và Bạch Quả Nhi tới đây để cưỡng đoạt Thiên Niên Huyết Sâm. Vị trí hẻo lánh giúp chúng tránh lực lượng tuần tra quanh các Phường thị.","theLucLienQuan":[],"nguon":["@c1778"]},{"id":"nam-son","name":"Nam Sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Địa danh gắn với danh xưng Nam Sơn Tam Ác.","detail":"Chương chỉ nhắc Nam Sơn qua danh xưng Nam Sơn Tam Ác, chưa cung cấp vị trí hay đặc điểm địa lý cụ thể.","theLucLienQuan":["Nam Sơn Tam Ác"],"nguon":["@c1780"]},{"id":"thanh-thanh","name":"Thánh Thành","cn":"","capDo":"thanh","parentId":"linh-gioi","blurb":"Một thành trì từng gửi lời mời Hàn Lập sau khi hắn tiến giai Hợp Thể.","detail":"Hàn Lập từng từ chối lời mời tới Thánh Thành, vì vậy không gặp Thiên Nguyên Thánh Hoàng tại đó.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1782","@c1880"]},{"id":"thanh-hoang-bao-kho","name":"Thánh Hoàng bảo khố","cn":"","capDo":"khac","parentId":"thanh-thanh","blurb":"Kho tàng thuộc quyền quản lý của Thiên Nguyên Thánh Hoàng.","detail":"Thiên Nguyên Thánh Hoàng từng mang một số vật phẩm từ bảo khố tới phục vụ sự kiện và có thể tìm phụ liệu ủ Hồng La Tiên Tửu tại đây.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1782"]},{"id":"khu-vuc-cam-dia-cuu-tien-son","name":"Khu vực cấm địa Cửu Tiên Sơn","cn":"","capDo":"khac","parentId":"cuu-tien-son","blurb":"Khu vực sâu hàng ngàn dặm trong Cửu Tiên Sơn được phong tỏa để đón những đại nhân vật tham dự Vạn Bảo Đại Hội.","detail":"Chỉ những đại nhân vật được mời trước mới được tiến vào. Người tự tiện xâm nhập có thể bị lực lượng trấn thủ đuổi đi hoặc giết chết.","theLucLienQuan":["Lực lượng Nhân - Yêu trấn thủ Cửu Tiên Sơn"],"nguon":["@c1783"]},{"id":"dong-phu-cua-dien-thanh-diep","name":"Động phủ của Điền Thanh Diệp","cn":"","capDo":"khac","parentId":"cuu-tien-son","blurb":"Động phủ nằm trên một ngọn núi ở vùng phụ cận Cửu Tiên Sơn.","detail":"Cửa đá trong vách núi được huyễn thuật ngụy trang thành một khu rừng nhỏ. Hàn Lập phá lớp huyễn hóa để làm lộ cửa động phủ trước khi truyền tin vào trong.","theLucLienQuan":["Kim Quảng Tông"],"nguon":["@c1783"]},{"id":"dong-phu-cua-nhac-hoa-tien-tu","name":"Động phủ của Nhạc Hoa tiên tử","cn":"","capDo":"khac","parentId":null,"blurb":"Động phủ nơi Hàn Lập kiểm tra và tạm thời chữa trị cho Bạch Quả Nhi.","detail":"Phía sau đại sảnh của động phủ có một hành lang dẫn tới phòng ngủ của Bạch Quả Nhi.","theLucLienQuan":[],"nguon":["@c1784"]},{"id":"phong-ngu-cua-bach-qua-nhi","name":"Phòng ngủ của Bạch Quả Nhi","cn":"","capDo":"khac","parentId":"dong-phu-cua-nhac-hoa-tien-tu","blurb":"Gian phòng nơi Bạch Quả Nhi nằm hôn mê khi hàn khí phát tác.","detail":"Trong phòng đặt giường viêm mộc; Hàn Lập tiến hành kiểm tra huyết dịch và tạm thời trục xuất hàn khí cho Bạch Quả Nhi tại đây.","theLucLienQuan":[],"nguon":["@c1784"]},{"id":"phi-tien-phong","name":"Phi Tiên Phong","cn":"","capDo":"khac","parentId":"cuu-tien-son","blurb":"Ngọn núi cao nhất trong chín ngọn núi của Cửu Tiên Sơn, thuộc địa phận phàm nhân.","detail":"Phi Tiên Phong được chọn làm nơi đặt quảng trường và hội trường chính của Vạn Bảo đại hội. Những người tinh thông thần thông thổ hệ của hai tộc Nhân và Yêu đang ngày đêm bố trí toàn núi.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1786"]},{"id":"nghenh-tien-cung","name":"Nghênh Tiên Cung","cn":"","capDo":"khac","parentId":"cuu-tien-son","blurb":"Cung điện bạch ngọc tại Cửu Tiên Sơn dùng để tiếp đãi tu sĩ Hợp Thể cùng môn nhân.","detail":"Cung điện cao khoảng ba đến bốn trăm trượng, có chừng mười tầng và nằm giữa hơn trăm lầu các. Mỗi tu sĩ Hợp Thể cùng môn nhân có thể độc chiếm một tầng với pháp trận truyền tống riêng, còn các lầu các xung quanh dành cho tu sĩ Luyện Hư. Khi Hàn Lập tới, Vạn Cốt chân nhân cùng môn hạ là đoàn Hợp Thể duy nhất đã cư trú tại đây.","theLucLienQuan":["Nhân tộc","Yêu tộc","Lực lượng Nhân - Yêu trấn thủ Cửu Tiên Sơn"],"nguon":["@c1786"]},{"id":"tang-thu-nam-nghenh-tien-cung","name":"Tầng thứ năm Nghênh Tiên Cung","cn":"","capDo":"khac","parentId":"nghenh-tien-cung","blurb":"Tầng thứ năm là nơi Hàn Lập chọn tạm trú trong Nghênh Tiên Cung.","detail":"Không gian tầng này gồm bình đài lộ thiên, đường hoa, linh thảo, hồ nuôi linh ngư năm màu, chính điện, đình viện và các thiên điện dành cho môn nhân đệ tử. Bầu trời cùng phần cảnh quan phía trên là cảnh tượng do cấm chế huyễn hóa.","theLucLienQuan":[],"nguon":["@c1787"]},{"id":"cung-dien-mau-do-nhu-san-ho","name":"Cung điện màu đỏ như san hô","cn":"","capDo":"khac","parentId":null,"blurb":"Cung điện hùng vĩ thuộc về Vạn Cốt chân nhân.","detail":"Hàn Lập tới nơi này gặp Vạn Cốt chân nhân và nghe ông giới thiệu về Hắc Vực trao đổi hội.","theLucLienQuan":["Bạch Cốt môn"],"nguon":["@c1788"]},{"id":"man-hoang","name":"Man hoang","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực rộng lớn mà Hàn Lập từng lưu lại trong thời gian dài do hoàn cảnh bắt buộc.","detail":"Trong hành trình tại Man hoang, Hàn Lập đã đi qua phạm vi gần nửa đại lục và liên tiếp gặp được những cơ duyên góp phần thúc đẩy tốc độ tiến cấp.","theLucLienQuan":[],"nguon":["@c1788"]},{"id":"hac-vuc","name":"Hắc Vực","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Địa điểm bí mật dùng để tổ chức Hắc Vực trao đổi hội.","detail":"Hắc Vực không cố định tại một nơi mà có thể tự động di chuyển trên bầu trời. Thời gian và phương thức tiến vào được những người tổ chức bí mật thông báo cho người tham dự.","theLucLienQuan":["Hắc Vực trao đổi hội","Những người tổ chức Hắc Vực trao đổi hội"],"nguon":["@c1788"]},{"id":"noi-o-cua-van-cot-chan-nhan","name":"Nơi ở của Vạn Cốt chân nhân","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Vạn Cốt chân nhân tiếp đãi Hàn Lập và bí mật hội kiến Hoa tiên tử.","detail":"Địa điểm này có truyền tống pháp trận dùng để đưa Hàn Lập rời đi. Sau khi hắn biến mất, Vạn Cốt chân nhân gặp Hoa tiên tử tại đây để bàn kế hoạch tập hợp tán tu Hợp Thể kỳ.","theLucLienQuan":["Bạch Cốt môn"],"nguon":["@c1789"]},{"id":"nui-thien-am","name":"Núi Thiên Âm","cn":"","capDo":"khac","parentId":null,"blurb":"Địa bàn gắn với Thiên Âm lão tổ.","detail":"Thiên Âm lão tổ ở núi Thiên Âm có một chút giao tình với Vạn Cốt chân nhân và được xem là mục tiêu có khả năng gia nhập kế hoạch liên kết tán tu Hợp Thể kỳ.","theLucLienQuan":[],"nguon":["@c1789"]},{"id":"thanh-huyen-vu","name":"Thành Huyền Vũ","cn":"","capDo":"thanh","parentId":null,"blurb":"Nơi Liễu Thanh từng theo Thiên Diệu Linh Hoàng tới làm khách và có cơ duyên nhìn thấy Tham Linh.","detail":"Tại Thành Huyền Vũ, Liễu Thanh từng chứng kiến Tham Linh lộ diện trong kỳ thôn thổ tinh hoa nhật nguyệt diễn ra ba nghìn năm một lần.","theLucLienQuan":[],"nguon":["@c1791"]},{"id":"thanh-tri-mau-den-tren-lung-cu-thu","name":"Thành trì màu đen trên lưng cự thú","cn":"","capDo":"thanh","parentId":null,"blurb":"Tòa thành lớn nằm trên phần lưng giống một mảnh lục địa của tọa kỵ Huyền Vũ Phách Hoàng.","detail":"Xung quanh thành trì có giáp sĩ mặc giáp đen và hơn một nghìn Lôi Vệ cưỡi lam sắc cự lang phòng vệ.","theLucLienQuan":["Lôi Vệ"],"nguon":["@c1791"]},{"id":"hac-son","name":"Hắc Sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Hình thái bất động của Cự quy mang Hắc thành sau khi thu đầu và tứ chi.","detail":"Hắc Sơn là ngọn núi đen do Cự quy của Huyền Vũ Phách Hoàng biến thành. Lôi Vệ và các giáp sĩ bố trí nhiều tầng pháp trận, cấm chế cùng sương mù đen quanh nơi này để che kín thành trì trên lưng cự quy.","theLucLienQuan":["Lôi Vệ"],"nguon":["@c1792"]},{"id":"cay-kinh-thien-thong-linh","name":"Cây Kình Thiên Thông Linh","cn":"","capDo":"khac","parentId":"thien-linh-thanh","blurb":"Cổ thụ thần kỳ gần Thiên Linh Thành, được dự tính kết hợp với hệ thống cấm chế của thành để chống lại Ma tộc.","detail":"Các thông đạo từ Ma giới xuất hiện gần cây Kình Thiên Thông Linh khiến khu vực Thiên Linh Thành có nguy cơ trở thành mục tiêu công kích trọng yếu. Mạc Giản Ly và Thánh Đảo dự định dựa vào sức mạnh của cổ thụ cùng cấm chế trong thành để tiêu hao đại quân Ma tộc.","theLucLienQuan":["Thánh Đảo","Ma tộc"],"nguon":["@c1793"]},{"id":"quang-han-gioi","name":"Quảng Hàn giới","capDo":"gioi-nho","parentId":null,"blurb":"Tiểu giới nơi Hàn Lập từng thu thập linh dược Tiên giới có thể luyện thành linh đan cho tu sĩ Hợp Thể kỳ.","detail":"Nơi Hàn Lập từng thu thập được một ít linh dược Tiên giới, có thể dùng luyện lượng lớn linh đan tinh tiến pháp lực.","nguon":["@c1794"]},{"id":"vu-hai-quan-dia-diem","name":"Vụ Hải Quan","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi bắt nguồn pháp khí cùng công pháp truyền thừa trong cơ thể Khí Linh Tử.","detail":"Khí Linh Tử được Hàn Lập định hướng kế thừa Vụ Hải nhất mạch và sau khi tu luyện đại thành có thể trở lại đảm nhiệm chức quan chủ tại đây.","theLucLienQuan":["Vụ Hải Quan"],"nguon":["@c1795"]},{"id":"bien-may-phi-tien-phong","name":"Biển mây Phi Tiên Phong","cn":"","capDo":"khac","parentId":"phi-tien-phong","blurb":"Biển mây rộng lớn được ngưng tụ trên đỉnh Phi Tiên Phong, bên trong có nhiều điện phủ phục vụ đại hội.","detail":"Biển mây nằm trên sơn đỉnh và được nối với vách núi bằng một cây cầu ngũ sắc dài hơn trăm trượng. Vạn Bảo Đại Điện cùng nhiều điện phủ khác tọa lạc trong khu vực này.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1796"]},{"id":"van-bao-dai-dien","name":"Vạn Bảo Đại Điện","cn":"","capDo":"khac","parentId":"bien-may-phi-tien-phong","blurb":"Đại điện nằm trong biển mây trên đỉnh Phi Tiên Phong, là nơi tổ chức cuộc đấu giá của đại hội.","detail":"Hàn Lập được lão giả Lôi Vệ dẫn tới một lối vào yên tĩnh của Vạn Bảo Đại Điện. Tại đây, hắn gặp Bành Quyết, hắc y phụ nhân và tử sam nữ tử.","theLucLienQuan":["Nhân tộc","Yêu tộc","Vạn Bảo đại hội"],"nguon":["@c1796"]},{"id":"cau-ngu-sac-phi-tien-phong","name":"Cầu ngũ sắc Phi Tiên Phong","cn":"","capDo":"khac","parentId":"phi-tien-phong","blurb":"Cây cầu hình vòm nối vách đá trên đỉnh Phi Tiên Phong với biển mây chứa quần thể điện phủ.","detail":"Cầu dài hơn trăm trượng và là lối đi để các tu sĩ thông thường tiến vào khu vực Vạn Bảo Đại Điện sau khi được đưa lên sơn đỉnh.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1796"]},{"id":"dai-bach-ngoc","name":"Đài Bạch Ngọc","cn":"","capDo":"khac","parentId":"thien-dien-dau-gia","blurb":"Đài cao hơn mười trượng nằm tại trung tâm thiên điện đấu giá, là nơi Huyền Vũ Phách Hoàng và Ly Hỏa Giao Vương chủ trì hội đấu giá.","detail":"Bốn góc đài được bố trí một bộ gồm bốn ngân sắc phi kiếm cấp linh bảo. Phía dưới còn có tám Kim Giáp lực sĩ không tỏa ra dao động pháp lực nhưng mang hắc sắc sát khí đáng sợ.","theLucLienQuan":["Vạn Bảo đại hội"],"nguon":["@c1797"]},{"id":"quy-tan-phong-tang-ba","name":"Quý tân phòng tầng ba","cn":"","capDo":"khac","parentId":"thien-dien-dau-gia","blurb":"Gian phòng riêng ở tầng ba thiên điện, dành cho khách quý và tu sĩ Hợp Thể kỳ dự hội đấu giá.","detail":"Hàn Lập, Hải Đại Thiếu và Khí Linh Tử được đưa vào một quý tân phòng tại đây. Phòng có cửa sổ phủ sương trắng nhưng vẫn cho phép nhìn rõ hội trường, cùng một pháp bàn đặt trên bàn gỗ xanh.","theLucLienQuan":["Vạn Bảo đại hội"],"nguon":["@c1797"]},{"id":"viem-vuc","name":"Viêm vực","cn":"","capDo":"khac","parentId":"hac-phuong-cung-dia-diem","blurb":"Khu vực nằm trong Hắc Phượng Cung, được dùng làm nơi trách phạt thành viên phạm lỗi.","detail":"Tiểu Hồng bị Tiêu Quán buộc diện bích tại viêm vực trong một nghìn năm vì tự tiện tham gia mưu tính của Diệp gia liên quan đến Thiên Phượng chân huyết.","theLucLienQuan":["Hắc Phượng tộc","Hắc Phượng Cung"],"nguon":["@c1797"]},{"id":"hac-phuong-cung-dia-diem","name":"Hắc Phượng Cung","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm gắn với Hắc Phượng tộc và Hắc Phượng Vương Tiêu Quán.","detail":"Bên trong Hắc Phượng Cung có viêm vực dùng để thi hành hình phạt. Tiểu Hồng bị giam tại đây để diện bích một nghìn năm.","theLucLienQuan":["Hắc Phượng tộc","Hắc Phượng Cung"],"nguon":["@c1797"]},{"id":"bach-bich-hap-coc","name":"Bạch Bích Hạp Cốc","cn":"","capDo":"vuc","parentId":null,"blurb":"Hẻm cốc nằm ở cực đông thuộc Vu nhân tộc và chịu sự kiểm soát trực tiếp của Huyền Vũ Thành. Nơi đây có sản lượng Ngân Ti Tinh cực thấp.","detail":"Bạch Bích Hạp Cốc là nguồn khai thác Ngân Ti Tinh quý hiếm. Do sản lượng rất ít, phần lớn vật liệu thu được đều do Huyền Vũ Thành sử dụng.","theLucLienQuan":["Huyền Vũ Thành","Vu nhân tộc"],"nguon":["@c1798"]},{"id":"dong-phu-trong-ngon-nui-nho","name":"Động phủ trong ngọn núi nhỏ","cn":"","capDo":"khac","parentId":"nui-hoang-cach-xa-cuu-tien-son","blurb":"Động phủ nơi phu phụ Hắc mi lão giả giữ Khí Linh Tử trước khi đưa hắn tới Cửu Tiên Sơn.","detail":"Hàn Lập và Hải Đại Thiếu tìm tới động phủ sau khi đối phương đã rời đi. Tại đây Hàn Lập chờ tiêu ký thần niệm trong cơ thể đệ tử phản ứng mạnh để xác định hướng truy đuổi.","theLucLienQuan":[],"nguon":["@c1803"]},{"id":"tang-thu-chin-nghenh-tien-cung","name":"Tầng thứ chín Nghênh Tiên cung","cn":"","capDo":"khac","parentId":"nghenh-tien-cung","blurb":"Khu vực do Lũng gia sử dụng trong Nghênh Tiên cung và là nơi Khí Linh Tử được xác nhận đã bị đưa tới.","detail":"Tầng chín được nhiều lớp cấm chế bảo vệ, gồm cả cấm chế không gian trên vách tường. Không gian bên trong có rừng cây và đang tập trung lão tổ, gia chủ cùng nhiều trưởng lão của Lũng gia.","theLucLienQuan":["Lũng gia"],"nguon":["@c1804"]},{"id":"rung-cay-trong-tang-chin","name":"Rừng cây trong tầng chín","cn":"","capDo":"khac","parentId":"tang-thu-chin-nghenh-tien-cung","blurb":"Khu rừng nằm trong không gian phía sau vách cấm chế của tầng chín Nghênh Tiên cung.","detail":"Hàn Lập xuất hiện dưới một cây cổ thụ xanh lớn tại đây sau khi xuyên qua cấm chế không gian. Hai đệ tử Lũng gia có mặt trong khu rừng đã bắt gặp hắn.","theLucLienQuan":["Lũng gia"],"nguon":["@c1804"]},{"id":"thanh-tri-lung-gia","name":"Thành trì Lũng gia","cn":"","capDo":"thanh","parentId":null,"blurb":"Thành trì thuộc Lũng gia, được tường cao và cấm chế sương mù bảo vệ.","detail":"Tường thành cao hơn mười trượng, bên trong có nhiều lầu các, đình đài và một tòa kim tháp cao vài trăm trượng ở khu vực trung tâm. Hàn Lập dùng mây xám xuyên qua cấm chế rồi bí mật vượt tường vào thành.","theLucLienQuan":["Lũng gia"],"nguon":["@c1805"]},{"id":"kim-thap-trung-tam-lung-gia","name":"Kim tháp trung tâm Lũng gia","cn":"","capDo":"khac","parentId":"thanh-tri-lung-gia","blurb":"Tòa kim tháp cao lớn nằm tại trung tâm thành trì Lũng gia.","detail":"Lũng gia lão tổ cùng các trưởng lão Luyện Hư, trận pháp đại sư và luyện khí đại sư tập trung tại đây để nghiên cứu bức vẽ Kình Thiên chiến thuyền.","theLucLienQuan":["Lũng gia"],"nguon":["@c1805"]},{"id":"tru-so-lung-gia","name":"Trụ sở Lũng gia","cn":"","capDo":"khac","parentId":"thanh-tri-lung-gia","blurb":"Khu vực trung tâm do Lũng gia kiểm soát và có lão tổ tọa trấn.","detail":"Kim Mao Cự Viên lẻn vào nơi này để bắt Khí Linh Tử, dẫn tới cuộc truy đuổi và giao chiến với Lũng gia lão tổ.","theLucLienQuan":["Lũng gia"],"nguon":["@c1806"]},{"id":"toa-thap-lon-toa-anh-vang","name":"Tòa tháp lớn tỏa ánh vàng","cn":"","capDo":"khac","parentId":"tru-so-lung-gia","blurb":"Tòa tháp lớn nằm trong khu vực của Lũng gia.","detail":"Một đạo tử quang của Lũng gia lão tổ bắn ra từ đỉnh tháp để truy đuổi Kim Mao Cự Viên đang mang Khí Linh Tử bỏ chạy.","theLucLienQuan":["Lũng gia"],"nguon":["@c1806"]},{"id":"bien-suong-mu-mau-trang-ngoai-thanh","name":"Biển sương mù màu trắng ngoài thành","cn":"","capDo":"khac","parentId":"thanh-tri-lung-gia","blurb":"Biển sương trắng nằm bên ngoài thành của Lũng gia.","detail":"Nơi Kim Mao Cự Viên và Lũng gia lão tổ giao chiến bằng linh áp cùng nhục thân. Dư ba tử kim quét sạch một vùng sương mù và khiến tu sĩ Lũng gia không dám tiến vào.","theLucLienQuan":["Lũng gia"],"nguon":["@c1806"]},{"id":"thanh-dao","name":"Thánh đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Thánh địa chung của Nhân–Yêu hai tộc, định kỳ tiếp nhận những người có tư chất siêu phàm.","detail":"Thánh đảo được cho là có khoảng hai mươi đến ba mươi tồn tại Hợp Thể, chỉ điều động họ khi lưỡng tộc gặp nguy cơ tồn vong. Nơi đây còn được đồn có Kim Cương Yêu Viên nhất tộc bảo hộ quanh năm.","theLucLienQuan":["Thánh đảo","Kim Cương Yêu Viên nhất tộc"],"nguon":["@c1807","@c1887","@c1940","@c2006"]},{"id":"thanh-mieu","name":"Thánh Miếu","cn":"","capDo":"khac","parentId":null,"blurb":"Thánh địa của Linh tộc, có địa vị tương tự Thánh đảo đối với Nhân–Yêu hai tộc.","detail":"Thiên Thu Thánh nữ không biết hiện tại Thánh Miếu có bao nhiêu tồn tại cấp Thánh Linh.","theLucLienQuan":["Linh tộc"],"nguon":["@c1807"]},{"id":"tien-cung","name":"Tiên cung","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực có cấm chế phòng hộ từng bị ngân sắc hỏa diễm của Kim mao Cự viên xuyên thủng.","detail":"Sau khi Kim mao Cự viên trốn thoát, các thủ vệ không thể đuổi kịp nên phải quay lại tu bổ phần cấm chế bị tổn hại.","theLucLienQuan":["Lũng gia"],"nguon":["@c1807"]},{"id":"me-thien-lau","name":"Mê Thiên Lâu","cn":"","capDo":"khac","parentId":"cuu-tien-son","blurb":"Hiệu buôn tại phường thị Cửu Tiên Sơn, chuyên cung cấp Mê Thiên thạch dùng cho ảo ảnh trận pháp.","detail":"Bề ngoài Mê Thiên Lâu khá thấp bé, nhưng phần lớn kiến trúc gồm năm sáu tầng nằm dưới lòng đất. Nơi đây có nhiều Yêu tu qua lại và có thể cung cấp cả Mê Thiên thạch đỉnh giai với số lượng lớn.","theLucLienQuan":["Yêu tộc"],"nguon":["@c1808"]},{"id":"diem-pho-cua-thien-ho-nhat-toc","name":"Điếm phô của Thiên Hồ Nhất Tộc","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Cửa hàng của Thiên Hồ Tộc tại Thiên Uyên Thành, nơi Hàn Lập gặp tỷ muội Tần thị.","detail":"Bên trong điếm có các pháp trận đặc biệt giúp tăng gấp bội uy lực của huyễn thuật và mê mị thuật. Hàn Lập hoàn tất giao dịch tài liệu yêu thú với Tần Tố Nhi và Mị Linh tại đây.","theLucLienQuan":["Thiên Hồ Tộc"],"nguon":["@c1809"]},{"id":"hac-vuc-dai-hoi","name":"Hắc Vực đại hội","cn":"","capDo":"khac","parentId":"hac-vuc","blurb":"Hội trao đổi tại Hắc Vực mà Tần Tố Nhi vừa nhận được thiếp mời tham dự.","detail":"Tần Tố Nhi dự định mang một bảo vật nguy hiểm mà tỷ muội nàng vất vả lấy được tới đây để thử đổi lấy vật phẩm tốt hơn. Việc để lộ tin tức về món đồ có thể dẫn tới họa sát thân.","theLucLienQuan":["Thiên Hồ Tộc"],"nguon":["@c1809","@c1816"]},{"id":"ngon-nui-nho-gan-nghenh-tien-cung","name":"Ngọn núi nhỏ gần Nghênh Tiên Cung","cn":"","capDo":"khac","parentId":null,"blurb":"Một đỉnh núi nhỏ vắng người nằm gần Nghênh Tiên Cung. Đây là nơi Hàn Lập và Vạn Cốt Chân Nhân hội hợp trước khi tiến vào Hắc Vực.","detail":"Sáng hôm sau cuộc gặp Đại Nhi, Hàn Lập lặng lẽ rời chỗ ở và đến ngọn núi nhỏ này. Vạn Cốt Chân Nhân chờ tại đây để chuẩn bị cùng hắn lên đường và dặn dò những điều cần lưu ý trong Hắc Vực.","theLucLienQuan":[],"nguon":["@c1810"]},{"id":"son-coc-hoang-vang-ngoai-cuu-tien-son","name":"Sơn cốc hoang vắng ngoài Cửu Tiên Sơn","cn":"","capDo":"khac","parentId":"cuu-tien-son","blurb":"Một điểm chờ dẫn vào Hắc Vực nằm bên ngoài Cửu Tiên Sơn.","detail":"Hàn Lập, Vạn Cốt chân nhân và ba người che giấu thân phận tập hợp tại sơn cốc này. Khi năm tấm Khiên Dẫn Lệnh phát sáng, cánh cửa bạc dẫn vào Hắc Vực xuất hiện trên không trung.","theLucLienQuan":["Hắc Vực đại hội"],"nguon":["@c1811"]},{"id":"khien-dan-chi-mon","name":"Khiên Dẫn chi môn","cn":"","capDo":"khac","parentId":"son-coc-hoang-vang-ngoai-cuu-tien-son","blurb":"Cánh cửa bạc khổng lồ dùng để tiếp dẫn người mang Khiên Dẫn Lệnh vào Hắc Vực.","detail":"Cánh cửa cao hơn mười trượng, mang hoa văn cổ xưa và phù văn bạc. Nó được ngưng tụ từ vô số hồ quang trong mây đen, mở ra dưới tác động của pháp khí do Khiên Dẫn sứ giả sử dụng rồi biến mất sau khi mọi người đi qua.","theLucLienQuan":["Hắc Vực đại hội"],"nguon":["@c1811"]},{"id":"khong-gian-phia-duoi-bien-hac-khi","name":"Không gian phía dưới biển hắc khí","cn":"","capDo":"gioi-nho","parentId":"hac-vuc","blurb":"Không gian bí mật nằm sâu hơn mấy vạn trượng bên dưới biển hắc khí của Hắc Vực.","detail":"Khu vực được chiếu sáng bởi hơn mười quang cầu lam sắc lơ lửng, có rừng cột đá đen và quần thể kiến trúc mang phong cách man hoang thượng cổ. Hắc Vực đại điện là công trình nổi bật trong không gian này.","theLucLienQuan":["Hắc Vực"],"nguon":["@c1812"]},{"id":"hac-vuc-dai-dien","name":"Hắc Vực đại điện","cn":"","capDo":"khac","parentId":"khong-gian-phia-duoi-bien-hac-khi","blurb":"Đại điện đồ sộ dùng để tiếp đón khách tham dự Trao đổi đại hội của Hắc Vực.","detail":"Công trình cao hơn ngàn trượng, chiếm diện tích vài dặm trên một ngọn núi đen. Khiên Dẫn sứ giả đưa khách tới đây trước khi giao họ cho đội hắc sa thị nữ.","theLucLienQuan":["Hắc Vực"],"nguon":["@c1812"]},{"id":"quang-truong-truoc-hac-vuc-dai-dien","name":"Quảng trường trước Hắc Vực đại điện","cn":"","capDo":"khac","parentId":"hac-vuc-dai-dien","blurb":"Khu vực tiếp đón khách nằm trước Hắc Vực đại điện.","detail":"Các hắc sa thị nữ xếp thành hai hàng tại quảng trường để nghênh đón, phân luồng và bố trí người phục vụ khách dự Trao đổi đại hội.","theLucLienQuan":["Hắc Vực"],"nguon":["@c1812"]},{"id":"hoi-truong-trao-doi-dai-hoi","name":"Hội trường Trao đổi đại hội","cn":"","capDo":"khac","parentId":"hac-vuc-dai-dien","blurb":"Hội trường hư không dùng làm nơi tiến hành Trao đổi đại hội tại Hắc Vực.","detail":"Khoảng năm sáu trăm thạch đình lơ lửng bao quanh ngọc đài trung tâm, dù khi Hàn Lập tới mới chỉ có vài chục đình có người. Trung tâm hội trường có quầng sáng trắng ngà, các cột đá hồng lam, một pháp trận màu vàng và hai bàn đá đen trắng.","theLucLienQuan":["Hắc Vực"],"nguon":["@c1812"]},{"id":"bi-dia-di-toc-man-hoang","name":"Bí địa dị tộc man hoang","cn":"","capDo":"khac","parentId":null,"blurb":"Di tích của một dị tộc man hoang đã tuyệt diệt, nơi Hắc Vực tìm được Tề Thiên La. Văn tự và công pháp còn lại tại đây giúp xác định lai lịch của bộ trấn tộc chi bảo.","detail":"Bí địa lưu giữ Tề Thiên La bị hư tổn, văn tự ghi rằng bảo vật vốn ghép bộ với Chấn Thiên Chùy và một thiên công pháp dành cho luyện thể sĩ. Hắc Vực không tìm thấy Chấn Thiên Chùy chính phẩm tại nơi này.","theLucLienQuan":["Hắc Vực","Dị tộc man hoang đã tuyệt diệt"],"nguon":["@c1814"]},{"id":"dai-dien-trao-doi-cua-hac-vuc","name":"Đại điện trao đổi của Hắc Vực","cn":"","capDo":"khac","parentId":"hac-vuc","blurb":"Đại điện nơi các tu sĩ tham dự đại hội Hắc Vực tiến hành tranh đổi bảo vật.","detail":"Các tu sĩ ngồi trong những phi đình bố trí quanh đài cao và bị hạn chế thần niệm. Nơi đây chứng kiến phần bảo vật của Hắc Vực kết thúc rồi chuyển sang trao đổi tự do.","theLucLienQuan":["Hắc Vực"],"nguon":["@c1817"]},{"id":"dai-ngoc","name":"Đài ngọc","cn":"","capDo":"khac","parentId":"dai-dien-trao-doi-cua-hac-vuc","blurb":"Khu vực trung tâm dùng để triển lãm vật phẩm trong giai đoạn trao đổi tự do.","detail":"Đài được màn hào quang bảo vệ và mỗi lượt chỉ cho tối đa ba người tiến vào. Màn bảo hộ từng tự phát sáng để đối kháng nhiệt lực từ ba đạo Kim Ô chân hỏa.","theLucLienQuan":["Hắc Vực"],"nguon":["@c1817"]},{"id":"dau-gia-dai-dien","name":"Đấu giá đại điện","cn":"","capDo":"khac","parentId":"hac-vuc-dai-hoi","blurb":"Đại điện nơi các khách tham dự Hắc Vực đại hội tiến hành trao đổi kỳ trân.","detail":"Nghiệt Vân và Tịnh Minh Đan cùng xuất hiện tại đây. Diện tích đại điện được nhận định là không đủ để thả ra toàn bộ ngàn vạn thú hồn chứa trong Nghiệt Vân.","theLucLienQuan":["Hắc Vực"],"nguon":["@c1818"]},{"id":"vong-quy-phong","name":"Vọng Quy Phong","cn":"","capDo":"khac","parentId":"thien-nguyen-canh","blurb":"Ngọn núi hẻo lánh được Cốc gia chọn làm nơi gặp vị Hợp Thể trợ quyền. Gần trăm tu sĩ của gia tộc tập trung tại đỉnh núi để chờ người được hẹn.","detail":"Cốc gia bố trí phòng hộ quanh đỉnh Vọng Quy Phong trong lúc chờ đợi. Sau hai canh giờ, một đạo thanh hồng đưa một thanh niên áo xanh và một nữ đồng tới nơi.","theLucLienQuan":["Cốc gia","Chân linh thế gia"],"nguon":["@c1822"]},{"id":"linh-dong","name":"Linh động","cn":"","capDo":"gioi-nho","parentId":"thien-nguyen-canh","blurb":"Địa điểm hoặc không gian mà đệ tử các Chân linh thế gia có thể tiến vào. Số suất của mỗi gia tộc phụ thuộc vào thứ hạng tại Chân linh đại điển.","detail":"Quyền tiến vào linh động là một trong những lợi ích quan trọng khiến các Chân linh thế gia coi trọng kết quả đại điển.","theLucLienQuan":["Chân linh thế gia","Cốc gia"],"nguon":["@c1822"]},{"id":"van-linh-dai","name":"Vạn Linh Đài","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm tổ chức Chân Linh đại điển.","detail":"Vạn Linh Đài cách nơi đoàn Cốc gia hội hợp hơn một tuần trăng di chuyển. Hiểu Phong tiên tử và Tiêu trưởng lão dẫn đoàn tới đây sau khi Hàn Lập nhận lời làm khách khanh.","theLucLienQuan":["Cốc gia","Chân linh thế gia"],"nguon":["@c1823"]},{"id":"thien-ma-hoang-nguyen","name":"Thiên Mã hoang nguyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Phế linh chi địa rộng lớn nằm giữa Thiên Nguyên Cảnh và Vạn Diệu Cảnh.","detail":"Hoang nguyên đầy cát vàng, không có cây cỏ và rộng đến mức một tu sĩ Hóa Thần phải phi độn liên tục hơn một tuần trăng mới vượt qua. Tuyết Bạch Ngô Công đã tiêu diệt một đoàn hơn mười tu sĩ tại đây.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1823"]},{"id":"phong-nguyen-dai-luc","name":"Phong Nguyên đại lục","cn":"","capDo":"chau","parentId":null,"blurb":"Đại lục rộng lớn có nhiều loại cổ thú mang thuộc tính âm hàn.","detail":"Lục Dực xem Phong Nguyên đại lục là vùng đất đủ rộng lớn để tìm kiếm các loại cổ thú âm hàn cần cho kế hoạch tu luyện hướng tới Chân Linh chi thể.","theLucLienQuan":[],"nguon":["@c1825"]},{"id":"di-gioi-cua-van-linh","name":"Dị giới của Vạn Linh","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Thế giới nơi bản thể cấp Chân Linh của Vạn Linh đại nhân tồn tại.","detail":"Bản thể Vạn Linh không trực tiếp xuất hiện tại Vạn Linh Đài. Nó chỉ phân ra một luồng phân niệm, hình thành hóa thân và cách giới hàng lâm theo nghi thức triệu gọi.","theLucLienQuan":[],"nguon":["@c1827"]},{"id":"chan-linh-dai-dien","name":"Chân Linh đại điển","cn":"","capDo":"khac","parentId":null,"blurb":"Đại điển của các Chân Linh thế gia, nơi đệ tử và tu sĩ tham dự tỷ thí.","detail":"Trong kỳ đại điển này, những người tham dự được chứng kiến Lũng gia lão tổ, một tu sĩ Hợp Thể hậu kỳ, trực tiếp lên Vạn Linh Đài giao đấu với Hàn Lập.","theLucLienQuan":["Chân Linh thế gia","Lũng gia","Phong gia","Cốc gia"],"nguon":["@c1830"]},{"id":"van-linh-dien","name":"Vạn Linh Điện","cn":"","capDo":"khac","parentId":"van-linh-coc","blurb":"Điện phủ nằm trên vách núi trong Vạn Linh Cốc.","detail":"Vạn Linh Điện từng là nơi các gia chủ và trưởng lão thương lượng khi Chân Linh Đại Điển bắt đầu. Vào ban đêm sau khi đại điển kết thúc, toàn bộ thủ vệ tại đây bị rút đi để phục vụ cuộc thương nghị bí mật liên quan đến Ma Kiếp và cơ hội tiến vào Đại Thừa.","theLucLienQuan":["Lũng gia"],"nguon":["@c1833"]},{"id":"thien-dien-bi-mat-trong-van-linh-dien","name":"Thiên điện bí mật trong Vạn Linh Điện","cn":"","capDo":"khac","parentId":"van-linh-dien","blurb":"Thiên điện được dùng làm nơi tổ chức cuộc thương nghị bí mật.","detail":"Bên trong thiên điện có một thạch bàn lớn và ba vị khách đã ngồi chờ trước khi Hàn Lập được Huy trưởng lão dẫn vào.","theLucLienQuan":["Lũng gia"],"nguon":["@c1833"]},{"id":"van-linh-coc","name":"Vạn Linh Cốc","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc được dùng làm địa điểm tổ chức Chân Linh Đại Điển.","detail":"Sau khi Chân Linh Đại Điển kết thúc, một số thế gia rời đi nhưng phần lớn tiếp tục lưu lại Vạn Linh Cốc vài ngày để trao đổi tài nguyên và tâm đắc công pháp. Cốc gia dựng nơi ở tạm trong cốc cho người của mình và khách tham dự.","theLucLienQuan":["Cốc gia","Lũng gia","Ngũ đại Chân Linh thế gia"],"nguon":["@c1833"]},{"id":"van-bao-dai-hoi","name":"Vạn Bảo đại hội","cn":"","capDo":"khac","parentId":null,"blurb":"Hội đấu giá nơi Thiên Thu Thánh Nữ từng xuất hiện.","detail":"Thái thượng trưởng lão Lâm gia từng thấy Thiên Thu Thánh Nữ tại đây nên nhận ra nàng khi nàng hiện thân trong thiên điện.","theLucLienQuan":["Nhân tộc","Linh Tộc"],"nguon":["@c1834"]},{"id":"tam-hoang-that-yeu","name":"Tam Hoàng Thất Yêu","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Phạm vi gồm các lãnh địa lớn của Nhân tộc và Yêu tộc mà Hàn Lập lựa chọn để du hành.","detail":"Hàn Lập dự định đi khắp khu vực này để hỏi thăm một nữ nhân có thể đã phi thăng Linh giới, đồng thời tôi luyện tu vi và tâm cảnh sau khi tiến giai Hợp Thể.","theLucLienQuan":["Nhân tộc","Yêu tộc","Tam Hoàng"],"nguon":["@c1837"]},{"id":"lanh-dia-that-yeu","name":"Lãnh địa Thất Yêu","cn":"","capDo":"vuc","parentId":"tam-hoang-that-yeu","blurb":"Khu vực thuộc các thế lực Yêu tộc trong phạm vi Tam Hoàng Thất Yêu.","detail":"Sau khi tin tức về Hàn Lập biến mất khỏi Nhân tộc, từng xuất hiện lời đồn rằng hắn có mặt tại một số phường thị trong lãnh địa Thất Yêu.","theLucLienQuan":["Yêu tộc"],"nguon":["@c1837"]},{"id":"khu-vuc-nhan-toc","name":"Khu vực Nhân tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực cư trú và hoạt động của các thế lực Nhân tộc, đang chuyển sang trạng thái chuẩn bị Ma kiếp.","detail":"Trong hơn trăm năm, dân cư, tu sĩ, thế gia và các thành thị từng bước di chuyển, xây dựng phòng tuyến, huấn luyện lực lượng và tích trữ trang bị.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1838"]},{"id":"phuong-thi-thien-uyen-thanh","name":"Phường thị Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Khu giao thương có nguồn tài liệu dồi dào tại Thiên Uyên Thành.","detail":"Bạch Quả Nhi thường tới đây mua bán tài liệu, còn Hồ lão đệ từng tìm được một mảnh Tử Kim Thiết tại một cửa tiệm nhỏ trong phường thị.","theLucLienQuan":["Thiên Uyên Thành","Nhân tộc","Yêu tộc"],"nguon":["@c1838"]},{"id":"dai-dien-giao-dich-nhan-yeu","name":"Đại điện giao dịch của phường thị Nhân–Yêu","cn":"","capDo":"khac","parentId":"phuong-thi-thien-uyen-thanh","blurb":"Địa điểm giao dịch nơi người tham gia có thể che giấu thân phận.","detail":"Hơn trăm tu sĩ đang giao dịch trong đại sảnh khi Bạch Quả Nhi tới gặp Tần Tố Nhi và hoàn thành cuộc trao đổi tài liệu thay Hàn Lập.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1838"]},{"id":"son-mach-linh-khi-nong-dam","name":"Sơn mạch linh khí nồng đậm","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn mạch có linh khí dị thường nồng đậm, nằm tại điểm cuối hành trình hai tháng của Bạch Quả Nhi.","detail":"Sau khi rời Thiên Uyên Thành, Bạch Quả Nhi trở về theo đường cũ và hạ xuống đỉnh một ngọn núi sâu trong sơn mạch. Chương chưa xác nhận nơi đây có phải chỗ Hàn Lập bế quan hay không.","theLucLienQuan":[],"nguon":["@c1838"]},{"id":"tieu-the-gioi-trong-long-nui","name":"Tiểu thế giới trong lòng núi","cn":"","capDo":"gioi-nho","parentId":"dong-phu-han-lap","blurb":"Không gian rộng lớn nằm sâu sau nhiều tầng cấm chế của động phủ Hàn Lập.","detail":"Tiểu thế giới được biến thành một thảo nguyên có mây trắng, hoa cỏ và linh khí dồi dào. Bên trong có hai ngọn tiểu sơn cùng một lầu các bạch ngọc ba tầng; khi Hàn Lập bắt đầu bế quan, toàn bộ không gian bị pháp trận biến thành biển sương ngũ sắc.","theLucLienQuan":[],"nguon":["@c1839"]},{"id":"lau-cac-bach-ngoc","name":"Lầu các bạch ngọc","cn":"","capDo":"khac","parentId":"tieu-the-gioi-trong-long-nui","blurb":"Tòa lầu ba tầng nằm giữa hai ngọn tiểu sơn trong tiểu thế giới.","detail":"Lầu các được hào quang ngũ sắc bảo vệ. Bản thể Hàn Lập ngồi tại tầng một, trước kim sắc cự đỉnh chứa chất lỏng thần bí ngũ sắc.","theLucLienQuan":[],"nguon":["@c1839"]},{"id":"hai-ngon-tieu-son","name":"Hai ngọn tiểu sơn","cn":"","capDo":"khac","parentId":"tieu-the-gioi-trong-long-nui","blurb":"Hai ngọn núi nhỏ cao hơn trăm trượng, một màu đen và một màu xanh biếc.","detail":"Mỗi đỉnh núi có một thân ảnh mang dung mạo giống Hàn Lập ngồi vận công. Đây cũng là hai vị trí phát động quang trận phong ấn tiểu thế giới.","theLucLienQuan":[],"nguon":["@c1839"]},{"id":"khu-vuc-nhan-yeu-hai-toc","name":"Khu vực Nhân Yêu hai tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Phạm vi hoạt động của Nhân tộc và Yêu tộc, nơi Hàn Lập từng du ngoạn trong thời gian nghiên cứu Vạn Độc Hỗn Nguyên Thân.","detail":"Hàn Lập nghiên cứu thấu triệt Vạn Độc Hỗn Nguyên Thân trong thời gian du ngoạn khu vực Nhân Yêu hai tộc. Các tài liệu kịch độc cần cho ba tầng cuối của luyện thể thuật này rất khó tìm trong phạm vi đó.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1840"]},{"id":"cung-dien-duoi-bien","name":"Cung điện dưới biển","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Một cung điện lớn nằm dưới biển, bên trong có mật thất bí ẩn.","detail":"Mật thất của cung điện chứa một kén đỏ như máu với vô số tơ máu. Trong kén có hắc ảnh lưu chuyển và phát ra nhịp đập trầm đục như trái tim.","theLucLienQuan":[],"nguon":["@c1842"]},{"id":"hai-vuc-co-ngan-trieu","name":"Hải vực có Ngân Triều","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Vùng biển xanh nơi các Phi Linh nhân trẻ tuổi tiến hành thí luyện.","detail":"Nhóm thí luyện bất ngờ gặp thiên tai Ngân Triều, bị vòi rồng mang điện hồ bạc truy đuổi và phải lập trận chống đỡ.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1842"]},{"id":"dia-uyen","name":"Địa Uyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực từng do nhiều đại yêu vương chiếm giữ. Sau khi các yêu vương đột nhiên mất tích, các tộc Phi Linh đã liên thủ công chiếm toàn bộ nơi này.","detail":"Địa Uyên là địa điểm gắn với một trong những biến động nổi danh nhất của Phi Linh tộc trong vài trăm năm gần đây. Nguyên nhân các đại yêu vương đồng loạt biến mất chưa được giải thích trong chương này.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1843","@c1845"]},{"id":"hai-vuc-gan-phi-linh-toc","name":"Hải vực gần Phi Linh tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển gần lãnh địa Phi Linh tộc, nơi Hàn Lập tới sau hành trình hơn tám mươi năm. Nhóm đệ tử Ngũ Sắc, Bạch Ngọc và Thiên Bằng tiến hành thí luyện tại đây.","detail":"Hải vực này xuất hiện Ngân triều ngàn năm một lần và trở thành hiểm địa đối với nhóm đệ tử Phi Linh. Sau khi được cứu, cả nhóm quyết định lập tức rời đi vì lo thiên tai quay lại.","theLucLienQuan":["Phi Linh tộc","Thiên Bằng tộc","Ngũ Sắc tộc","Bạch Ngọc tộc"],"nguon":["@c1843"]},{"id":"ngan-trieu","name":"Ngân triều","cn":"","capDo":"khac","parentId":"hai-vuc-gan-phi-linh-toc","blurb":"Thiên tai biển hình thành từ cơn lốc, điện hồ, thạch băng và thiên địa nguyên khí hỗn loạn. Tu sĩ dưới Hóa Thần gần như không thể sống sót khi bị cuốn vào.","detail":"Ngân triều xuất hiện khoảng ngàn năm một lần tại hải vực gần Phi Linh tộc. Hóa Thần tu sĩ cũng chỉ có thể miễn cưỡng tự bảo vệ, còn việc cứu cả một nhóm người cần thực lực ít nhất đạt Luyện Hư hậu kỳ đại thành hoặc Hợp Thể.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1843"]},{"id":"thanh-thanh-thien-bang","name":"Thánh Thành Thiên Bằng","cn":"","aliases":["Thiên Bằng Thánh Thành","Thánh Thành Thiên Bằng Tộc","Thánh Thành"],"capDo":"thanh","parentId":null,"blurb":"Trung tâm của Thiên Bằng tộc và nơi có nhiều trưởng lão Hợp Thể trấn giữ.","detail":"Hàn Lập đến bên ngoài Thánh Thành Thiên Bằng dưới hình thái Thanh Bằng khổng lồ, phô bày khí tức Thiên Bằng tinh thuần khiến các trưởng lão trong thành phải ra xem xét. Sau khi hiện chân thân và nói rõ có việc cần trao đổi, hắn được Kim Duyệt đích thân mời vào thành.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1844"]},{"id":"tang-sau-nhat-dia-uyen","name":"Tầng sâu nhất Địa Uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Khu vực bí ẩn và được canh giữ nghiêm ngặt nhất trong Địa Uyên.","detail":"Một khoáng mạch quý hiếm có trữ lượng lớn được phát hiện tại đây khoảng trăm năm trước. Việc tranh ngừa khai thác riêng khiến toàn Địa Uyên bị đặt vào trạng thái nửa phong bế, còn trưởng lão các tộc cũng không thể tùy tiện tiến vào.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1846"]},{"id":"khong-gian-an-cu-cua-thanh-nguyen-tu","name":"Không gian ẩn cư của Thanh Nguyên Tử","cn":"","capDo":"gioi-nho","parentId":"tang-ba-dia-uyen","blurb":"Không gian khác nơi Thanh Nguyên Tử ẩn cư.","detail":"Lối tiến vào không gian này liên quan đến một tọa độ tại tầng ba Địa Uyên. Hàn Lập trở lại để thực hiện ước định với Thanh Nguyên Tử.","theLucLienQuan":[],"nguon":["@c1846"]},{"id":"dai-thanh-tran-thu-dia-uyen","name":"Đại thành trấn thủ Địa Uyên","cn":"","capDo":"thanh","parentId":"dia-uyen","blurb":"Thành trì kiểm soát lối ra vào Địa Uyên, có tường thành màu xanh, nhiều kiến trúc hình trụ và các đội thủ vệ tuần tra.","detail":"Bên trong thành có pháp trận tỏa ngân quang dẫn xuống Địa Uyên. Đoàn Kim Duyệt phải xuất trình ngọc bài tại cửa thành rồi tiếp tục qua sự kiểm tra của Kim Phong trước khi được tiến vào.","theLucLienQuan":["Lực lượng thủ vệ Địa Uyên","Thiên Bằng tộc"],"nguon":["@c1847"]},{"id":"khoang-mo-sau-trong-dia-uyen","name":"Khoáng mỏ sâu trong Địa Uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Khoáng mỏ nằm sâu trong Địa Uyên, nơi khai thác và cất giữ nhiều quáng thạch quý hiếm.","detail":"Một kẻ có thần thông cao cường lợi dụng lúc Tần trưởng lão vắng mặt để cướp sạch số quáng thạch tích lũy trong nhiều năm. Nhiều thủ vệ tại đây bị giết hoặc đánh bị thương trước khi thủ phạm trốn đi.","theLucLienQuan":["Lực lượng thủ vệ Địa Uyên"],"nguon":["@c1847"]},{"id":"lan-doc-dam-lay","name":"Lan Độc đầm lầy","cn":"","capDo":"khac","parentId":"tang-thu-nhat-cua-dia-uyen","blurb":"Đầm lầy phủ sương lục nhạt nằm tại tầng thứ nhất của Địa Uyên.","detail":"Khu vực có độc khí, hoa lan kịch độc và đàn Độc Phong. Từ đây tới cửa xuống tầng hai mất khoảng nửa ngày đường.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1848"]},{"id":"ngon-nui-hinh-chu-nhan","name":"Ngọn núi hình chữ Nhân","cn":"","capDo":"khac","parentId":"tang-thu-nhat-cua-dia-uyen","blurb":"Ngọn núi xám trắng trọc lóc đánh dấu lối xuống tầng thứ hai của Địa Uyên.","detail":"Sườn núi bị chẻ thành hình chữ Nhân và vị trí của nó được ghi trên địa đồ do Kim Duyệt sử dụng.","theLucLienQuan":["Phi Linh tộc","Chấp pháp đội"],"nguon":["@c1848"]},{"id":"tang-thu-nhat-cua-dia-uyen","name":"Tầng thứ nhất của Địa Uyên","cn":"","capDo":"vuc","parentId":"dia-uyen","blurb":"Tầng đầu tiên bên trong Địa Uyên, nơi có Lan Độc đầm lầy.","detail":"Yêu vật cấp thấp tại tầng này phần lớn đã bị Phi Linh nhân càn quét. Đoàn Hàn Lập vượt qua tầng này để tới cửa xuống tầng hai.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1848"]},{"id":"tang-thu-hai-cua-dia-uyen","name":"Tầng thứ hai của Địa Uyên","cn":"","capDo":"vuc","parentId":"dia-uyen","blurb":"Tầng thứ hai của Địa Uyên, đích đến của Hàn Lập, Kim Duyệt và Lôi Lan.","detail":"Đường ra vào tầng này đang bị chấp pháp đội phong tỏa vì kẻ cướp khoáng mạch có thể lẩn trốn tại các tầng sâu hơn.","theLucLienQuan":["Phi Linh tộc","Chấp pháp đội"],"nguon":["@c1848"]},{"id":"khoang-mach-dia-uyen","name":"Khoáng mạch Địa Uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Khu khoáng mạch do các nhánh Phi Linh tộc cùng chia lợi ích trên danh nghĩa.","detail":"Phần lớn sản lượng thực tế thuộc về các đại tộc đứng đầu, còn Thiên Bằng tộc chỉ nhận được phần nhỏ. Khoáng mạch vừa bị một kẻ có thần thông mạnh cướp sạch.","theLucLienQuan":["Phi Linh tộc","Thiên Bằng tộc","Chấp pháp đội"],"nguon":["@c1848"]},{"id":"cua-vao-tang-thu-ba-duoi-day-song","name":"Cửa vào tầng thứ ba dưới đáy sông","cn":"","capDo":"khac","parentId":"tang-thu-hai-cua-dia-uyen","blurb":"Lối đi từ tầng thứ hai xuống tầng thứ ba Địa Uyên nằm dưới đáy một con sông.","detail":"Nhóm Hàn Lập tìm đến cửa vào này sau khi vượt qua yêu vật và nhiều đội chấp pháp tuần tra tại tầng thứ hai.","theLucLienQuan":["Chấp pháp đội"],"nguon":["@c1849"]},{"id":"tang-thu-ba-dia-uyen","name":"Tầng thứ ba Địa Uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Tầng Địa Uyên nơi nhóm Hàn Lập phát hiện dấu tích thiên lôi và tìm đến tọa độ truyền tống.","detail":"Tại đây, ba người phát hiện hiện trường ba chấp pháp đội viên bị giết, vượt qua dãy sơn mạch đen rồi dựng Ngũ sắc quang trận tại tọa độ do một vị tiền bối chỉ dẫn.","theLucLienQuan":["Chấp pháp đội","Thiên Bằng tộc"],"nguon":["@c1849"]},{"id":"vung-loan-thach-bi-thien-loi-danh","name":"Vùng loạn thạch bị thiên lôi đánh","cn":"","capDo":"khac","parentId":"tang-thu-ba-dia-uyen","blurb":"Hiện trường ba chấp pháp đội viên bị kẻ tinh thông thần thông lôi hệ giết chết.","detail":"Khu vực có một phiến đá cháy đen đường kính hơn mười trượng, mùi khét và nhiều pháp bảo hư hại, trong đó có nửa thanh đoản nhận màu lam.","theLucLienQuan":["Chấp pháp đội"],"nguon":["@c1849"]},{"id":"day-son-mach-den","name":"Dãy sơn mạch đen","cn":"","capDo":"khac","parentId":"tang-thu-ba-dia-uyen","blurb":"Dãy núi tại tầng thứ ba Địa Uyên, nơi nhóm Hàn Lập bị đàn yêu cầm giống quạ tập kích.","detail":"Ba người vừa chiến đấu với đàn yêu cầm vừa tiến lên; tại khu vực này, Bạch sắc viên bàn phát sinh cảm ứng và báo hiệu họ đã tới gần tọa độ mục tiêu.","theLucLienQuan":[],"nguon":["@c1849"]},{"id":"toa-do-truyen-tong-trong-dia-uyen","name":"Tọa độ truyền tống trong Địa Uyên","cn":"","capDo":"khac","parentId":"tang-thu-ba-dia-uyen","blurb":"Địa điểm do một vị tiền bối chỉ dẫn để Hàn Lập dựng trận truyền tống rời đi.","detail":"Kim Duyệt không cảm nhận được tiết điểm không gian tại đây, nhưng Bạch sắc viên bàn vẫn xác nhận tọa độ. Hàn Lập bố trí Ngũ sắc quang trận, đưa pháp khí vào trung tâm rồi khởi động trận.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1849"]},{"id":"bang-sat-chi-dia","name":"Băng sát chi địa","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực Kim Duyệt dự định đưa Lôi Lan tới để tu luyện.","detail":"Kim Duyệt dùng việc tới Băng sát chi địa giúp Lôi Lan tu luyện làm lý do công khai cho chuyến đi, đồng thời tránh để người khác nghi ngờ sau khi Hàn Lập được truyền tống.","theLucLienQuan":["Thiên Bằng Tộc"],"nguon":["@c1850"]},{"id":"ho-sau-tren-mat-dat","name":"Hố sâu trên mặt đất","cn":"","capDo":"khac","parentId":null,"blurb":"Hố sâu rộng được tạo thành khi Ngũ Sắc Khổng Tước bị kiếm quang ép đập mạnh xuống mặt đất.","detail":"Sau khi Hàn Lập hợp ba mươi sáu kim sắc tiểu kiếm thành cự kiếm, kiếm quang cuốn thân thể Ngũ Sắc Khổng Tước đập xuống đất và tạo thành hố sâu rộng. Tiếng Ngư điếm chủ tuyên bố sẽ liều mạng vọng lên từ phía dưới hố.","theLucLienQuan":[],"nguon":["@c1852"]},{"id":"dong-phu-thanh-nguyen-tu","name":"Động phủ Thanh Nguyên Tử","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Nơi ở và tu luyện của Thanh Nguyên Tử trong Minh Hà chi địa.","detail":"Hàn Lập cùng Nguyên Dao trở lại nơi này để gặp nguyên anh hóa thân của Thanh Nguyên Tử. Tại đại sảnh động phủ, Hàn Lập giao đủ tài liệu quý hiếm và bàn cách giải quyết việc Minh Hà thần nhũ đã được cho người khác mượn.","theLucLienQuan":[],"nguon":["@c1858"]},{"id":"minh-ha-chi-dia","name":"Minh Hà chi địa","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực Thanh Nguyên Tử ẩn cư và cũng là nơi ở của đại năng dị thú nắm giữ linh nhũ.","detail":"Từ động phủ Thanh Nguyên Tử tới nơi ở của đại năng dị thú cần khoảng mười ngày phi hành. Sâu trong khu vực có một hồ nước xanh biếc phủ sương xám và kim đảo được nhiều cấm chế bảo vệ.","theLucLienQuan":[],"nguon":["@c1859"]},{"id":"ho-nuoc-xanh-biec-suong-xam","name":"Hồ nước xanh biếc trong sương xám","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Hồ nước cực lớn nằm sâu trong Minh Hà chi địa, được bao phủ bởi sương xám và tỏa ra linh khí mạnh.","detail":"Trong hồ có vô số ngư yêu sở hữu pháp lực. Chúng dường như bị một lực lượng ước chế nên không dám nổi lên mặt nước khi Hàn Lập và Thanh Nguyên Tử bay qua.","theLucLienQuan":[],"nguon":["@c1859"]},{"id":"kim-dao-dai-nang-di-thu","name":"Kim đảo của đại năng dị thú","cn":"","capDo":"khac","parentId":"ho-nuoc-xanh-biec-suong-xam","blurb":"Hòn đảo tỏa kim quang giữa hồ, là nơi ở của đại năng dị thú nắm giữ linh nhũ.","detail":"Một tòa cung điện xanh vàng chiếm khoảng hai phần ba diện tích đảo, xung quanh có nhiều kỳ hoa dị quả. Toàn đảo được quang vụ cùng nhiều lớp cấm chế bao phủ.","theLucLienQuan":[],"nguon":["@c1859"]},{"id":"kim-diem-dao","name":"Kim Diễm Đảo","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Hòn đảo tỏa ánh vàng rực rỡ, là nơi ở của Kim Diễm Hậu.","detail":"Kim Diễm Đảo có cung điện kim sắc, quầng sáng bạch sắc phòng hộ và bốn kim giáp vệ sĩ cảnh giới Luyện Hư canh giữ. Thanh Nguyên Tử đưa Hàn Lập tới đây để thương lượng với chủ đảo.","theLucLienQuan":[],"nguon":["@c1860"]},{"id":"cung-dien-kim-sac","name":"Cung điện kim sắc","cn":"","capDo":"khac","parentId":"kim-diem-dao","blurb":"Cung điện rực sắc vàng nằm trên Kim Diễm Đảo.","detail":"Bên trong cung điện có một đại sảnh rộng lớn, nơi Kim Diễm Hậu tiếp Thanh Nguyên Tử và Hàn Lập rồi thương lượng về Cửu Đồng Châu, Minh Hà chi nhũ, Tức Nhưỡng chi thổ và lôi châu diệt ma.","theLucLienQuan":[],"nguon":["@c1860"]},{"id":"cung-dien-kim-diem-hau","name":"Cung điện Kim Diễm Hậu","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Nơi ở của Kim Diễm Hậu tại Minh Hà Chi Địa.","detail":"Hư Linh, Kim Diễm Hậu, Thanh Nguyên Tử và Hàn Lập bàn chuyện trong đại sảnh của cung điện. Khách được khoản đãi bằng linh quả và Bích Linh tửu tại đây.","theLucLienQuan":[],"nguon":["@c1862"]},{"id":"dai-sanh-hu-linh","name":"Đại sảnh của Hư Linh","cn":"","capDo":"khac","parentId":"dong-phu-thanh-nguyen-tu","blurb":"Gian đại sảnh nơi Hư Linh tiếp khách và trưng bày tàn phiến Huyền Thiên chi bảo.","detail":"Hư Linh kích hoạt tàn phiến hình lư hương tại đây, khiến thiên địa chi lực đáng sợ tạo thành sức ép bao phủ toàn bộ đại sảnh.","theLucLienQuan":["Phù Du tộc"],"nguon":["@c1864"]},{"id":"chien-truong-co-man-hoang-the-gioi","name":"Chiến trường cổ trong Man hoang thế giới","cn":"","capDo":"khac","parentId":"man-hoang-the-gioi","blurb":"Một chiến trường cổ nằm sâu trong Man hoang thế giới.","detail":"Hư Linh tình cờ tìm thấy tàn phiến Huyền Thiên chi bảo hình lư hương tại chiến trường cổ này, sau đó mang về luyện chế lại để khu sử.","theLucLienQuan":[],"nguon":["@c1864"]},{"id":"khong-gian-ben-trong-hac-phong-cac","name":"Không gian bên trong Hắc Phong Các","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Không gian phong bế bên trong Hắc Phong Các, nơi diễn ra cuộc thương lượng bí mật về Phệ Kim Trùng trưởng thành.","detail":"Hư Linh lão giả đưa Hàn Lập vào đây để thương lượng việc đổi ít nhất năm nghìn Phệ Kim Trùng trưởng thành. Hắc khí bên ngoài lầu các ngăn người khác cảm ứng và cản thần niệm xâm nhập.","theLucLienQuan":[],"nguon":["@c1866"]},{"id":"hac-phong-cac-dia-danh","name":"Hắc Phong Các","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Hàn Lập và Hư Linh lão giả tiến hành cuộc giao dịch riêng về Phệ Kim trùng, Minh Hà linh nhũ và Dục Trùng Bí Thuật.","detail":"Hàn Lập rời Hắc Phong Các trước sau khi hoàn tất giao dịch. Hư Linh lão giả ở lại phong giữ Linh Thú Hoàn rồi mới ra ngoài hội họp với Thanh Nguyên Tử và Kim Diễm.","theLucLienQuan":[],"nguon":["@c1867"]},{"id":"tam-canh-nhan-toc","name":"Tam cảnh Nhân tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Ba vùng lãnh thổ lớn của Nhân tộc được quân sự hóa toàn diện để chuẩn bị cho ma kiếp.","detail":"Sau hơn ba trăm năm, khắp tam cảnh xuất hiện thành lũy, giáp sĩ cùng mạng lưới pháp trận và cấm chế dày đặc. Các thành thị trở thành cứ điểm phòng thủ, còn nhân lực và tài nguyên được huy động trên quy mô toàn tộc.","theLucLienQuan":["Nhân tộc","Thánh đảo","Tam Đại Hoàng thành","Mười đại tông môn Nhân tộc","Tam đại gia tộc Chân Linh"],"nguon":["@c1868"]},{"id":"vung-son-mach-gan-thien-uyen-thanh","name":"Vùng sơn mạch gần Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Vùng núi nơi các ký danh đệ tử của Hàn Lập gây dựng hàng trăm môn nhân.","detail":"Bạch Quả Nhi giảng pháp tại một ngọn núi trong vùng này cho khoảng ba bốn trăm môn nhân của Khí Linh Tử và Hải Đại Thiếu.","theLucLienQuan":["Vụ Hải Quan","Thiên Uyên thành"],"nguon":["@c1868"]},{"id":"huyen-vu-hoang-thanh","name":"Huyền Vũ hoàng thành","cn":"","capDo":"thanh","parentId":"tam-canh","blurb":"Hoàng thành nơi thân nhân của Bạch Quả Nhi đã chuyển đến để chuẩn bị đối phó Ma Kiếp.","detail":"Phụ thân gửi thư gọi Bạch Quả Nhi trở về đây vì tổ mẫu cùng những thân nhân khác đều đã di dời tới hoàng thành.","theLucLienQuan":[],"nguon":["@c1869"]},{"id":"dia-vuc-nhan-toc","name":"Địa vực Nhân tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực Hàn Lập trở về sau hành trình hơn trăm năm kể từ khi rời Minh Hà chi địa.","detail":"Sau khi trở lại địa vực Nhân tộc và biết Ma Kiếp sắp bộc phát, Hàn Lập triệu tập ba đệ tử để dặn dò, bố trí nhiều tầng cấm chế rồi tiếp tục bế quan tăng tiến tu vi và đào tạo Phệ Kim Trùng Vương.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1870"]},{"id":"son-mach-sau-trong-man-hoang-the-gioi","name":"Sơn mạch sâu trong Man Hoang thế giới","cn":"","capDo":"khac","parentId":"man-hoang-the-gioi","blurb":"Vùng sơn mạch nơi bạch y thanh niên đối đầu ba cổ thú không chịu rời đi.","detail":"Bạch y thanh niên cảnh cáo các sinh linh cường đại rời khỏi khu vực này. Khi song đầu cự nhân và hai xích mãng chống đối, hắn hóa thành ngô công trắng sáu cánh, dùng hàn diễm tiêu diệt rồi nuốt chúng.","theLucLienQuan":[],"nguon":["@c1871"]},{"id":"tham-hai-cung-dien","name":"Thâm Hải Cung Điện","cn":"","capDo":"khac","parentId":null,"blurb":"Cung điện nằm dưới biển sâu, có mật thất chứa huyết kén và một thủy tinh cầu hiển thị đài sen ngân quang.","detail":"Trong mật thất của cung điện, huyết kén bành trướng rồi nổ tung, để lộ thanh niên mang minh ấn liên hoa vàng. Một thủy tinh cầu đặt trên bàn ngọc hiển thị hình ảnh đài sen ngân quang sống động.","theLucLienQuan":[],"nguon":["@c1871"]},{"id":"thanh-dia-moc-toc","name":"Thánh địa Mộc tộc","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Thánh địa nằm trong phạm vi Mộc tộc, có đại thụ cao hơn vạn trượng và Hắc Linh Hoa.","detail":"Bạch y nữ tử cùng hắc giáp đại hán bí mật xâm nhập nơi này và lấy hơn mười đóa Hắc Linh Hoa. Đại trưởng lão Mộc tộc mở khe hở không gian để giao đấu bên ngoài, tránh phá hoại thánh địa.","theLucLienQuan":["Mộc Tộc"],"nguon":["@c1872"]},{"id":"hac-linh-thanh-thon","name":"Hắc Linh Thánh Thôn","cn":"","capDo":"khac","parentId":"thanh-dia-moc-toc","blurb":"Khu vực thuộc Mộc tộc nơi Hắc Linh Hoa sinh trưởng.","detail":"Hắc Linh Thánh Thôn có sản lượng linh hoa cực thấp, trải qua vạn năm cũng chỉ sinh ra hơn trăm đóa Hắc Linh Hoa.","theLucLienQuan":["Mộc Tộc"],"nguon":["@c1872"]},{"id":"khe-ho-khong-gian-tai-thanh-dia-moc-toc","name":"Khe hở không gian tại thánh địa Mộc tộc","cn":"","capDo":"gioi-nho","parentId":"thanh-dia-moc-toc","blurb":"Khe hở không gian do Đại trưởng lão Mộc tộc cưỡng ép mở ra làm chiến trường.","detail":"Đại trưởng lão dùng cự kiếm thanh sắc chém rách hư không, tạo khe hở dài vài chục trượng rồi cùng bạch y nữ tử tiến vào giao đấu khoảng một tuần trà.","theLucLienQuan":["Mộc Tộc"],"nguon":["@c1872"]},{"id":"truong-lao-dien","name":"Trưởng Lão Điện","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi các trưởng lão Thiên Uyên Thành hội họp và bàn việc.","detail":"Kim Việt thiền sư dẫn Hàn Lập tới Trưởng Lão Điện sau khi bố trí nơi cư trú cho môn nhân của hắn.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1874"]},{"id":"dai-sanh-ngoc-tren-thap-lon","name":"Đại sảnh ngọc trên tháp lớn","cn":"","capDo":"khac","parentId":"truong-lao-dien","blurb":"Đại sảnh nơi Hàn Lập gặp ba trưởng lão Hợp Thể của Thiên Uyên Thành.","detail":"Gian phòng có bàn cùng những vách tường trắng sáng như được xây bằng ngọc thượng đẳng.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1874"]},{"id":"dong-phu-ngan-quang-tien-tu","name":"Động phủ Ngân Quang tiên tử","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Động phủ của Ngân Quang tiên tử tại Thiên Uyên Thành.","detail":"Hàn Lập tới đây gặp riêng Ngân Quang tiên tử và lưu lại khoảng nửa ngày. Nội dung cuộc trao đổi không được tiết lộ.","theLucLienQuan":["Thiên Uyên Thành","Ngân Lang Tộc"],"nguon":["@c1874"]},{"id":"thap-trang-cua-han-lap","name":"Tháp trắng của Hàn Lập","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi ở tạm của Hàn Lập cùng khoảng một nghìn môn nhân trong Thiên Uyên Thành.","detail":"Tòa tháp nhỏ hơn nhiều công trình xung quanh nhưng vẫn đủ sức chứa toàn bộ đoàn người của Hàn Lập.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1874"]},{"id":"son-mach-cu-diem-lung-gia","name":"Sơn mạch cứ điểm Lũng gia","cn":"","capDo":"vuc","parentId":"dia-vuc-nhan-toc","blurb":"Sơn mạch dài hơn nghìn vạn dặm được Lũng gia và hơn mười thế gia xây dựng thành cứ điểm chống Ma tộc.","detail":"Khu vực đầy sát khí, có hơn mười thành trì bố trí thành vòng phòng thủ, nhiều pháp trận và các đội vệ sĩ tuần tra. Thành lớn nhất treo đại kỳ mang chữ Lũng.","theLucLienQuan":["Lũng gia","Liên minh các thế gia tại cứ điểm Lũng gia"],"nguon":["@c1874"]},{"id":"dai-thanh-cua-lung-gia","name":"Đại thành của Lũng gia","cn":"","capDo":"thanh","parentId":"dia-vuc-nhan-toc","blurb":"Thành trì nơi Lũng gia lão tổ cư trú vào thời điểm gặp Hàn Lập.","detail":"Lũng gia lão tổ từ trong đại thành bay ra, nghênh tiếp Hàn Lập tại vùng không trung lân cận rồi tiến hành giao dịch.","theLucLienQuan":["Lũng gia","Nhân tộc"],"nguon":["@c1875"]},{"id":"ma-chuong-gan-thien-uyen-thanh","name":"Ma chướng gần Thiên Uyên Thành","cn":"","capDo":"vuc","parentId":"dia-vuc-nhan-toc","blurb":"Các vùng ma chướng lan rộng gần Thiên Uyên Thành khi Ma kiếp sắp bộc phát.","detail":"Những vùng ma chướng gần thành trải rộng hàng vạn dặm, phát ánh sáng đen và chứa ma khí cuộn mạnh. Tại một vùng cách thành mấy vạn dặm, hư không rung chuyển rồi vô số Ma Dơi tràn ra.","theLucLienQuan":["Thiên Uyên Thành","Ma tộc"],"nguon":["@c1877"]},{"id":"dia-phan-linh-hoang","name":"Địa phận Linh Hoàng","cn":"","capDo":"vuc","parentId":"dia-vuc-nhan-toc","blurb":"Địa phận thuộc phạm vi của vị Linh Hoàng mới nhậm chức.","detail":"Gần địa phận này xuất hiện một vùng ma chướng trải rộng tới trăm vạn dặm, lớn hơn các vùng ma chướng quanh Thiên Uyên Thành trên trăm lần.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1877"]},{"id":"ma-hai-tren-troi-cao","name":"Ma hải trên trời cao","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Vùng ma khí rộng lớn trên trời cao, nơi các đàn ma thú và lực lượng Ma tộc liên tục tràn ra.","detail":"Ma hải tiếp tục dao động và mở rộng thêm khoảng ba phần khi hàng trăm cự tháp hình tam giác vượt giới xuất hiện. Từ đây, nhiều đợt ma thú cùng đại quân Ma tộc được triển khai vào Linh Giới.","theLucLienQuan":["Ma tộc","Đại quân Ma tộc vượt giới"],"nguon":["@c1879"]},{"id":"dai-thanh-ma-toc-duoi-ma-hai","name":"Đại thành Ma tộc dưới ma hải","cn":"","capDo":"thanh","parentId":"linh-gioi","blurb":"Cứ điểm quân sự quy mô lớn do Ma tộc dựng quanh khoảng một trăm cự tháp dưới ma hải.","detail":"Đại thành có tường đá bao kín phạm vi mấy vạn dặm, nhiều pháp trận và tầng cấm chế, cùng một tế đàn đỏ thẫm gần khu vực trung tâm. Huyết Quang còn dùng ma khí gia trì toàn thành để tăng khả năng hồi phục cho quân trú đóng.","theLucLienQuan":["Ma tộc"],"nguon":["@c1880"]},{"id":"thanh-tri-nhan-toc-ben-dai-thu","name":"Thành trì Nhân tộc bên đại thụ","cn":"","capDo":"thanh","parentId":"dia-vuc-nhan-toc","blurb":"Thành trì Nhân tộc được xây dựa vào một đại thụ khổng lồ và nằm gần Ma chướng lớn.","detail":"Đại thụ vươn thẳng lên trời và mang theo lầu các trên các nhánh. Nhiều tu sĩ Hợp Thể đứng tại đó quan sát ma hải đang cuồn cuộn gần phòng tuyến.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1880"]},{"id":"thien-nguyen-thanh-thanh","name":"Thiên Nguyên Thánh thành","cn":"","capDo":"thanh","parentId":"dia-vuc-nhan-toc","blurb":"Thành trì Nhân tộc nằm cách khu vực một tăng một đạo giao chiến với ma vật khoảng ngàn dặm.","detail":"Vùng phụ cận Thiên Nguyên Thánh thành đã xuất hiện ma vật và dấu hiệu cao giai Ma tộc kéo tới, buộc hai tu sĩ đang hoạt động bên ngoài phải rút lui.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1880"]},{"id":"thien-nguyen-hoang-thanh","name":"Thiên Nguyên Hoàng Thành","cn":"","capDo":"thanh","parentId":"dia-vuc-nhan-toc","blurb":"Hoàng thành Nhân tộc trở thành hướng rút lui của hai tu sĩ khi cao giai Ma tộc áp sát.","detail":"Sau khi phát hiện ma phong báo hiệu cao giai Ma tộc đang kéo tới, một tăng một đạo lập tức hóa thành kinh hồng bay về phía Thiên Nguyên Hoàng Thành.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1880"]},{"id":"binh-nguyen-kho-vang-cua-yeu-toc","name":"Bình nguyên khô vàng của Yêu tộc","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Bình nguyên hoang vắng thuộc lãnh địa Yêu tộc, nơi hai đạo đại quân yêu thú và ma thú giao chiến.","detail":"Mười vạn sói u âm cùng hàng ngàn bạch ưng đối đầu hàng vạn ma sư lam sắc và song đầu phi xà. Giao chiến diễn ra cả trên không lẫn mặt đất với thương vong liên tục.","theLucLienQuan":["Yêu tộc","Ma tộc"],"nguon":["@c1880"]},{"id":"vung-bien-quanh-cu-dao","name":"Vùng biển quanh cự đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng biển có một cự đảo và thành thị cô độc bị hắc khí cùng hàng nghìn ma thú áp sát.","detail":"Một cự thú màu xanh dài tới vạn trượng trồi lên từ đáy biển, tạo lam sắc quang hà và cơn lốc cuốn hàng nghìn ma thú vào miệng rồi chìm xuống. Một bóng người cao lớn đứng trên tháp của cự đảo và lạnh lùng quan sát biến cố.","theLucLienQuan":["Ma tộc"],"nguon":["@c1881"]},{"id":"quan-thien-thai","name":"Quan Thiên Thai","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Địa điểm trong Thiên Uyên thành được Trưởng lão hội dùng để triệu tập Hàn Lập khi Ma tộc tới dưới thành.","detail":"Hải Đại Thiếu truyền tin rằng Hàn Lập phải tới Quan Thiên Thai do cao giai Ma tộc đã xuất hiện trong lực lượng áp sát Thiên Uyên thành.","theLucLienQuan":["Thiên Uyên thành","Trưởng lão hội Thiên Uyên thành"],"nguon":["@c1881","@c1882"]},{"id":"linh-hoang-thanh","name":"Linh Hoàng Thành","cn":"","capDo":"thanh","parentId":"dia-vuc-nhan-toc","blurb":"Một phòng tuyến của Nhân tộc đang chịu áp lực lớn từ đại quân Ma tộc.","detail":"Ngân Quang tiên tử xác định Linh Hoàng Thành mới là hướng tiến công chủ yếu của Ma tộc, với số lượng đại quân đông gấp nhiều lần lực lượng đang vây Thiên Uyên thành.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1882"]},{"id":"cac-thanh-luy-quanh-thien-uyen-thanh","name":"Các thành lũy quanh Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Hệ thống hàng nghìn thành lũy tạo thành tuyến phòng ngự bao quanh Thiên Uyên thành.","detail":"Mỗi thành lũy cao hơn trăm trượng, có cấm chế và hơn trăm tu sĩ trấn giữ. Mấy chục tòa gần đàn ma thú nhất trở thành chiến tuyến đầu tiên khi quân tiên phong Ma tộc mở cuộc xung kích.","theLucLienQuan":["Nhân tộc","Thiên Uyên thành","Ma tộc"],"nguon":["@c1883"]},{"id":"thien-bao-than-dien","name":"Thiên Bảo thần điện","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Cung điện bạch ngọc tại Thiên Uyên thành, cung cấp linh lực cho Kim Húc Bảo Kính.","detail":"Thiên Bảo thần điện là nguồn linh lực khổng lồ giúp phân quang của Kim Húc Bảo Kính tạo quầng sáng kim sắc bảo vệ diện rộng quanh tuyến thành lũy.","theLucLienQuan":["Nhân tộc","Thiên Uyên thành"],"nguon":["@c1883"]},{"id":"cung-dien-bach-ngoc","name":"Cung điện bạch ngọc","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi các tu sĩ Hợp Thể quan sát chiến trường và bàn phương án ứng phó đợt tiến công của Ma tộc.","detail":"Sau khi thống nhất việc luân phiên chủ trì phòng thủ, Hàn Lập, Kim Việt thiền sư, Ngân Quang tiên tử và những tu sĩ khác lần lượt rời đi. Cốc trưởng lão cùng Bảo đạo hữu tiếp tục ở lại bàn việc phản kích.","theLucLienQuan":["Thiên Uyên Thành","Trưởng Lão Hội"],"nguon":["@c1884"]},{"id":"cu-thap-do-dam-duoi-thien-uyen-thanh","name":"Cự tháp đỏ đậm dưới Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Công trình nằm sâu dưới Thiên Uyên Thành, là nơi bố trí trận đồ của Thất Tinh Tinh Hỏa đại trận.","detail":"Bên trong cự tháp có không gian vận chuyển đại trận với bảy vị trí chủ trì. Bảy lão giả Luyện Hư kỳ tập trung tại đây, xuất Nguyên Anh và đưa bộ dị bảo cực hỏa vào trung tâm trận đồ.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1884"]},{"id":"toa-thanh-ma-toc","name":"Tòa thành Ma tộc","cn":"","capDo":"thanh","parentId":null,"blurb":"Một thành trì Ma tộc nằm rất xa Thiên Uyên Thành. Nơi đây có ngọn tháp tam giác và đại điện dùng để theo dõi, đánh giá chiến trường.","detail":"Trong đại điện của tòa thành, Huyết bào Nam tử triệu tập hơn hai mươi Ma tộc cao cấp và quan sát biển lửa quanh Thiên Uyên Thành qua một viên tinh cầu truyền ảnh.","theLucLienQuan":["Ma tộc"],"nguon":["@c1885"]},{"id":"y-thien-thanh","name":"Ỷ Thiên Thành","cn":"","capDo":"thanh","parentId":"dia-vuc-nhan-toc","blurb":"Cứ điểm lớn do Tứ Đại Tông Môn xây dựng, có quy mô chỉ thua Thiên Uyên Thành và năng lực phòng ngự gần tương đương.","detail":"Ỷ Thiên Thành đang chịu sức ép lớn từ đại quân Ma tộc. Sau khi hai Thái Thượng trưởng lão bị dụ ra ngoài đánh lén và vẫn lạc, chiến lực cao cấp của thành suy giảm, buộc Tứ Đại Tông Môn cầu viện Thiên Uyên Thành.","theLucLienQuan":["Tứ Đại Tông Môn","Ỷ Thiên Môn","Khinh Thiên Môn","Thiên Hoàng Tông","Ma tộc"],"nguon":["@c1886","@c1898","@c1917","@c1968"]},{"id":"truyen-tong-dai-dien-thien-uyen-thanh","name":"Truyền tống đại điện Thiên Uyên Thành","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Đại điện đặt Truyền Tống Trận bí mật của Thiên Uyên Thành, nơi Hàn Lập và Ngân Quang tiên tử khởi hành đi cứu viện Ỷ Thiên Thành.","detail":"Nơi đặt pháp trận truyền tống bí mật dùng để đưa viện binh tới khu vực gần Ỷ Thiên Thành. Có đội vệ sĩ canh giữ do một thủ lĩnh chỉ huy. Pháp trận chỉ có thể đưa người tới vị trí cách Ỷ Thiên Thành khoảng nửa tháng hành trình do cấm chế Ma tộc ngăn truyền tống cự ly xa.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1887"]},{"id":"tieu-son-tren-cua-dong","name":"Tiểu sơn trên cửa động","cn":"","capDo":"khac","parentId":"dong-quat","blurb":"Ngọn núi cao khoảng nghìn trượng che lối ra của động quật chứa truyền tống trận.","detail":"Bạch giáp Lão hán dùng cự côn đen tuyền đánh nát gần nửa ngọn núi trước khi bắt đầu truy đuổi hung thủ.","theLucLienQuan":["Ma tộc"],"nguon":["@c1888"]},{"id":"toa-nui-ngoai-van-dam","name":"Tòa núi ngoài vạn dặm","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Ngọn núi nằm cách khu vực truyền tống hơn vạn dặm.","detail":"Lam tôn giả và một Ma tộc đầu trọc đứng tại đây chờ Lực lão quái quay lại để cùng thực hiện đại sự do Huyết Quang giao phó.","theLucLienQuan":["Ma tộc"],"nguon":["@c1888"]},{"id":"khu-cu-diem-nhan-toc","name":"Khu cứ điểm Nhân tộc","cn":"","capDo":"khac","parentId":"dia-vuc-nhan-toc","blurb":"Một cứ điểm của Nhân tộc đang bị lực lượng Ma tộc bao vây.","detail":"Lam tôn giả và Mễ mỗ hoạt động quanh khu vực này trước khi lên đường hội hợp với Lực tôn giả. Phe Ma tộc nghi ngờ các tu sĩ Nhân tộc xuất hiện tại đây có liên quan tới kế hoạch chống lại vòng vây.","theLucLienQuan":["Nhân tộc","Ma tộc","Thánh tộc"],"nguon":["@c1889"]},{"id":"quan-tieu-son-tieu-dieu","name":"Quần tiểu sơn tiêu điều","cn":"","capDo":"khac","parentId":null,"blurb":"Quần núi nhỏ nơi hai Ma Tôn Hợp Thể ẩn thân và bố trí đại trận mai phục.","detail":"Lực tôn giả chạy về quần tiểu sơn để tìm đồng bọn cứu viện và dụ người truy kích vào đại trận. Hắn bị Hàn Lập chặn lại rồi tiêu diệt trước khi tới được nơi mai phục.","theLucLienQuan":["Ma tộc"],"nguon":["@c1892"]},{"id":"khu-vuc-ma-tran-quanh-cac-tieu-son","name":"Khu vực ma trận quanh các tiểu sơn","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu vực rộng vài dặm với nhiều tiểu sơn được dùng làm mắt trận trong trận pháp của Lam tôn giả.","detail":"Ma trận từ dưới đất hiện lên và phủ kín khu vực bằng phù văn cùng ma khí. Các sơn phong giữ vai trò mắt trận; Hàn Lập phá hủy ba ngọn khiến ma khí trong trận suy yếu.","theLucLienQuan":["Ma tộc"],"nguon":["@c1895"]},{"id":"ma-thanh-moi-kien-lap","name":"Ma thành mới kiến lập","cn":"","capDo":"thanh","parentId":null,"blurb":"Một thành trì Ma tộc mới xây, có cự tháp hình tam giác cao hàng nghìn trượng. Hóa thân Huyết Quang tọa trấn tại đây.","detail":"Từ ma thành này, Huyết Quang xác nhận cái chết của ba Ma tôn và phái hơn trăm Huyết Quang Tinh Vệ đi điều tra chiến trường, truy tìm hung thủ cùng món đồ thất lạc.","theLucLienQuan":["Ma tộc","Huyết Quang Tinh Vệ"],"nguon":["@c1898"]},{"id":"cu-thap-trong-y-thien-thanh","name":"Cự tháp trong Ỷ Thiên thành","cn":"","aliases":[],"capDo":"khac","parentId":"y-thien-thanh","blurb":"Tòa tháp cao hơn ngàn trượng nằm trong Ỷ Thiên thành, là trung tâm của pháp trận điều động đại quân khôi lỗi.","detail":"Hàng ngàn tu sĩ lập trận quanh cự tháp và truyền ngũ sắc linh lực vào bên trong. Khi được kích hoạt, tháp phối hợp mở đường để từng đội thanh sắc đồng nhân tiến ra chiến trường.","theLucLienQuan":["Lực lượng phòng thủ Ỷ Thiên thành","Nhân tộc"],"nguon":["@c1900"]},{"id":"trung-kiem-son-mach","name":"Trung Kiếm sơn mạch","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn mạch nằm cách Ỷ Thiên thành khoảng vạn dặm, là nơi đại quân Ma tộc chủ lực đang đồn trú.","detail":"Đại quân Ma tộc chưa tung toàn bộ lực lượng vào cuộc công thành mà tập trung chủ lực tại Trung Kiếm sơn mạch, chờ thời điểm đại trận phòng hộ của Ỷ Thiên thành mất hiệu lực.","theLucLienQuan":["Ma tộc đại quân tiến công Ỷ Thiên thành"],"nguon":["@c1902"]},{"id":"chin-tuyet-dia-hoa-luc","name":"Chín tuyệt địa hỏa lực","cn":"","capDo":"khac","parentId":"y-thien-thanh","blurb":"Chín địa điểm cung cấp địa hỏa cho Cửu Dương Cương Nhật Tuyệt Trận.","detail":"Đây là các nguồn hỏa lực cần thiết để bố trí và vận hành tuyệt trận bảo vệ Ỷ Thiên Thành. Chương chưa nêu tên riêng hoặc vị trí cụ thể của từng tuyệt địa.","theLucLienQuan":["Bốn đại tông môn tại Ỷ Thiên Thành"],"nguon":["@c1903"]},{"id":"lau-cac-trong-rung-truc","name":"Lầu các trong rừng trúc","cn":"","capDo":"khac","parentId":"y-thien-thanh","blurb":"Nơi ở u tĩnh của Hàn Lập bên trong Ỷ Thiên thành.","detail":"Lầu các nằm giữa rừng trúc và có mật thất được bố trí nhiều tầng cấm chế nghiêm mật. Hàn Lập ở đây nghiên cứu hộp gỗ suốt ba ngày ba đêm.","theLucLienQuan":["Nhân tộc","Lực lượng phòng thủ Ỷ Thiên thành"],"nguon":["@c1905"]},{"id":"khong-gian-tam-toi-trong-hop-go","name":"Không gian tăm tối trong hộp gỗ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian bí ẩn mà hư ảnh thần niệm của Hàn Lập tiến vào sau khi xuyên qua hộp gỗ.","detail":"Nơi này chìm trong bóng tối và bước đầu được Hàn Lập nhận định giống một tầng cấm chế ảo thuật hơn tu di không gian thông thường. Thần niệm tiến vào có thể bị giữ lại trong các tầng cấm chế.","theLucLienQuan":[],"nguon":["@c1905"]},{"id":"tang-thu-muoi-ben-trong-tran-ma-toa","name":"Tầng thứ mười bên trong Trấn Ma Tỏa","cn":"","capDo":"gioi-nho","parentId":"khong-gian-tam-toi-trong-hop-go","blurb":"Không gian ảo thuật thuộc tầng cấm chế thứ mười bên trong Trấn Ma Tỏa, nơi thần niệm Hàn Lập gặp Lục bào lão giả.","detail":"Nơi này ban đầu là một vùng sương xám dường như không có biên giới. Lục bào lão giả có thể biến toàn bộ không gian thành trời xanh, núi biếc, dòng suối và cá sống với cảm giác gần như chân thực; thần niệm của lão bị vây tại đây, còn thần niệm Hàn Lập vô tình xâm nhập khi tìm cách tiến vào bảo vật.","theLucLienQuan":["Thánh tộc"],"nguon":["@c1906"]},{"id":"khong-gian-muoi-ba-tang-cua-tran-ma-toa","name":"Không gian mười ba tầng của Trấn Ma Tỏa","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian tự hình thành bên trong Trấn Ma Tỏa, được chia thành mười ba tầng.","detail":"Mỗi tầng đều được một đại tông sư trận pháp Cổ Ma giới bố trí thượng cổ cấm chế. Hệ thống cấm chế cùng lưỡng khí hỗn độn khiến người bị nhốt gần như không thể dùng ngoại lực thoát ra; Xa Kỵ Cung đang bị giam sâu bên trong.","theLucLienQuan":["Cổ Ma tộc"],"nguon":["@c1907"]},{"id":"am-duong-minh-tri","name":"Âm Dương Minh Trì","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Một loại linh địa do thiên địa diễn biến, có khả năng tồn tại tại Linh giới.","detail":"Âm Dương Minh Trì là một trong hai loại linh địa có thể dùng để tế luyện lại Trấn Ma Tỏa. Khi kết hợp với bí thuật của Cổ Ma tộc, nơi này cho phép rút một phần khí hỗn độn khỏi bảo vật.","theLucLienQuan":[],"nguon":["@c1907"]},{"id":"hoang-tuyen-dia-hoa","name":"Hoàng Tuyền Địa Hỏa","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Một loại linh địa tại Linh giới có thể dùng để tế luyện Trấn Ma Tỏa.","detail":"Hoàng Tuyền Địa Hỏa có cùng công dụng với Âm Dương Minh Trì trong việc phối hợp với bí thuật Cổ Ma để tế luyện lại Trấn Ma Tỏa và rút khí hỗn độn.","theLucLienQuan":[],"nguon":["@c1907","@c1927"]},{"id":"son-coc-cua-dai-quan-ma-toc","name":"Sơn cốc của đại quân Ma tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi đóng quân và hội họp của nhóm Tàng ma tôn trước cuộc công thành Ỷ Thiên thành.","detail":"Tàng ma tôn dẫn Lãnh Nhận và Vũ Tiên tử ra nghênh đón Âm Dương nhị sát tại đây. Các cường giả Ma tộc sau đó vào đại điện trong cốc thương nghị kế hoạch hơn nửa ngày.","theLucLienQuan":["Ma tộc","Phe Huyết Quang"],"nguon":["@c1909"]},{"id":"dai-dien-hoi-nghi-y-thien-thanh","name":"Đại điện hội nghị Ỷ Thiên thành","cn":"","capDo":"khac","parentId":"y-thien-thanh","blurb":"Trung tâm hội nghị và theo dõi chiến trường của lực lượng phòng thủ Ỷ Thiên thành.","detail":"Đại điện tập hợp hơn trăm tu sĩ từ Luyện Hư trở lên cùng hàng trăm vệ sĩ. Một hư ảnh lớn ở giữa điện cho thấy các đoàn hắc khí của quân Ma tộc đang áp sát thành từ bốn phía.","theLucLienQuan":["Nhân tộc","Lực lượng phòng thủ Ỷ Thiên thành","Bốn đại tông môn tại Ỷ Thiên Thành"],"nguon":["@c1909"]},{"id":"ma-hai-mau-den","name":"Ma hải màu đen","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực tập kết lực lượng Ma tộc bên ngoài Ỷ Thiên thành.","detail":"Bốn tôn giả Ma tộc và cự hình chiến thuyền lần lượt xuất hiện từ ma hải. Gia Luân chiến ma chưa lộ diện và có thể vẫn còn ẩn bên trong.","theLucLienQuan":["Ma tộc","Gia Luân chiến ma"],"nguon":["@c1911"]},{"id":"khu-vuc-muoi-dam-truoc-tuong-thanh","name":"Khu vực mười dặm trước tường thành","cn":"","capDo":"khac","parentId":"y-thien-thanh","blurb":"Chiến trường chính giữa đại quân Nhân tộc và Ma tộc trước tường thành Ỷ Thiên.","detail":"Khi hai bên giao chiến toàn diện, khu vực này bị linh quang, vụ nổ và khí huyết tinh bao phủ, nhanh chóng trở thành một vùng tử địa.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1911"]},{"id":"dau-tuong-thanh-y-thien-thanh","name":"Đầu tường thành Ỷ Thiên thành","cn":"","capDo":"khac","parentId":"y-thien-thanh","blurb":"Khu vực phòng thủ trên tường thành, nơi cấm chế bị cự chùy màu đen liên tục công kích.","detail":"Hai cự chùy màu đen đánh cấm chế tại đầu tường thành đến mức phòng hộ lung lay. Khi các trận chiến giữa tu sĩ Nhân tộc và Ma tộc triển khai, cấm chế tại đây tiếp tục tỏa hào quang mạnh.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1912"]},{"id":"dinh-dai-dien","name":"Đỉnh đại điện","cn":"","capDo":"khac","parentId":"dai-dien-hoi-nghi-y-thien-thanh","blurb":"Khu vực phía trên đại điện nơi Ngân Quang tiên tử xuyên qua quang tráo bạc để nghênh chiến Vũ tiên tử.","detail":"Ngân Quang tiên tử hóa thành ngân hồng bay lên phía trên đỉnh đại điện, xuyên thủng quang tráo màu bạc rồi chủ động đánh về phía Vũ tiên tử.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1912"]},{"id":"khong-gian-ben-trong-that-thai-bao-thap","name":"Không gian bên trong thất thải bảo tháp","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian Tu Di độc lập nằm trong Thất thải bảo tháp, dùng để giam giữ và công kích mục tiêu bị thu vào.","detail":"Nơi này không thấy trời đất, bốn phía tràn ngập hà quang lưu ly. Số lượng lớn hắc sắc ma thú có thể xuất hiện từ hà quang và lao vào công kích người bị giam.","theLucLienQuan":["Ma tộc"],"nguon":["@c1914","@c1917"],"aliases":["Không gian lưu ly của thất sắc bảo tháp"]},{"id":"chien-truong-ngoai-y-thien-thanh","name":"Chiến trường ngoài Ỷ Thiên thành","cn":"","capDo":"khac","parentId":"y-thien-thanh","blurb":"Khu vực bên ngoài Ỷ Thiên thành nơi các chiến đoàn Hợp Thể của Nhân tộc và Ma tộc giao chiến.","detail":"Tại đây, Hàn Lập bị Tử Ngôn đỉnh và Thất thải bảo tháp phối hợp trấn áp. Các trận đấu của Thanh Long thượng nhân, Lâm Loan tiên tử và Ngân Quang tiên tử cũng đồng loạt chuyển sang bất lợi.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1914"]},{"id":"tang-thu-nhat-cua-bao-thap","name":"Tầng thứ nhất của bảo tháp","cn":"","capDo":"khac","parentId":"khong-gian-ben-trong-that-thai-bao-thap","blurb":"Tầng đầu có không gian thực tế kéo dài hơn vẻ ngoài và được hơn một trăm khôi lỗi bạc Hóa Thần kỳ canh giữ.","detail":"Cửa vào được bảo vệ bằng kim quang cấm chế và cửa đá. Phía trên tầng có chướng bích màu xám phân cách với tầng kế tiếp; Hàn Lập không phá chướng bích vì lo ảnh hưởng tới tiếp điểm không gian.","theLucLienQuan":[],"nguon":["@c1918"]},{"id":"tang-thu-hai-cua-bao-thap","name":"Tầng thứ hai của bảo tháp","cn":"","capDo":"khac","parentId":"khong-gian-ben-trong-that-thai-bao-thap","blurb":"Tầng thứ hai được bố trí khôi lỗi bạc có thực lực tương đương tu sĩ Hóa Thần trung kỳ.","detail":"Đây là tầng tiếp theo trên đường Hàn Lập tiến về vị trí tiếp điểm không gian trong bảo tháp.","theLucLienQuan":[],"nguon":["@c1918"]},{"id":"tang-thu-ba-cua-bao-thap","name":"Tầng thứ ba của bảo tháp","cn":"","capDo":"khac","parentId":"khong-gian-ben-trong-that-thai-bao-thap","blurb":"Tầng thứ ba có khoảng mười khôi lỗi bạc Hóa Thần hậu kỳ đại thành phong tỏa cửa thang lầu.","detail":"Lực lượng thủ vệ tại đây mạnh hơn hai tầng dưới nhưng vẫn bị Hàn Lập đánh bại trên đường tiến lên.","theLucLienQuan":[],"nguon":["@c1918"]},{"id":"tang-thu-tu-den-tang-thu-sau-cua-bao-thap","name":"Tầng thứ tư đến tầng thứ sáu của bảo tháp","cn":"","capDo":"khac","parentId":"khong-gian-ben-trong-that-thai-bao-thap","blurb":"Ba tầng này được canh giữ bởi khôi lỗi kim sắc có thực lực tăng dần từ Luyện Hư sơ kỳ đến Luyện Hư hậu kỳ đại thành.","detail":"Khôi lỗi tại tầng sáu đặc biệt khó đối phó, buộc Hàn Lập phải vận dụng vài loại đại thần thông mới có thể vượt qua.","theLucLienQuan":[],"nguon":["@c1918"]},{"id":"tang-thu-bay-cua-bao-thap","name":"Tầng thứ bảy của bảo tháp","cn":"","capDo":"khac","parentId":"khong-gian-ben-trong-that-thai-bao-thap","blurb":"Tầng thứ bảy nằm gần tiếp điểm không gian và được hai khôi lỗi lưu ly Hợp Thể sơ kỳ canh giữ.","detail":"Không gian ban đầu hoàn toàn yên tĩnh. Phá Diệt Pháp Mục giúp Hàn Lập xác định tiếp điểm không gian ở gần phía trước, ngay trước khi hai khôi lỗi lưu ly xuất hiện chặn đường.","theLucLienQuan":[],"nguon":["@c1918"]},{"id":"hang-dong-trang-trong-tinh-thach","name":"Hang động trắng trong tinh thạch","cn":"","capDo":"khac","parentId":null,"blurb":"Một hang động màu trắng ẩn sau khối tinh thạch lớn trên tòa đài cao.","detail":"Hàn Lập dùng Phá Diệt pháp mục và Phạm thánh kim thân đánh vỡ tinh thạch, làm lộ hang động rộng chừng một trượng. Hắn lập tức hóa thành kinh hồng bay vào trong để rời khỏi chiến trường.","theLucLienQuan":[],"nguon":["@c1920"]},{"id":"khong-gian-ben-trong-tran-ma-toa","name":"Không gian bên trong Trấn Ma Tỏa","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian giam giữ Xa Kỵ Cung và nam tử có thanh âm tang thương.","detail":"Bên trong có một vùng thảo nguyên trên không, nơi Xa Kỵ Cung gặp hắc nguyên anh của Hàn Lập và đối thoại với nam tử bí ẩn đang ẩn nấp.","theLucLienQuan":[],"nguon":["@c1928"]},{"id":"khong-gian-than-bi-trong-co-the-cu-bang","name":"Không gian thần bí trong cơ thể Cự Bằng","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian trong hình thái Cự Bằng của Hàn Lập, nơi nguyên anh kim sắc chờ hắc nguyên anh trở về.","detail":"Hắc nguyên anh từ hộp gỗ trở về không gian này rồi nhập vào nguyên anh kim sắc của Hàn Lập, giúp hắn tiếp nhận những tin tức thu được từ Xa Kỵ Cung.","theLucLienQuan":[],"nguon":["@c1928"]},{"id":"cao-nguyen-mau-vang","name":"Cao nguyên màu vàng","cn":"","capDo":"khac","parentId":null,"blurb":"Một vùng cao nguyên mênh mông, hoang vắng và không có cây cỏ.","detail":"Hàn Lập nhìn thấy vùng đất này sau hai canh giờ di chuyển trong hình thái Cự Bằng. Tại đây hắn trở lại hình người và bố trí hàng trăm kiếm quang ẩn trong không gian xung quanh.","theLucLienQuan":[],"nguon":["@c1928"]},{"id":"phe-thanh-nhan-toc","name":"Phế thành Nhân tộc","cn":"","capDo":"thanh","parentId":null,"blurb":"Một tòa thành nhỏ của Nhân tộc đã bị bỏ hoang nhiều năm.","detail":"Nửa tháng sau khi rời chiến trường, Hàn Lập ẩn giấu dao động pháp lực bay qua nơi này. Thần niệm phát hiện điều khác thường khiến hắn dừng độn quang và kinh ngạc quan sát phía dưới.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1935"]},{"id":"can-nha-cu-cua-hua-gia","name":"Căn nhà cũ của Hứa gia","cn":"","capDo":"khac","parentId":null,"blurb":"Điểm đặt chân đã bị bỏ hoang của Hứa gia ở ngoài Trấn Hoàng Thành. Hứa Thiên Vũ cùng hai cháu gái dùng nơi này để chống lại năm tà tu truy đuổi.","detail":"Căn nhà có bài trí cổ xưa, được bạch khí và cấm chế đặc biệt bảo vệ. Cấm chế tại đây còn che giấu căn nguyên dao động, khiến thần niệm của Hàn Lập nhất thời không thể truy xét rõ.","theLucLienQuan":["Hứa gia"],"nguon":["@c1936"]},{"id":"tran-hoang-thanh","name":"Trấn Hoàng Thành","cn":"","aliases":["Thánh Hoàng Thành"],"capDo":"thanh","parentId":"linh-gioi","blurb":"Thành trì do Thánh Hoàng trấn thủ, nơi Hứa gia chuyển đến trước ma kiếp. Đại quân Ma tộc tránh trực tiếp tấn công nơi này dù nhiều cứ điểm xung quanh đã thất thủ.","detail":"Trấn Hoàng Thành là chỗ dựa an toàn của Hứa gia trong ma kiếp. Hàn Lập khuyên Hứa Thiên Vũ cùng hai cháu gái sớm quay về thành sau khi thu thập tin tức về quân Ma tộc quanh khu vực.","theLucLienQuan":["Hứa gia","Nhân tộc","Ma tộc"],"nguon":["@c1936"]},{"id":"thanh-nho-noi-ba-nu-tu-hua-gia-cho-doi","name":"Thành nhỏ nơi ba nữ tử Hứa gia chờ đợi","cn":"","capDo":"thanh","parentId":null,"blurb":"Điểm hội họp của Huyết Linh và ba nữ tử Hứa gia.","detail":"Sau khi thu Hư Hoàng Đỉnh và phá hủy mật thất, Huyết Linh bay về phía thành nhỏ nơi Hứa Thiên Vũ cùng hai nữ tử đang chờ.","theLucLienQuan":["Hứa gia"],"nguon":["@c1937"]},{"id":"dai-sanh-bi-mat","name":"Đại sảnh bí mật","cn":"","capDo":"khac","parentId":"dong-quat","blurb":"Một đại sảnh bí mật rộng hơn một mẫu, được dùng để cất giữ Hư Hoàng Đỉnh.","detail":"Đại sảnh nằm sau cửa đồng bị cấm chế che giấu và ban đầu chỉ có một bàn đá đặt Hư Hoàng Đỉnh. Huyết Linh phá hủy nơi này bằng huyết sắc lôi hỏa sau khi lấy bảo vật.","theLucLienQuan":[],"nguon":["@c1937"]},{"id":"khu-vuc-phia-tay","name":"Khu vực phía tây","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực phần lớn là bình nguyên hoang vắng, tạm thời chưa thấy ma tộc xuất hiện.","detail":"Hàn Lập chỉ nơi này cho các tu sĩ Thiên Mã Môn. Giản Phi Thiên quyết định đưa môn nhân tới đây tìm một nơi hẻo lánh để ẩn thân.","theLucLienQuan":["Thiên Mã Môn"],"nguon":["@c1938"]},{"id":"hac-thuy-son-mach","name":"Hắc Thủy sơn mạch","cn":"","capDo":"vuc","parentId":null,"blurb":"Dãy núi có Ẩn Tông nhất mạch, từng được đề xuất làm nơi lánh nạn cho Thiên Mã Môn.","detail":"Giản Phi Thiên bác bỏ kế hoạch tới Hắc Thủy sơn mạch vì cho rằng nơi này không còn an ổn và khó tránh khỏi thần niệm của cao giai ma tộc.","theLucLienQuan":["Ẩn Tông nhất mạch","Thiên Mã Môn"],"nguon":["@c1938"]},{"id":"cu-ho-hoang-tuyen-dia-hoa","name":"Cự hố Hoàng Tuyền địa hỏa","cn":"","capDo":"khac","parentId":"hoang-tuyen-dia-hoa","blurb":"Cự hố rộng khoảng vài mẫu, là nơi Hoàng Tuyền địa hỏa hiển lộ và che giấu Hoàng Lương thạch linh.","detail":"Nửa trên của hố là đá xám trắng, nửa dưới đen bóng như ngọc và tỏa hàn khí cùng lục mang. Đáy hố bị sương vàng cuồn cuộn che phủ, bên dưới thường truyền ra tiếng nổ và hào quang chớp động.","theLucLienQuan":["Thánh đảo"],"nguon":["@c1939"]},{"id":"dinh-nui-phia-tren-hoang-tuyen-dia-hoa","name":"Đỉnh núi phía trên Hoàng Tuyền địa hỏa","cn":"","capDo":"khac","parentId":"hac-thuy-son-mach","blurb":"Địa điểm ba tu sĩ dựng bẫy chờ bắt Hoàng Lương Thạch Linh.","detail":"Toàn bộ đỉnh núi được bao quanh bằng đại trận và Ngân Tiêu Lôi Võng. Bão tuyết nhân tạo từng phủ kín nơi này để xóa khí tức do nhóm phục kích để lại.","theLucLienQuan":["Thánh Đảo"],"nguon":["@c1940"]},{"id":"cu-ho-suong-vang","name":"Cự hố sương vàng","cn":"","capDo":"khac","parentId":"dinh-nui-phia-tren-hoang-tuyen-dia-hoa","blurb":"Miệng hố trên đỉnh núi dẫn xuống khu vực Hoàng Tuyền địa hỏa.","detail":"Trước lúc Hoàng Lương Thạch Linh xuất hiện, sương vàng trong hố cuộn thành vòng xoáy, tỏa hàn khí làm vách đá kết sương giá vàng và thỉnh thoảng phun bạch khí.","theLucLienQuan":["Thánh Đảo"],"nguon":["@c1940"]},{"id":"ho-lon-co-cam-che","name":"Hố lớn có cấm chế","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực diễn ra trận vây bắt Hoàng Lương thạch linh.","detail":"Quanh hố lớn có nhiều quang trận và cấm chế được kích hoạt thành lưới phong tỏa, nhằm ngăn Hoàng Lương thạch linh chạy xuống địa hỏa.","theLucLienQuan":[],"nguon":["@c1942"]},{"id":"day-nui-mau-xam","name":"Dãy núi màu xám","cn":"","capDo":"khac","parentId":null,"blurb":"Dãy núi nằm trên đường Vũ Khiếu Thiên trở về Thánh đảo, nơi lão bất ngờ rơi vào một cuộc tập kích.","detail":"Khu vực có hai ngọn núi cao vạn trượng tạo thành một khe hẹp. Khi Vũ Khiếu Thiên vừa bay qua, hai ngọn núi đồng loạt nổ tung rồi đổ xuống, khiến đá núi trút khắp xung quanh.","theLucLienQuan":["Thánh đảo"],"nguon":["@c1944"]},{"id":"hai-ngon-nui-phuc-kich","name":"Hai ngọn núi phục kích","cn":"","capDo":"khac","parentId":null,"blurb":"Hai sơn phong che giấu hai Thạch trưởng lão và có thể ngưng tụ thành cự thủ trăm trượng.","detail":"Hai ngọn núi là nơi hai thạch cự nhân ẩn thân để phục kích Vũ Khiếu Thiên. Sau trận chiến, cả hai sơn phong đều sập một nửa và hai thạch cự nhân hiện nguyên hình.","theLucLienQuan":[],"nguon":["@c1945"]},{"id":"tuyen-duong-dao-thoat-cu-cua-han-lap","name":"Tuyến đường đào thoát cũ của Hàn Lập","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Lộ tuyến tại Ma giới mà Hàn Lập từng đi qua và lựa chọn lại trong lúc bị Nguyên Sát truy kích.","detail":"Hàn Lập chạy theo phương hướng mình từng đi qua. Trong hơn nửa ngày đào thoát trên tuyến này, hắn không gặp thêm Ma tộc xuất hiện chặn đường.","theLucLienQuan":["Ma tộc"],"nguon":["@c1947"]},{"id":"khu-vuc-do-huyet-quang-phu-trach","name":"Khu vực do Huyết Quang phụ trách","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Địa bàn tác chiến tại Linh giới do Huyết Quang phụ trách.","detail":"Nguyên Sát tiến vào khu vực này để truy sát Hàn Lập, khiến Huyết Quang yêu cầu nàng phải rời khỏi địa bàn sau khi hai bên hoàn tất giao dịch.","theLucLienQuan":["Ma tộc"],"nguon":["@c1948"]},{"id":"dam-lay-bui-cay-thap","name":"Đầm lầy bụi cây thấp","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Vùng đầm lầy mọc nhiều bụi cây thấp nằm trên đường đào thoát của Hàn Lập.","detail":"Tại đây, Báo Lân Thú tỉnh lại và cảnh báo Hàn Lập rằng phía trước có những kẻ địch mang ác ý đang ẩn giấu.","theLucLienQuan":[],"nguon":["@c1948"]},{"id":"ao-dam-boc-khi-nong","name":"Ao đầm bốc khí nóng","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng ao đầm nơi Hàn Lập bị hơn mười huyết sắc Ma tộc có khả năng phục hồi bao vây.","detail":"Sau hai tháng đào thoát, Hàn Lập trong hình thái ngân sắc cự bằng bị nhóm huyết sắc Ma tộc giữ chân tại đây. Khi giao tranh còn kéo dài, Càn Khôn Bàn và thạch điện đã tiến đến khoảng cách hơn nghìn dặm.","theLucLienQuan":["Ma tộc"],"nguon":["@c1949"]},{"id":"cac-cu-diem-lon-cua-nhan-toc-trong-khu-vuc","name":"Các cứ điểm lớn của Nhân tộc trong khu vực","cn":"","capDo":"khac","parentId":null,"blurb":"Những cứ điểm lớn của Nhân tộc mà Hàn Lập có thể tìm tới để hội họp với đồng tộc.","detail":"Huyết Quang lên kế hoạch phong tỏa đường dẫn tới các cứ điểm này cùng tuyến đường tới Thiên Uyên Thành, nhằm ngăn Hàn Lập nhận được tiếp ứng.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1950"]},{"id":"phe-tich-ngon-nui","name":"Phế tích ngọn núi","cn":"","capDo":"khac","parentId":"ngon-nui-cao","blurb":"Đống đổ nát hình thành sau khi Nguyên Sát dùng ngũ sắc quang trận phá hủy ngọn núi.","detail":"Phế tích có một hố lớn ở trung tâm và bị thần niệm của Nguyên Sát kiểm tra từng phần. Linh khu của Hàn Lập dưới nguyên hình khúc gỗ nằm im tại đây thêm hai canh giờ, sau đó mới khôi phục hình người và rời đi.","theLucLienQuan":["Ma tộc"],"nguon":["@c1951"]},{"id":"son-coc-bi-can-khon-ban-phong-toa","name":"Sơn cốc bị Càn Khôn Bàn phong tỏa","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc nơi hóa thân Hàn Lập ẩn dưới lòng đất để giữ chân Huyết Quang và Nguyên Sát.","detail":"Càn Khôn Bàn bao phủ toàn bộ sơn cốc bằng linh quang đỏ và điều khiển quang cầu rà soát mọi ngóc ngách. Sau đó, Nguyên Sát dùng hơn vạn quạ đen do ma nguyên ngưng tụ để tiếp tục dò tìm sâu dưới lòng đất.","theLucLienQuan":["Ma tộc"],"nguon":["@c1952"]},{"id":"son-coc-co-bai-da","name":"Sơn cốc có bãi đá","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc nơi Nguyên Sát và Huyết Quang chia quân truy bắt các mục tiêu khác nhau.","detail":"Nguyên Sát dùng đàn quạ tìm kiếm đệ nhị Nguyên Anh tại bụi cây trong sơn cốc. Hơn trăm Ma tộc được lệnh canh giữ quanh bãi đá trước khi cùng Nguyên Sát tiếp tục truy đuổi.","theLucLienQuan":["Ma tộc","Đại quân Ma tộc do Huyết Quang thống lĩnh"],"nguon":["@c1953"]},{"id":"ria-khu-vuc-nhan-toc","name":"Rìa khu vực Nhân tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biên hoang vu của lãnh thổ Nhân tộc, nằm gần Man Hoang thế giới.","detail":"Hàn Lập chạy tới khu vực này sau hơn nửa năm bị truy đuổi. Do cổ thú từ Man Hoang thế giới thường vượt qua cấm chế xâm nhập, Nhân tộc không xây thành thị tại đây và Ma tộc cũng không bố trí đại quân.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1954"]},{"id":"tan-cung-nam-thien","name":"Tận cùng Nam Thiên","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Biên giới phía nam của vùng lãnh địa Nhân tộc, tiếp giáp Man Hoang.","detail":"Khu vực có một dãy sơn mạch cực lớn cùng màn sương do siêu cấp pháp trận tạo thành. Hàn Lập vượt qua cấm chế đã suy yếu tại đây để tiến vào Man Hoang, sau đó Nguyên Sát và các hóa thân Huyết Quang cũng bám theo.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1956"]},{"id":"dam-lay-trong-man-hoang","name":"Đầm lầy trong Man Hoang","cn":"","capDo":"khac","parentId":"man-hoang-the-gioi","blurb":"Một vùng đầm lầy nơi Hàn Lập săn giết tử sắc cự sư.","detail":"Hàn Lập giết tử sắc cự sư cấp Luyện Hư hậu kỳ tại đây và lấy yêu đan để luyện Nhiếp Linh Đan. Một ngày sau, Nguyên Sát cùng ba hóa thân Huyết Quang tới kiểm tra tàn tích còn lại.","theLucLienQuan":[],"nguon":["@c1956"]},{"id":"ma-kim-son-mach","name":"Ma Kim sơn mạch","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn mạch nơi Hàn Lập từng giết một thuộc hạ của Bảo Hoa và lấy Huyền Thiên Như Ý Nhận tàn phiến từ một ma viên Hợp Thể Kỳ.","detail":"Khí tức ma thú trên người Hắc Ngạc khiến Hàn Lập nhớ lại cảm ứng từng gặp tại Ma Kim sơn mạch. Từ mối liên hệ giữa địa điểm này, tàn phiến và thuộc hạ đã chết của Bảo Hoa, hắn suy đoán nàng từng ẩn mình trong sơn mạch.","theLucLienQuan":["Ma tộc"],"nguon":["@c1958"]},{"id":"cu-thap-ma-toc-gan-thien-uyen-thanh","name":"Cự tháp Ma tộc gần Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Cự tháp nơi Huyết Quang và các Ma tôn họp bàn chiến sự quanh Thiên Uyên Thành.","detail":"Huyết Quang dưới hình dạng huyết bào thiếu niên nghe thuộc hạ báo cáo kết quả càn quét tại đây. Trong lúc nghị sự, hắn cảm ứng ba đại hóa thân của mình gặp nạn.","theLucLienQuan":["Ma tộc đại quân"],"nguon":["@c1960"]},{"id":"ho-nuoc-do-nhu-mau-tai-ma-gioi","name":"Hồ nước đỏ như máu tại Ma giới","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một hồ máu bí ẩn nằm sâu trong Ma giới.","detail":"Từ sâu trong hồ vang lên tiếng thét giận dữ và thê lương, khiến mặt hồ chấn động trong khoảng thời gian một chén trà. Chương này chưa xác nhận người phát ra tiếng thét.","theLucLienQuan":["Ma tộc"],"nguon":["@c1960"]},{"id":"chien-truong-thach-dien-tai-linh-gioi","name":"Chiến trường thạch điện tại Linh giới","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Chiến trường nơi Bảo Hoa đối đầu các hóa thân Huyết Quang, Nguyên Sát và Lục Cực.","detail":"Bảo Hoa tiêu diệt ba hóa thân Huyết Quang tại đây, sau đó bắn bị thương Lục Cực và ngăn thạch điện truyền tống. Cuối chương, hai thạch nhân lộ nguyên hình và tiếp tục đối đầu Bảo Hoa cùng đại hán.","theLucLienQuan":["Ma tộc"],"nguon":["@c1960"]},{"id":"ho-rong-menh-mong","name":"Hồ rộng mênh mông","cn":"","capDo":"khac","parentId":null,"blurb":"Điểm đến của cuộc truyền tống do Hàn Lập và Lôi Vân Tử thực hiện.","detail":"Song trọng Lôi Quang trận đưa Hàn Lập và Lôi Vân Tử tới không trung phía trên hồ, cách nơi xuất phát hơn ngàn vạn dặm. Hai người xác nhận đã thoát khỏi cảm giác bị giám sát rồi chia tay tại đây.","theLucLienQuan":[],"nguon":["@c1961"]},{"id":"day-nui-da-hoang-vu","name":"Dãy núi đá hoang vu","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực hoang vắng được Hàn Lập chọn làm nơi ẩn náu dưỡng thương.","detail":"Sau ba ngày ba đêm phi hành, Hàn Lập tới dãy núi đá không có dấu vết con người. Hắn độn vào lòng núi, tìm một động quật và bố trí trận kỳ để bế quan hồi phục.","theLucLienQuan":[],"nguon":["@c1961"]},{"id":"lanh-dia-nhan-toc","name":"Lãnh địa Nhân tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực của Nhân tộc được Bảo Hoa chọn làm đích đến mới.","detail":"Sau khi mất dấu Hàn Lập và Lôi Vân Tử, Bảo Hoa quyết định dẫn Hắc Ngạc tới đây tìm linh dược chữa khỏi thương thế, đồng thời chuẩn bị bói toán khi đã tới gần mục tiêu hơn.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1961"]},{"id":"khong-gian-than-bi-trong-tran-ma-toa","name":"Không gian thần bí trong Trấn Ma Tỏa","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian giam giữ Phong Tà và Xa Kỵ Cung bên trong Trấn Ma Tỏa.","detail":"Không gian mờ mịt này đã biến thành một vùng băng địa phủ đầy bông tuyết. Hàn Lập dùng thần niệm hóa thân tiến vào đây để chứng minh mình có Hỗn độn nhị khí và thương lượng phương thức trao đổi pháp quyết luyện hóa.","theLucLienQuan":["Ma tộc"],"nguon":["@c1962"]},{"id":"khu-vuc-man-hoang-gan-nhan-toc","name":"Khu vực man hoang gần Nhân tộc","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực man hoang nơi Hàn Lập ẩn thân và tiếp tục giao dịch với hai ma đầu trong Trấn Ma Tỏa.","detail":"Tại đây, Hàn Lập thu hồi thần niệm hóa thân và Nguyên Anh rồi dành hai ngày hai đêm lĩnh hội phần pháp quyết luyện hóa Hỗn độn nhị khí do Xa Kỵ Cung giao.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1963"]},{"id":"khu-rung-toi","name":"Khu rừng tối","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Khu rừng nơi hóa thân Lục Cực dừng lại điều tức sau khi bị Bảo Hoa gây thương tích.","detail":"Nguyên Sát trông nom Lục Cực tại đây trong lúc nàng dùng linh đan áp chế thương thế do Lạc Nhật chân diễm. Hai người đồng thời bàn về mục đích xuất hiện của Bảo Hoa và kế hoạch hội hợp với một hóa thân khác.","theLucLienQuan":["Ma tộc"],"nguon":["@c1963"]},{"id":"thien-linh-thanh","name":"Thiên Linh thành","cn":"","capDo":"thanh","parentId":"lanh-dia-nhan-toc","blurb":"Một trong ba đại hoàng thành của Nhân tộc, bị đại quân Ma tộc đánh hạ sau năm tháng.","detail":"Phần lớn tu sĩ phòng thủ và nhiều trưởng lão Hợp Thể kỳ tử trận khi thành thất thủ. Ma tộc chặt đổ kình thiên cự thụ biểu tượng, phá hủy gần như toàn bộ kiến trúc rồi đóng quân, xây pháp đài và trồng ma thụ để biến nơi đây thành cứ điểm lâu dài.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1964"]},{"id":"thien-linh-canh","name":"Thiên Linh cảnh","cn":"","capDo":"vuc","parentId":"lanh-dia-nhan-toc","blurb":"Khu vực Nhân tộc có các thế lực còn sót lại sau khi Thiên Linh thành thất thủ.","detail":"Các thế lực Nhân tộc trong khu vực phát hiện Ma tộc có ý định định cư lâu dài tại Thiên Linh thành và khẩn cấp truyền tin tới những cứ điểm lớn khác.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1964"]},{"id":"rung-nguyen-thuy-gan-lanh-dia-moc-toc","name":"Rừng nguyên thủy gần lãnh địa Mộc tộc","cn":"","capDo":"khac","parentId":"khu-vuc-man-hoang-gan-nhan-toc","blurb":"Một vùng rừng Man hoang nằm sát lãnh địa Mộc tộc và chứa tiết điểm nhỏ nối Ma giới với Linh giới.","detail":"Ma tộc dựng một cứ điểm rộng vài dặm quanh tiết điểm, gồm tháp cao và tường trắng. Liên quân Mộc tộc dùng Mộc độn thuật tiến qua khu rừng để bí mật áp sát nơi này.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c1964"]},{"id":"cu-diem-ma-toc-gan-moc-toc","name":"Cứ điểm Ma tộc gần Mộc tộc","cn":"","capDo":"khac","parentId":"rung-nguyen-thuy-gan-lanh-dia-moc-toc","blurb":"Cứ điểm bảo vệ một tiết điểm Ma giới nhỏ gần lãnh địa Mộc tộc.","detail":"Lực lượng trấn thủ ban đầu không phải quân tinh nhuệ nhưng liên tục được bổ sung, khiến nhiều cuộc tiến đánh của các thế lực Mộc tộc địa phương thất bại. Liên quân do Trúc lão cùng đôi nam nữ Hóa Thần hậu kỳ dẫn dắt đang tập kích nơi này, còn Hàn Lập bí mật bám theo họ.","theLucLienQuan":["Ma tộc","Mộc tộc"],"nguon":["@c1964"]},{"id":"tiet-diem-ma-gioi-gan-moc-toc","name":"Tiết điểm Ma giới gần Mộc tộc","cn":"","capDo":"khac","parentId":"cu-diem-ma-toc-gan-moc-toc","blurb":"Một tiết điểm nhỏ nối Ma giới với Linh giới, nằm gần lãnh địa Mộc tộc.","detail":"Tiết điểm hiện ra như một lỗ đen rộng khoảng một mẫu trên không trung, nhỏ hơn nhiều so với các tiết điểm tại khu vực Nhân Yêu lưỡng tộc. Đây là mục tiêu chính mà liên quân Mộc tộc dự định phá hủy.","theLucLienQuan":["Ma tộc","Mộc tộc"],"nguon":["@c1964"]},{"id":"tiet-diem-ma-toc","name":"Tiết điểm Ma tộc","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khe không gian nối Linh giới với Ma giới, gồm hơn mười vách ngăn do không gian chi lực hình thành.","detail":"Hàn Lập hóa thành Thiên phượng để phá liên tiếp các vách ngăn và xuyên qua tiết điểm. Đầu bên Ma giới có hai trạm gác màu đen do vệ sĩ Ma tộc trông coi.","theLucLienQuan":["Ma tộc"],"nguon":["@c1966"]},{"id":"sa-mac-xam","name":"Sa mạc xám","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Sa mạc nằm ngay ngoài tiết điểm, dưới bầu trời vàng nhạt có ba mặt trời đỏ.","detail":"Khu vực có linh khí thưa thớt và ma khí phiêu đãng. Hai trạm gác của vệ sĩ Ma tộc được đặt gần lối ra của tiết điểm.","theLucLienQuan":["Ma tộc"],"nguon":["@c1966"]},{"id":"hap-coc-cuong-phong","name":"Hạp cốc cuồng phong","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Hạp cốc rộng hàng trăm trượng và sâu hơn nghìn trượng, có cuồng phong cùng hàn khí dữ dội.","detail":"Nhiệt độ giảm mạnh theo độ sâu, khiến sương trắng đóng trên vách đá. Sông băng dưới đất nằm tại đáy hạp cốc.","theLucLienQuan":[],"nguon":["@c1966"]},{"id":"song-bang-duoi-dat","name":"Sông băng dưới đất","cn":"","capDo":"khac","parentId":"hap-coc-cuong-phong","blurb":"Con sông phát lam quang nằm dưới đáy hạp cốc, có dòng chảy ngầm cực kỳ cuồng bạo.","detail":"Mặt nước yên tĩnh và không đóng băng dù hàn khí rất mạnh, trong khi hai bờ phủ băng dày. Vật rơi xuống sẽ nhanh chóng đóng băng, chìm vào dòng nước và bị cuốn khỏi phạm vi cảm ứng.","theLucLienQuan":[],"nguon":["@c1966"]},{"id":"sa-mac-mau-vang","name":"Sa mạc màu vàng","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Vùng sa mạc phía Ma giới nơi có tiết điểm được Hàn Lập sử dụng để trở về Linh giới.","detail":"Hàn Lập toàn lực phi hành tới vùng sa mạc này, ngụy trang bằng hắc khí rồi hóa thành Thiên phượng để xuyên qua tiết điểm.","theLucLienQuan":["Ma tộc"],"nguon":["@c1967"]},{"id":"thanh-tri-cua-yeu-toc","name":"Thành trì của Yêu tộc","cn":"","capDo":"thanh","parentId":"linh-gioi","blurb":"Một thành trì trọng yếu của Yêu tộc đang bị đại quân Ma tộc tấn công dữ dội.","detail":"Tình hình chiến sự tại đây tương tự Thiên Uyên thành, với những đợt công kích mãnh liệt của Ma tộc nhằm vào lực lượng phòng thủ.","theLucLienQuan":["Yêu tộc","Ma tộc"],"nguon":["@c1967"]},{"id":"dao-nho-than-bi-giua-nhan-toc-va-yeu-toc","name":"Đảo nhỏ thần bí giữa Nhân tộc và Yêu tộc","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Một hòn đảo bí mật nằm giữa lãnh địa Nhân tộc và Yêu tộc, được dùng làm nơi tổ chức hội nghị cấp Hợp Thể.","detail":"Trong điện phủ có cấm chế bao bọc trên đảo, hơn mười tồn tại Hợp Thể bí mật thảo luận ý đồ chiếm đóng và kế hoạch đưa lượng lớn cổ ma đê giai sang Linh giới.","theLucLienQuan":["Nhân tộc","Yêu tộc","Nhân tộc và Yêu tộc"],"nguon":["@c1967"]},{"id":"khu-lau-cac-yen-tinh-tren-dao","name":"Khu lầu các yên tĩnh trên đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực có linh khí nồng đậm trên đảo, gồm nhiều lầu các độc lập dành cho khách nghỉ ngơi và tu luyện.","detail":"Khu vực gồm bảy tám tòa lầu các độc lập, mỗi tòa có nơi luyện khí, luyện đan và mật thất tu luyện. Ngao Khiếu lão tổ chọn một tòa để nói chuyện riêng với Ngân Nguyệt.","theLucLienQuan":["Yêu tộc"],"nguon":["@c1970"]},{"id":"hap-coc-bi-an-gan-thien-uyen-thanh","name":"Hạp cốc bí ẩn gần Thiên Uyên thành","cn":"","capDo":"khac","parentId":"lanh-dia-nhan-toc","blurb":"Một hạp cốc nằm trong dãy núi cách Thiên Uyên thành hơn mười vạn dặm. Nơi đây được cho là cất giấu truyền tống pháp trận bí mật có thể đưa người trực tiếp vào thành.","detail":"Ba tu sĩ Hỏa Ly Tông gồm chưởng môn, Lý sư đệ và Dương sư đệ tiến vào hạp cốc để kiểm tra pháp trận. Cùng lúc, một thanh niên cầm ngọn núi nhỏ màu đen và nữ đồng trên vai cũng bay về đúng địa điểm này.","theLucLienQuan":["Hỏa Ly Tông","Thiên Uyên thành","Ma tộc"],"nguon":["@c1972"]},{"id":"diem-truyen-tong-bi-mat-cua-thien-uyen-thanh","name":"Điểm truyền tống bí mật của Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Một điểm đặt truyền tống trận cỡ nhỏ dành cho trưởng lão Thiên Uyên thành. Mỗi lượt trận chỉ có thể truyền tống tối đa hai người.","detail":"Hàn Lập dẫn Báo Lân thú tới đây để trở về Thiên Uyên thành nhưng đề phòng địa điểm đã bị Ma tộc biến thành ổ mai phục. Đầu truyền tống bên trong thành có cấm chế và trọng binh bảo vệ nhằm ngăn kẻ địch lợi dụng xâm nhập.","theLucLienQuan":["Thiên Uyên thành","Ma tộc"],"nguon":["@c1973"]},{"id":"day-nui-phia-truoc","name":"Dãy núi phía trước","cn":"","capDo":"vuc","parentId":null,"blurb":"Dãy núi nơi Hàn Lập phát hiện các tu sĩ Nhân tộc đang chạy khỏi ma vân. Cuộc truy đuổi diễn ra gần rìa khu vực này.","detail":"Hơn mười môn nhân Nhân tộc chạy khỏi dãy núi trong khi bạch phát lão giả đoạn hậu. Ma thú và giáp sĩ Ma tộc truy đuổi họ, dẫn tới việc Hàn Lập xuất hiện giải vây ở cuối chương.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1973"]},{"id":"son-coc-dat-truyen-tong-tran","name":"Sơn cốc đặt truyền tống trận","cn":"","capDo":"khac","parentId":"day-nui-phia-truoc","blurb":"Sơn cốc có truyền tống trận mà bạch phát lão giả cùng hai sư đệ tìm kiếm. Nơi này đã trở thành điểm mai phục của cao giai Ma tộc.","detail":"Bạch phát lão giả cùng hai sư đệ và môn nhân tiến vào sơn cốc nhưng bị bảy, tám Ma tộc đồng cấp vây công. Hai sư đệ phải tự bạo Nguyên Anh để làm bị thương đối phương và mở đường thoát cho đồng môn.","theLucLienQuan":["Thiên Uyên thành","Nhân tộc","Ma tộc"],"nguon":["@c1973"]},{"id":"dai-dien-truyen-tong-thien-uyen-thanh","name":"Đại điện truyền tống Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Đại điện chứa hơn mười truyền tống trận và được lực lượng Thiên Uyên thành canh giữ nghiêm ngặt.","detail":"Khu vực có nhiều tầng cấm chế, hơn trăm vệ sĩ thường trực và một lầu các quân trú đóng gần đó. Khi Hàn Lập truyền tống vào, toàn bộ đại điện lập tức bị phong tỏa để đề phòng biến cố.","theLucLienQuan":["Thiên Uyên thành","Lực lượng phòng thủ Thiên Uyên thành"],"nguon":["@c1974"]},{"id":"dau-nguyen-cac","name":"Đâu Nguyên các","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Một địa điểm có danh khí không nhỏ trong Thiên Uyên thành, nơi tổ chức các cuộc giao dịch dành cho tu sĩ cao giai.","detail":"Đâu Nguyên các đang tổ chức một giao dịch hội nhỏ và kín đáo, chỉ cho tu sĩ từ Luyện Hư kỳ trở lên tham gia. Băng Phượng hiện có mặt tại đây, khiến Hàn Lập lập tức lên đường tới đưa nàng trở về.","theLucLienQuan":["Thiên Uyên thành"],"nguon":["@c1975"]},{"id":"truyen-tong-dien-thien-uyen-thanh","name":"Truyền tống điện Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Điện phủ đặt truyền tống trận bên trong Thiên Uyên thành.","detail":"Hàn Lập trở lại Thiên Uyên thành tại đây. Bạch phát lão giả và lão phụ nhân xấu xí cũng xuất hiện từ truyền tống trận rồi được đội vệ sĩ do một Kim vệ dẫn đầu nghênh đón.","theLucLienQuan":["Thiên Uyên thành"],"nguon":["@c1975"]},{"id":"noi-o-cua-bach-truong-lao","name":"Nơi ở của Bạch trưởng lão","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi Băng Phượng bị Thanh Long và những người đã được mua chuộc bao vây. Hàn Lập phá cửa xông vào và suýt giao đấu với Thanh Long tại đây.","detail":"Địa điểm có cửa lớn được gia cố bằng cấm chế và do hai tu sĩ Luyện Hư canh giữ. Cuộc đối đầu giữa Hàn Lập và Thanh Long suýt phá hủy nơi này trước khi Kim Việt thiền sư xuất hiện hòa giải.","theLucLienQuan":["Thiên Uyên thành"],"nguon":["@c1977"]},{"id":"khong-gian-ty-thi-cua-dau-nguyen-cac","name":"Không gian tỷ thí của Đâu Nguyên các","cn":"","capDo":"gioi-nho","parentId":"dau-nguyen-cac","blurb":"Một không gian riêng được Đâu Nguyên các mở dựa vào khe không gian. Nơi này rộng khoảng vài nghìn mẫu và dùng để cách ly những cuộc tranh đấu cấp Hợp Thể.","detail":"Không gian có bầu trời màu xám, một đài cao được gia cố và hệ thống cột trận bố trí xung quanh. Người sử dụng tiến vào bằng truyền tống trận tại tầng cao nhất Đâu Nguyên các.","theLucLienQuan":["Đâu Nguyên các"],"nguon":["@c1979"]},{"id":"dai-cao-ty-thi","name":"Đài cao tỷ thí","cn":"","capDo":"khac","parentId":"khong-gian-ty-thi-cua-dau-nguyen-cac","blurb":"Võ đài nằm trong không gian tỷ thí của Đâu Nguyên các, có đường kính hơn trăm trượng. Bề mặt được cấm chế đặc thù gia cố và có hàng chục cột đá bố trí bao quanh.","detail":"Đài cao là nơi Hàn Lập và Thanh Long thượng nhân bắt đầu cuộc tỷ thí ba kích. Hỗn Thiên Lưỡng Nghi trận được triển khai để bao kín đài và bảo vệ người quan sát.","theLucLienQuan":["Đâu Nguyên các"],"nguon":["@c1979"]},{"id":"tang-cao-nhat-dau-nguyen-cac","name":"Tầng cao nhất Đâu Nguyên các","cn":"","capDo":"khac","parentId":"dau-nguyen-cac","blurb":"Tầng cao nhất của lầu các có một thính đường đặt truyền tống trận. Pháp trận tại đây dẫn thẳng vào không gian tỷ thí riêng.","detail":"Cố lão giả đưa Hàn Lập, Thanh Long thượng nhân và những người quan chiến đến tầng này rồi kích hoạt truyền tống trận.","theLucLienQuan":["Đâu Nguyên các"],"nguon":["@c1979"]},{"id":"thanh-hoang-thanh","name":"Thánh Hoàng thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Thành trì mà Thanh Long thượng nhân dự định tìm đến sau khi rời Thiên Uyên thành.","detail":"Thanh Long quyết định đến Thánh Hoàng thành để tránh Hàn Lập đuổi cùng giết tận. Việc hắn chuyển đến đây cũng giúp tứ đại tông môn Ỷ Thiên thành phân tán lực lượng và truyền thừa giữa hai thành.","theLucLienQuan":["Tứ đại tông môn Ỷ Thiên thành","Thánh Hoàng thành"],"nguon":["@c1982","@c2006"]},{"id":"mat-that-trong-long-nui","name":"Mật thất trong lòng núi","cn":"","capDo":"khac","parentId":null,"blurb":"Điểm truyền tống bên ngoài Thiên Uyên thành, được xây kín trong lòng một ngọn núi.","detail":"Thanh Long và hai đệ tử xuất hiện tại đây sau khi cưỡng ép truyền tống khỏi thành. Động khẩu dẫn ra ngoài được che giấu khéo léo.","theLucLienQuan":["Thiên Uyên thành"],"nguon":["@c1983"]},{"id":"khu-dat-hoang-vu-ngoai-thien-uyen-thanh","name":"Khu đất hoang vu ngoài Thiên Uyên thành","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng đất hoang vắng cách Thiên Uyên thành rất xa.","detail":"Thanh Long cùng hai đệ tử bay qua khu vực này trên đường tới sa mạc và bị Báo Lân thú phục kích tại đây.","theLucLienQuan":[],"nguon":["@c1983"]},{"id":"dai-dien-nghi-su-cua-truong-lao-hoi","name":"Đại điện nghị sự của Trưởng lão hội","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi các trưởng lão Thiên Uyên thành bàn bạc quân vụ và tiếp nhận báo cáo khẩn cấp.","detail":"Ngân phát lão giả và Kim Việt thiền sư đang bàn việc liên quan tới Ma tộc tại đây thì Thiên Uyên vệ xông vào báo tin về thiên tượng tiến giai.","theLucLienQuan":["Trưởng lão hội Thiên Uyên thành","Thiên Uyên vệ"],"nguon":["@c1985"]},{"id":"khu-vuc-cu-tru-cua-han-lap","name":"Khu vực cư trú của Hàn Lập","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Khu vực Hàn Lập cư trú trong Thiên Uyên thành, nằm tại trung tâm thiên tượng tiến giai Hợp Thể hậu kỳ.","detail":"Thiên tượng bao phủ phạm vi rộng quanh khu vực này. Ngân Quang tiên tử cùng hơn hai mươi tu sĩ Luyện Hư kỳ đứng ngoài phạm vi trăm dặm để quan sát.","theLucLienQuan":["Thiên Uyên thành"],"nguon":["@c1985"]},{"id":"thach-thap-noi-han-lap-be-quan","name":"Thạch tháp nơi Hàn Lập bế quan","cn":"","capDo":"khac","parentId":"khu-vuc-cu-tru-cua-han-lap","blurb":"Thạch tháp nơi Hàn Lập trùng kích Hợp Thể hậu kỳ và trực tiếp hứng chịu các đợt thiên kiếp.","detail":"Thạch tháp nằm ở trung tâm biển thiên hỏa rộng hơn trăm dặm. Cấm chế của tháp không đủ sức tự ngăn hỏa hải, nhưng nhiều thủ đoạn do Hàn Lập bố trí liên tiếp bay ra từ đỉnh tháp để hóa giải thiên hỏa và băng trùy.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1986"]},{"id":"mat-that-sau-trong-long-dat","name":"Mật thất sâu trong lòng đất","cn":"","capDo":"khac","parentId":"thach-thap-noi-han-lap-be-quan","blurb":"Không gian bế quan dưới thạch tháp, nơi Hàn Lập vận công tại quan khẩu trọng yếu.","detail":"Hàn Lập ngồi xếp bằng trên bồ đoàn trong mật thất, quanh người có hai tòa tiểu sơn, bảy mươi hai tiểu kiếm kết thành kiếm liên, hắc sắc phù văn và chiến giáp đen. Dù được nhiều lớp phòng hộ bao quanh, trên người hắn vẫn xuất hiện dày đặc những điểm sáng màu xám tỏa âm hàn khí.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1986"]},{"id":"bau-troi-phia-tren-thach-thap","name":"Bầu trời phía trên thạch tháp","cn":"","capDo":"khac","parentId":"thach-thap-noi-han-lap-be-quan","blurb":"Khu vực thiên tượng của hậu kỳ chi kiếp liên tục biến đổi phía trên nơi Hàn Lập bế quan.","detail":"Hỏa vân, phù văn nhiều màu, hình người ngũ sắc và tám mươi mốt hắc giao lần lượt xuất hiện tại đây. Thiên kiếp tiếp tục chuyển hóa qua biển lửa, băng trùy và vô số cự thạch có khối lớn tới hàng nghìn trượng.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1986"]},{"id":"than-thuc-hai-cua-han-lap","name":"Thần thức hải của Hàn Lập","cn":"","aliases":["Biển thần thức của Hàn Lập"],"capDo":"khac","parentId":null,"blurb":"Không gian tinh thần bên trong Hàn Lập, nơi nguyên thần của hắn giao chiến với tâm ma do thiên ngoại ma đầu thúc hóa.","detail":"Thiên ngoại ma đầu lợi dụng lúc Hàn Lập độ thiên kiếp để xâm nhập nơi này và thúc hóa một tâm ma mang dung mạo cùng phần lớn năng lực của hắn. Cuộc chiến trong thần thức hải kiềm chế gần một nửa nguyên thần, pháp lực và thần niệm của Hàn Lập trong khi thân thể thật vẫn phải đối diện thiên kiếp.","theLucLienQuan":[],"nguon":["@c1987"]},{"id":"thach-thap","name":"Thạch tháp","cn":"","capDo":"khac","parentId":null,"blurb":"Công trình nơi Hàn Lập bế quan và vượt thiên kiếp Hợp Thể hậu kỳ.","detail":"Thạch tháp được nhiều tầng cấm chế và pháp trận bảo vệ. Thiên kiếp do tám mươi mốt hắc giao dẫn phát đã đánh vỡ quang mạc phòng hộ, khiến lôi điện trực tiếp giáng vào bên trong.","theLucLienQuan":[],"nguon":["@c1988"]},{"id":"thach-thap-chi-huy-tren-tien-tuyen","name":"Thạch tháp chỉ huy trên tiền tuyến","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Điểm quan sát và chỉ huy của các trưởng lão Thiên Uyên thành khi đại quân Ma tộc áp sát.","detail":"Ngân phát lão giả, Kim Việt thiền sư và các trưởng lão đứng tại đây quan sát quân địch. Hàn Lập cùng Ngân Quang tiên tử cũng lên tháp để hội họp trước khi giao chiến.","theLucLienQuan":["Thiên Uyên thành","Ma tộc"],"nguon":["@c1992"]},{"id":"ma-hai-ngoai-thien-uyen-thanh","name":"Ma hải ngoài Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Vùng ma khí mênh mông bên ngoài Thiên Uyên thành, nơi đại quân Ma tộc tập kết và xuất kích.","detail":"Đàn ma thú, các đội Ma tộc tinh nhuệ, chiến thuyền, phi tháp và vô số chiến xa liên tục tiến ra từ vùng ma hải này để tổng công kích thành.","theLucLienQuan":["Đại quân Ma tộc","Ma tộc"],"nguon":["@c1993"]},{"id":"tuong-thanh-thien-uyen","name":"Tường thành Thiên Uyên","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Tuyến phòng thủ chính của Thiên Uyên thành trong cuộc tổng công kích của Ma tộc.","detail":"Các trưởng lão tập trung tại đây để quan sát quân địch và điều phối phòng thủ. Nhiều pháp trận cùng bốn tế đàn mang Thiên hà tứ bảo được dựng ở khu vực phía trước tường thành.","theLucLienQuan":["Trưởng lão hội Thiên Uyên thành","Nhân tộc","Yêu tộc"],"nguon":["@c1993","@c1994"]},{"id":"lau-cac-tren-thanh-thu","name":"Lầu các trên thành thủ","cn":"","aliases":[],"capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Lầu các được bố trí làm vị trí chờ chiến của Hàn Lập và Thanh Vân tam thập lục sĩ.","detail":"Nơi này được canh phòng nghiêm ngặt và đặt đại trận thượng cổ do ba mươi sáu trận tu vận hành.","theLucLienQuan":["Thiên Uyên thành","Thanh Vân tam thập lục sĩ"],"nguon":["@c1994"]},{"id":"cac-te-dan-thien-ha-tu-bao","name":"Các tế đàn Thiên hà tứ bảo","cn":"","aliases":[],"capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Bốn vị trí đặt các thành viên của Thiên hà tứ bảo trong hệ thống phòng thủ thành.","detail":"Mỗi tế đàn có tu sĩ cao giai điều khiển pháp trận, dẫn lượng lớn linh lực vào một bảo vật để phát động công kích diện rộng.","theLucLienQuan":["Thiên Uyên thành"],"nguon":["@c1994"]},{"id":"dai-sanh-phap-tran","name":"Đại sảnh pháp trận","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi Hàn Lập cùng ba mươi sáu tu sĩ chờ đợi giữa lúc đại chiến diễn ra.","detail":"Đại sảnh được cấm chế bảo vệ nhưng vẫn bị phần uy năng thất tán từ ma âm của ma cầm bốn cánh xuyên vào, khiến các tu sĩ bên trong đau đớn và chảy máu tai. Hàn Lập dùng linh quang màu xám bao phủ nơi này để ngăn thương tổn tiếp diễn.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1995"]},{"id":"khu-phap-tran-phong-bi-sam-nghiem","name":"Khu pháp trận phòng bị sâm nghiêm","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Khu vực tập trung hơn một nghìn pháp trận lớn nhỏ của Thiên Uyên Thành.","detail":"Các pháp trận tại đây liên kết thành một siêu cấp đại trận, tạo cấm chế cấm không bao phủ Thiên Uyên Thành và vùng lân cận. Cấm chế chỉ hạn chế phía Ma tộc, trong khi tu sĩ Nhân Yêu lưỡng tộc vẫn có thể phi hành và độn địa.","theLucLienQuan":["Thiên Uyên Thành","Ma tộc","Nhân Yêu lưỡng tộc"],"nguon":["@c1995"]},{"id":"toa-thap-dieu-khien-thi-khoi-loi","name":"Tòa tháp điều khiển thi khôi lỗi","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi các hắc bào tu sĩ điều khiển hàng trăm thi khôi lỗi ngoài chiến trường.","detail":"Bên trong tháp, mấy trăm hắc bào tu sĩ ngồi xếp bằng, bấm quyết niệm chú trước những con rối phủ phù văn và hắc khí. Sự điều khiển từ đây giúp các thi khôi lỗi tiếp tục chiến đấu và phục hồi sau khi bị Ma tôn phá hủy.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1995"]},{"id":"chien-truong-ngoai-thien-uyen-thanh","name":"Chiến trường ngoài Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Khu vực diễn ra cuộc tổng chiến giữa lực lượng Thiên Uyên Thành và đại quân Ma tộc.","detail":"Hơn trăm phi tháp, khôi lỗi và linh thú của Thiên Uyên Thành đối đầu chiến thuyền, tam giác ma tháp, Ma tộc giáp sĩ cùng ma cầm. Lưu quang, hắc khí và huyết chiến bao phủ chiến trường.","theLucLienQuan":["Thiên Uyên Thành","Ma tộc","Thánh đảo","Cổ ma tộc"],"nguon":["@c1996"]},{"id":"khong-gian-ben-trong-quang-trao","name":"Không gian bên trong quang tráo","cn":"","capDo":"khac","parentId":"chien-truong-ngoai-thien-uyen-thanh","blurb":"Phạm vi vài dặm được quang tráo của không gian pháp trận bao phủ.","detail":"Đây là chiến trường cục bộ nơi Hàn Lập, ngân phát lão giả và Kim Việt đối đầu Huyết Quang hóa thân cùng Hung. Mặt ngoài quang tráo có vô số ngân sắc phù văn bay lượn.","theLucLienQuan":["Thiên Uyên Thành","Ma tộc"],"nguon":["@c1996"]},{"id":"khong-gian-suong-trang","name":"Không gian sương trắng","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian quỷ dị tràn ngập sương trắng, được nối với chiến trường bằng một quang trận dịch chuyển.","detail":"Huyết Quang hóa thân bị quang trận đưa tới nơi này khi định can thiệp vào trận chiến của Hàn Lập. Ngân phát lão giả và Kim Việt thiền sư đã chờ sẵn bên trong để quyết tử ngăn hắn.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c1997"]},{"id":"chien-truong-giao-chien-voi-ma-toc","name":"Chiến trường giao chiến với Ma tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường nơi Hàn Lập đối đầu Hung trong khi các cường giả khác vây công Huyết Quang hóa thân.","detail":"Tại chiến trường này, Hàn Lập giao chiến trực diện với Hung, còn Kim Việt thiền sư và lão giả tóc bạc hợp sức vây công Huyết Quang hóa thân. Những lần va chạm mạnh làm hư không phụ cận vặn vẹo.","theLucLienQuan":["Ma tộc"],"nguon":["@c1998"]},{"id":"chien-truong-trong-khong-gian-phap-tran","name":"Chiến trường trong không gian pháp trận","cn":"","capDo":"khac","parentId":"chien-truong-ngoai-thien-uyen-thanh","blurb":"Khu chiến trường từng được không gian pháp trận phong tỏa, nơi Hàn Lập cùng các cường giả giao chiến với Huyết Quang hóa thân.","detail":"Hàn Lập điều tức và trấn áp dược lực tại đây trong khi Huyết Quang hóa thân đối đầu Kim Việt thiền sư cùng Ngân phát lão giả. Không gian phong tỏa sau đó bị huyết sắc khô lâu phá hủy, rồi khu vực rộng khoảng ngàn mẫu bị hư ảnh Thái Cực Đồ bao phủ.","theLucLienQuan":["Ma tộc","Thiên Uyên thành"],"nguon":["@c2002"]},{"id":"thach-thap-cua-han-lap","name":"Thạch tháp của Hàn Lập","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi ở của Hàn Lập trong Thiên Uyên Thành.","detail":"Bên dưới thạch tháp có một mật thất nằm sâu hơn trăm trượng. Hàn Lập trở về đây cùng Báo Lân Thú rồi lập tức bế quan điều tức.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c2004"]},{"id":"dai-dien-bi-an","name":"Đại điện bí ẩn","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Địa điểm tổ chức hội nghị bí mật của các tu sĩ Hợp Thể sau đại thắng.","detail":"Các trưởng lão Thiên Uyên Thành, sứ giả Thánh Đảo và một số tu sĩ khổ tu tập trung tại đây để đánh giá chiến công, bàn việc báo đáp viện quân và lập kế hoạch truy quét tàn quân Ma tộc.","theLucLienQuan":["Thiên Uyên Thành","Thánh Đảo"],"nguon":["@c2004"]},{"id":"khu-vuc-lan-can-thien-uyen-thanh","name":"Khu vực lân cận Thiên Uyên Thành","cn":"","capDo":"vuc","parentId":"thien-uyen-thanh","blurb":"Vùng quanh Thiên Uyên Thành nơi tàn quân Ma Tộc bị truy quét sau khi đại chiến kết thúc.","detail":"Các nhóm Ma Tộc còn sót lại tại khu vực này bị bao vây tiêu diệt hoặc rút sang hội quân với các đại quân khác. Phía Thiên Uyên Thành không truy kích quá sâu mà bố trí lực lượng trấn giữ biên giới rồi trở về.","theLucLienQuan":["Thiên Uyên Thành","Nhân Yêu hai tộc","Ma Tộc"],"nguon":["@c2005"]},{"id":"to-van-son","name":"Tổ Vân Sơn","cn":"","capDo":"khac","parentId":"khu-vuc-linh-toc-giap-nhan-toc","blurb":"Ngọn núi cao và cứ điểm nổi tiếng của Linh Tộc nằm gần khu vực Nhân Tộc.","detail":"Sau cuộc đồ sát của Thanh niên áo bào vàng, trên núi xuất hiện nhiều hố lớn, di hài, tàn tích và hơn ngàn khí vật vỡ vụn đã mất sạch linh khí.","theLucLienQuan":["Linh Tộc","Tổ Vân Sơn"],"nguon":["@c2007"]},{"id":"khu-vuc-linh-toc-giap-nhan-toc","name":"Khu vực Linh Tộc giáp Nhân Tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biên tiếp giáp giữa địa bàn Linh Tộc và Nhân Tộc.","detail":"Tổ Vân Sơn, một cứ điểm nổi tiếng của Linh Tộc, tọa lạc trong vùng này.","theLucLienQuan":["Linh Tộc","Nhân Tộc"],"nguon":["@c2007"]},{"id":"ngon-nui-tai-dia-ban-linh-toc","name":"Ngọn núi tại địa bàn Linh Tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường nơi thanh niên áo bào vàng dùng tấm lưới bạc đối phó ba đại Thánh Linh.","detail":"Công kích dẫn động thiên địa nguyên khí đã nghiền nát khu vực hơn mười dặm và khiến ngọn núi bị hạ thấp một nửa. Sau trận chiến, pháp khí con mắt màu tím xuất hiện từ đống đá vụn.","theLucLienQuan":["Linh Tộc"],"nguon":["@c2008"]},{"id":"cung-dien-mau-vang-trong-may","name":"Cung điện màu vàng trong mây","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi một lão giả Linh Tộc theo dõi trận chiến từ xa.","detail":"Cung điện nằm cách chiến trường một khoảng không xác định. Tại đây, lão giả tóc bạc quan sát hình ảnh qua tinh cầu màu trắng và quyết định trấn áp thanh niên áo bào vàng.","theLucLienQuan":["Linh Tộc"],"nguon":["@c2008"]},{"id":"khu-rung-nui-giua-thanh-thanh-va-thien-uyen-thanh","name":"Khu rừng núi giữa Thánh Thành và Thiên Uyên Thành","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực thuộc Nhân Tộc, nằm giữa phạm vi do Thánh Thành và Thiên Uyên Thành khống chế.","detail":"Hàn Lập đi vào khu vực này để gặp Diệp tiên tử tại một sơn cốc bí ẩn.","theLucLienQuan":["Nhân Tộc","Thiên Uyên Thành"],"nguon":["@c2008"]},{"id":"van-linh-thai","name":"Vạn Linh Thai","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm Hàn Lập từng gặp Diệp tiên tử trong quá khứ.","detail":"Vạn Linh Thai được nhắc lại khi Diệp tiên tử nhận ra Hàn Lập và nói về lần gặp trước.","theLucLienQuan":["Chân Linh thế gia"],"nguon":["@c2008"]},{"id":"son-coc-hoi-hop","name":"Sơn cốc hội họp","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Sơn cốc được chọn làm địa điểm tập hợp của các chiến lực Nhân Tộc và Linh Tộc trước hành trình Ma Giới.","detail":"Hàn Lập và Diệp tiên tử có mặt tại khu vực này, trong khi đội ngũ Linh Tộc và nhóm Lũng gia lão tổ lần lượt tiến đến. Cung trang nữ tử cùng thuộc hạ bí mật ẩn nấp cách sơn cốc hơn mười dặm để giám sát.","theLucLienQuan":["Nhân Tộc","Linh Tộc"],"nguon":["@c2010"]},{"id":"bo-bien-menh-mong","name":"Bờ biển mênh mông","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Bờ biển rộng lớn mà đoàn tu sĩ tới sau ba tháng bí mật di chuyển.","detail":"Cự thuyền màu xanh của Linh Tộc tàng hình ẩn nấp, vòng tránh các cứ điểm Ma Tộc trong ba tháng rồi đến cạnh bờ biển này.","theLucLienQuan":["Linh Tộc","Nhân Tộc","Ma Tộc"],"nguon":["@c2011"]},{"id":"bien-rong","name":"Biển rộng","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng biển mà cự thuyền màu xanh vượt qua trên đường tới tiết điểm thông đạo.","detail":"Cự thuyền chở đoàn xâm nhập Ma giới bay qua vùng biển rộng trong khoảng hai tháng trước khi tới gần tiết điểm thông đạo đã định.","theLucLienQuan":["Đoàn xâm nhập Ma giới"],"nguon":["@c2012"]},{"id":"tiet-diem-thong-dao-vao-ma-gioi","name":"Tiết điểm thông đạo vào Ma giới","cn":"","capDo":"khac","parentId":null,"blurb":"Điểm xâm nhập Ma giới đã được đoàn người xác định từ trước.","detail":"Khi tới gần tiết điểm, đoàn ngừng sử dụng cự thuyền màu xanh vì kích thước của nó quá lớn và chuyển sang tự bay để tiếp tục hành trình bí mật.","theLucLienQuan":["Đoàn xâm nhập Ma giới"],"nguon":["@c2012"]},{"id":"huyet-thach-son-mach","name":"Huyết Thạch Sơn Mạch","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng sơn mạch hoang vu nằm ở trung tâm Ma giới, có ít Ma tộc trú đóng. Đây là điểm xuất hiện mà đoàn Hàn Lập dự định tới sau khi vượt qua tiết điểm.","detail":"Lũng gia lão tổ lựa chọn tiết điểm tại Huyền Vũ cảnh vì lối này có thể đưa đoàn nhanh chóng vào Huyết Thạch Sơn Mạch, giảm nguy cơ vừa tiến vào Ma giới đã rơi giữa khu vực đông Ma tộc.","theLucLienQuan":["Ma tộc","Đoàn xâm nhập Ma giới"],"nguon":["@c2013","@c2018"]},{"id":"quan-dao-san-ho","name":"Quần đảo san hô","cn":"","capDo":"khac","parentId":"huyen-vu-canh","blurb":"Cụm đảo san hô lớn nhỏ dày đặc trên biển, có cao cấp Ma tộc trú đóng. Đoàn Hàn Lập phải dùng cấm chế ẩn nặc và Ngụy Ma Châu để bí mật tiến vào trung tâm.","detail":"Thiên Thu thánh nữ tạo cấm chế sương trắng che phủ toàn đoàn trước khi họ xâm nhập quần đảo. Nhờ che giấu khí tức và hành tích, đoàn người tiến vào trung tâm mà chưa bị phát hiện.","theLucLienQuan":["Ma tộc","Đoàn xâm nhập Ma giới"],"nguon":["@c2013"]},{"id":"cu-diem-ma-toc-tren-dao-san-ho","name":"Cứ điểm Ma tộc trên đảo san hô","cn":"","capDo":"khac","parentId":"quan-dao-san-ho","blurb":"Thành lũy Ma tộc bảo vệ tiết điểm thông đạo sang Ma giới trên một đảo san hô.","detail":"Cứ điểm chiếm gần nửa hòn đảo, có tường xám cao trăm trượng, quang mạc đen, nhiều tầng cấm chế, quân tuần tra, ma cầm và vùng mây đen sấm chớp bao phủ phía trên.","theLucLienQuan":["Ma tộc"],"nguon":["@c2015"]},{"id":"thong-dao-vao-ma-gioi","name":"Thông đạo vào Ma giới","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Thông đạo phát ra dị quang màu xám, nằm sau phòng tuyến và nhiều tầng cấm chế của Ma tộc.","detail":"Đoàn Hàn Lập phá các lớp phòng thủ, buộc Ma Tôn trấn giữ tránh đường rồi lần lượt bay qua thông đạo để tiến sâu vào Ma giới.","theLucLienQuan":["Ma tộc trấn giữ thông đạo","Đoàn xâm nhập Ma giới"],"nguon":["@c2016"]},{"id":"may-den-phong-ho","name":"Mây đen phòng hộ","cn":"","capDo":"khac","parentId":"thong-dao-vao-ma-gioi","blurb":"Khu vực mây đen chứa lôi võng và các cấm chế bảo vệ đường dẫn tới thông đạo.","detail":"Đoàn cường giả Hợp Thể tiến vào mây đen, phá các lớp cấm chế và dùng Tinh Lôi bình hút sạch lưới điện chắn đường.","theLucLienQuan":["Ma tộc trấn giữ thông đạo"],"nguon":["@c2016"]},{"id":"thong-dao-tiep-diem","name":"Thông đạo tiếp điểm","cn":"","aliases":[],"capDo":"khac","parentId":null,"blurb":"Thông đạo nối Linh giới với Ma giới, được các đoàn người và lực lượng Ma tộc sử dụng.","detail":"Đoàn Nhân tộc–Linh tộc đã vượt qua thông đạo để tiến vào Ma giới. Bảo Hoa yêu cầu Khách Vân che giấu sự việc rồi cùng Hắc Ngạc sử dụng chính lối đi này để trở lại Ma giới.","theLucLienQuan":["Ma tộc","Nhân tộc","Linh tộc","Ám bộ của Bảo Hoa"],"nguon":["@c2017"]},{"id":"ma-nguyen-hai","name":"Ma Nguyên Hải","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng biển là đích đến của đoàn Hàn Lập trong hành trình tìm Tẩy Linh Trì và Tịnh Linh Liên.","detail":"Hai linh vật được cho là nằm trên một đảo nhỏ thần bí ở tận cùng phía đông Ma Nguyên Hải, nhưng vị trí cụ thể chỉ có thể xác định sau khi đoàn tới nơi.","theLucLienQuan":["Ma tộc"],"nguon":["@c2018"]},{"id":"de-ngu-ma-ha","name":"Đệ Ngũ Ma Hà","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một dòng sông nổi danh tại Ma giới, được cân nhắc làm tuyến đường dẫn ra biển.","detail":"Đoàn có thể đi dọc dòng sông để tiến vào biển rồi vượt qua nhiều vùng hải vực tới Ma Nguyên Hải, nhưng phải đối mặt với nguy cơ gặp đàn ma thú và thú biển cấp cao.","theLucLienQuan":["Ma tộc"],"nguon":["@c2018"]},{"id":"huyen-khieu-sa-mac","name":"Huyễn Khiếu sa mạc","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Một trong mười cấm địa của Ma giới và là chướng ngại chính trên tuyến đường bộ tới Ma Nguyên Hải.","detail":"Sa mạc áp chế chín thành tu vi của người tiến vào, đồng thời khiến độn thuật và bảo vật không thể sử dụng. Nếu chỉ đi bộ theo cách thông thường, đoàn phải mất năm sáu chục năm mới vượt qua.","theLucLienQuan":["Ma tộc"],"nguon":["@c2018","@c2064","@c2068"]},{"id":"vung-hoang-da-phia-tay-thao-nguyen","name":"Vùng hoang dã phía tây thảo nguyên","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng hoang dã hiếm khi có Ma tộc đặt chân tới, nằm trên lối dẫn đến Huyễn Khiếu sa mạc.","detail":"Khu vực có ma thú lục địa nhưng số lượng ít hơn ma thú ngoài biển, vì vậy được xem là phần tương đối an toàn của tuyến đường bộ.","theLucLienQuan":["Ma tộc"],"nguon":["@c2018"]},{"id":"hai-vuc","name":"Hải vực","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Tuyến đường thay thế cho hành trình xuyên Huyễn Khiếu sa mạc.","detail":"Đi qua hải vực mất hơn mười năm nhưng có thể nhanh hơn tuyến sa mạc nếu đoàn thám hiểm không tìm đủ Bát Túc Ma Tích.","theLucLienQuan":[],"nguon":["@c2019"]},{"id":"cam-dia-bi-mat-cua-linh-toc","name":"Cấm địa bí mật của Linh tộc","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Cấm địa tại Linh giới, nơi Linh tộc vây khốn sứ giả có Kim Tiên chân hồn.","detail":"Khu vực có mặt đất cháy đen, một pháp trận rộng hơn mười dặm và kim điện lơ lửng trên cao. Tám Thánh Linh Hợp Thể kỳ vận hành đại trận tại đây để khóa sứ giả.","theLucLienQuan":["Linh tộc"],"nguon":["@c2019"]},{"id":"cuu-u-dia-hoa","name":"Cửu u Địa Hỏa","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm có địa hỏa được dự định dùng để luyện hóa chân hồn bị phong ấn.","detail":"Nam tử trong kim điện dự định chuyển sứ giả tới đây rồi phối hợp cửu u Địa Hỏa với chân hỏa của bản thân, luyện hóa đối phương trong mười vạn năm.","theLucLienQuan":["Linh tộc"],"nguon":["@c2019"]},{"id":"thien-tinh-thap","name":"Thiên Tinh Tháp","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Linh tộc bố trí pháp trận để phong ấn chân hồn của một tiên sứ.","detail":"Khu vực này có pháp trận do tám Thánh Linh chủ trì, cung điện màu vàng liên quan tới một thanh âm già nua và Huyễn Quang Thiên Tinh Tháp được dùng để đình trệ vụ tự bạo của Tích Huyết Hoạch Linh Hoa.","theLucLienQuan":["Linh tộc"],"nguon":["@c2020"]},{"id":"bac-minh-tien-cung","name":"Bắc Minh tiên cung","cn":"","capDo":"khac","parentId":"tien-gioi","blurb":"Tiên cung từng xảy ra một trận đại loạn cách thời điểm hiện tại khoảng trăm vạn năm.","detail":"Theo hiểu biết của cự đại nhân ảnh, toàn bộ vật phỏng chế Huyễn Quang Thiên Tinh Tháp từng bị hủy trong trận đại loạn tại đây.","theLucLienQuan":[],"nguon":["@c2020"]},{"id":"gioi-dien-xa-la-cua-dao-si-mat-den","name":"Giới diện xa lạ của đạo sĩ mặt đen","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện nơi đạo sĩ mặt đen cảm nhận phản ứng từ chân hồn chi bài.","detail":"Đây là một giới diện khác với nơi Linh Vương phong ấn đại địch. Tại đây, đạo sĩ mặt đen kiểm tra chân hồn chi bài và quyết định đi tìm người có chân hồn gặp chuyện.","theLucLienQuan":[],"nguon":["@c2021"]},{"id":"phia-dong-thao-nguyen","name":"Phía Đông thảo nguyên","cn":"","aliases":[],"capDo":"khac","parentId":"thao-nguyen","blurb":"Khu vực phía Đông của thảo nguyên Ma giới, nơi Hàn Lập tìm kiếm Thú Vương.","detail":"Hàn Lập chọn hướng Đông vì thần niệm cảm nhận khí tức ma thú tại đây không yếu. Sau khi đàn thú bất ngờ tháo chạy, hắn truy đuổi và phát hiện khu vực có ma thú xanh kịch độc, ma thú màu bạc cùng vòng khói xanh bí ẩn.","theLucLienQuan":["Ma thú"],"nguon":["@c2022"]},{"id":"khu-vuc-thu-trieu","name":"Khu vực thú triều","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Chiến trường tại Ma giới nơi hai hộ pháp Huyết Nha Thành bị đàn ma thú bao vây.","detail":"Thi thể Thú Vương mọc quái sừng năm màu nằm tại đây nhưng đàn thú vẫn chưa tan rã. Hàn Lập giả lập khí tức Ma tộc, cứu hai hộ pháp bằng điện võng rồi chuẩn bị truy sát hơn mười Ngân Cảnh Thú còn sống.","theLucLienQuan":["Huyết Nha Thành","Ma tộc"],"nguon":["@c2023"]},{"id":"huyet-nha-thanh","name":"Huyết Nha Thành","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Thành trì gần thảo nguyên Ma giới, được xây trên một quặng Huyết Quang Tinh.","detail":"Đây là thành nhỏ duy nhất trong phạm vi ngàn vạn dặm và là nơi tu sĩ thường dừng chân trước khi săn ma thú hoặc tiến vào hoang địa. Thành có một Ma tôn tọa trấn, cấm chế phòng hộ và một hội đấu giá sắp diễn ra.","theLucLienQuan":["Huyết Nha Thành"],"nguon":["@c2024","@c2072"]},{"id":"hoang-dia","name":"Hoang địa","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Khu vực Hàn Lập và đồng bạn đang muốn tiến tới.","detail":"Tuyến đường tới hoang địa bị thú triều Điệp Vĩ Thú chiếm giữ tại khu vực phía đông Huyết Nha Thành, buộc đội ngũ phải cân nhắc đối sách khác thay vì trực tiếp vượt qua.","theLucLienQuan":[],"nguon":["@c2024"]},{"id":"khu-vuc-phia-dong-huyet-nha-thanh","name":"Khu vực phía đông Huyết Nha Thành","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Khu vực đang bị thú triều Điệp Vĩ Thú chiếm giữ trên đường tới hoang địa.","detail":"Điệp Vĩ Thú từ sâu trong thảo nguyên tràn tới đây và đã lưu lại khoảng nửa tháng. Độc vụ dai dẳng của đàn thú có thể ăn mòn linh quang hộ thể cùng các biện pháp phòng ngự.","theLucLienQuan":["Huyết Nha Thành"],"nguon":["@c2024"]},{"id":"da-tu-thanh","name":"Dạ Tu thành","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Thành trì gần Huyết Nha Thành nhất được nhắc đến trong cuộc tra hỏi.","detail":"Theo đại hán Ma tộc, dù đi theo lộ trình nhanh nhất thì từ khu vực Huyết Nha Thành tới Dạ Tu thành cũng mất khoảng hai tháng.","theLucLienQuan":["Ma tộc"],"nguon":["@c2025"]},{"id":"kho-diep-sam-lam","name":"Khô Diệp Sâm Lâm","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu rừng nằm trên tuyến đường vòng phía nam nhằm tránh thú triều.","detail":"Đại hán Ma tộc nêu việc vượt qua Khô Diệp Sâm Lâm ở phía nam như một phương án vòng tránh các con đường phía đông đang bị Điệp Vĩ thú chiếm giữ.","theLucLienQuan":["Ma tộc"],"nguon":["@c2025"]},{"id":"thao-nguyen-phia-bac","name":"Thảo nguyên phía bắc","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Tuyến địa hình phía bắc có thể dùng để vòng tránh thú triều.","detail":"Thảo nguyên phía bắc được đại hán Ma tộc đề cập như hướng vòng còn lại khi những con đường tiến về phía đông đều bị Điệp Vĩ thú phong tỏa.","theLucLienQuan":["Ma tộc"],"nguon":["@c2025"]},{"id":"mo-quang-huyet-quang-tinh","name":"Mỏ quặng Huyết Quang tinh","cn":"","capDo":"khac","parentId":"huyet-nha-thanh","blurb":"Mỏ quặng nằm gần Huyết Nha thành.","detail":"Mỏ cung cấp đá Huyết Quang tinh có hiệu quả phá pháp, được dùng làm vật liệu xây tường thành.","theLucLienQuan":["Huyết Nha Thành"],"nguon":["@c2026"]},{"id":"ngon-nui-da-trong-huyet-nha-thanh","name":"Ngọn núi đá trong Huyết Nha thành","cn":"","capDo":"khac","parentId":"huyet-nha-thanh","blurb":"Ngọn núi đá cao vài trăm trượng chiếm một góc Huyết Nha thành.","detail":"Hơn phân nửa ngọn núi được bao quanh bởi các thạch tháp trắng xám đang xây dựng, bên ngoài có Ma tộc tinh nhuệ tuần tra. Trên sườn núi có thạch điện đỏ sẫm được liên hệ với Ma tôn Bính Thiên Nhận.","theLucLienQuan":["Huyết Nha Thành"],"nguon":["@c2026"]},{"id":"thach-dien-do-sam","name":"Thạch điện đỏ sẫm","cn":"","capDo":"khac","parentId":"ngon-nui-da-trong-huyet-nha-thanh","blurb":"Thạch điện nằm trên sườn ngọn núi đá trong Huyết Nha thành.","detail":"Công trình được suy đoán là nơi cư trú và tu luyện của Ma tôn Bính Thiên Nhận, nhưng chương này chưa xác nhận ông đang ở trong điện.","theLucLienQuan":["Huyết Nha Thành"],"nguon":["@c2026"]},{"id":"khu-quay-hang-huyet-nha-thanh","name":"Khu quầy hàng Huyết Nha thành","cn":"","capDo":"khac","parentId":"huyet-nha-thanh","blurb":"Khu giao dịch đông đúc nằm trên một con đường nhỏ hẹp trong Huyết Nha thành.","detail":"Hai bên đường có nhiều quầy hàng Ma tộc cùng khách mua bán. Hàn Lập tới đây sau khi tách khỏi đoàn và tỏ ra vui vẻ trước cảnh giao dịch quen thuộc.","theLucLienQuan":["Huyết Nha Thành"],"nguon":["@c2026"]},{"id":"nga-tu-cho-ma-toc","name":"Ngã tư chợ Ma tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Khu giao dịch gồm nhiều quầy hàng và cửa hàng phục vụ Ma tộc cao giai.","detail":"Hàn Lập đổi được Dị Ma Kim và tìm thấy hai loại linh dược tuyệt tích ở Linh giới tại khu vực này. Khi trời tối, người đi đường thưa dần và các cửa hàng đóng cửa để chuẩn bị giới nghiêm.","theLucLienQuan":["Ma tộc"],"nguon":["@c2028"]},{"id":"phong-kin-tai-nha-tro","name":"Phòng kín tại nhà trọ","cn":"","capDo":"khac","parentId":null,"blurb":"Căn phòng riêng được Hàn Lập thuê để kiểm tra Dị Ma Kim trong đêm.","detail":"Hàn Lập bố trí nhiều tầng cấm chế tại đây trước khi bổ đôi Dị Ma Kim. Căn phòng trở thành nơi hắn trấn áp cột sáng, phong cấm quang cầu, dò xét năng lượng linh-ma dung hợp và thử hấp thu một phần.","theLucLienQuan":[],"nguon":["@c2028"]},{"id":"cung-dien-dau-gia-tai-huyet-nha-thanh","name":"Cung điện đấu giá tại Huyết Nha Thành","cn":"","capDo":"khac","parentId":"huyet-nha-thanh","blurb":"Địa điểm tổ chức hội đấu giá định kỳ của Ma tộc tại Huyết Nha Thành. Khi Hàn Lập tiến vào, bên trong đã tập trung khoảng ba, bốn nghìn Ma tộc cao giai.","detail":"Cung điện nằm tại một góc thành, có phòng đấu giá hình tròn với các bậc thang dạng phễu, ghế băng màu xanh và thạch đài đen ở trung tâm. Trên vách có đồ án quái thú, còn một cửa nhỏ bên dưới cung điện dẫn ra khu vực thạch đài.","theLucLienQuan":["Huyết Nha Thành","Ma tộc"],"nguon":["@c2029"]},{"id":"thao-nguyen-ngoai-huyet-nha-thanh","name":"Thảo nguyên ngoài Huyết Nha Thành","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Khu vực ngoài Huyết Nha Thành nơi Ma tộc săn giết ma thú. Tài liệu thu được tại đây thường được mang vào thành đấu giá để đổi lấy đan dược và ma khí.","detail":"Ma tộc cao giai hoạt động trên thảo nguyên săn bắt ma thú rồi đưa những tài liệu không cần dùng về Huyết Nha Thành trao đổi, sau đó tiếp tục quay lại khu vực săn bắt.","theLucLienQuan":["Ma tộc","Huyết Nha Thành"],"nguon":["@c2029"]},{"id":"kho-tich-thanh","name":"Khô Tịch thành","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Thành trì thuộc Ma giới và là địa bàn của Hải gia.","detail":"Khô Tịch thành nằm cách xa Huyết Nha Thành. Hải gia, một luyện khí thế gia lớn, lấy nơi đây làm địa bàn.","theLucLienQuan":["Hải gia"],"nguon":["@c2032"]},{"id":"tuong-thanh-huyet-nha-thanh","name":"Tường thành Huyết Nha Thành","cn":"","capDo":"khac","parentId":"huyet-nha-thanh","blurb":"Vành tường thành có cấm chế bảo vệ Huyết Nha Thành.","detail":"Người trong lục quang và người trong hôi quang lần lượt vượt qua cấm chế tại đây sau khi chạm trán đội tuần tra. Hàn Lập cũng âm thầm xuyên qua cấm chế mà không bị ma khí cảm ứng phát hiện.","theLucLienQuan":["Huyết Nha Thành","Ma vệ Huyết Nha Thành"],"nguon":["@c2034"]},{"id":"phien-loan-thach-den-tuyen","name":"Phiến loạn thạch đen tuyền","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Vùng loạn thạch cách Huyết Nha Thành hơn vạn dặm.","detail":"Dương lão nhị dẫn Huyết Nha Thành chủ tới đây để thương lượng về Thánh Chuyên và Khấp Linh bí tàng. Đây cũng là nơi cả hai đồng thời bị những đòn đánh lén chưa rõ nguồn gốc.","theLucLienQuan":["Huyết Nha Thành"],"nguon":["@c2035"]},{"id":"loi-hai","name":"Lôi hải","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Khu vực tại Ma giới có liên hệ với Lôi Hải Thất Sát.","detail":"Dương lão nhị tự nhận xuất thân từ Lôi hải nhưng phủ nhận mình là thành viên của Lôi Hải Thất Sát.","theLucLienQuan":["Lôi Hải Thất Sát"],"nguon":["@c2035","@c2082","@c2110","@c2150"]},{"id":"noi-khap-linh-thanh-to-toa-hoa","name":"Nơi Khấp Linh thánh tổ tọa hóa","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Di địa của Khấp Linh thánh tổ từng bị hai thế lực cướp phá.","detail":"Lôi Hải Thất Sát và Thiên Phòng Sơn từng tranh đoạt di vật tại đây. Trong lúc hỗn loạn, Huyết Nha Thành chủ đã bí mật lấy ba trong bốn khối Thánh Chuyên.","theLucLienQuan":["Lôi Hải Thất Sát","Thiên Phòng Sơn"],"nguon":["@c2035"]},{"id":"khap-linh-bi-tang","name":"Khấp Linh bí tàng","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Bảo tàng bí mật của Khấp Linh thánh tổ, được Khấp Linh bí đồ chỉ dẫn.","detail":"Bí tàng được truyền rằng chứa nhiều bảo vật quý. Dương lão nhị đặc biệt nhắc tới Mặc linh thánh thuyền như một trong những chí bảo nằm trong đó.","theLucLienQuan":[],"nguon":["@c2035"]},{"id":"huyen-da-thanh","name":"Huyễn Dạ Thành","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Một thành trì tại Ma giới được chọn làm điểm tái hội họp của nhóm tu sĩ Nhân tộc sau khi phá vòng vây Hấp Ma Nghĩ.","detail":"Nhóm Lũng gia lão tổ dự định tự mình vượt qua vùng man hoang rồi đến Huyễn Dạ Thành. Điểm hẹn là khách sạn lớn nhất trong thành vào cùng ngày hai năm sau, và người đến quá hạn sẽ không được chờ tiếp.","theLucLienQuan":["Nhóm tu sĩ Nhân tộc của Lũng gia lão tổ"],"nguon":["@c2039","@c2047","@c2083"]},{"id":"ma-nghi-chi-hai","name":"Ma Nghĩ Chi Hải","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vòng vây khổng lồ do vô số Hấp Ma Nghĩ hợp thành quanh khu vực Huyết Nha Thành.","detail":"Hấp Ma Nghĩ có thể dùng một cụm nhỏ làm mồi nhử trong khi đại quân ẩn trên cao, sau đó bất ngờ phủ xuống và khép kín cả trời đất. Cuộc phục kích tại đây khiến đội ngũ Ma tộc tan rã và chạy trốn về nhiều hướng.","theLucLienQuan":["Ma tộc","Huyết Nha Thành"],"nguon":["@c2040"]},{"id":"nghi-hai-cach-huyet-nha-thanh-ba-bon-van-dam","name":"Nghĩ Hải cách Huyết Nha Thành ba bốn vạn dặm","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng Hấp Ma Nghĩ thứ hai chặn đường Hàn Lập sau khi hắn thoát khỏi cuộc phục kích ban đầu.","detail":"Vùng Nghĩ Hải này xuất hiện dưới dạng một đám mây tím đang tiến đến. Hàn Lập dịch chuyển vào bên trong, thử nhiều loại công kích rồi dùng Thanh Trúc Phong Vân Kiếm cưỡng ép mở đường.","theLucLienQuan":[],"nguon":["@c2040"]},{"id":"nghi-hai","name":"Nghĩ Hải","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Biển Hấp Ma Nghĩ dày đặc bao vây và truy sát Ma tộc, ma thú cùng nhóm Hàn Lập.","detail":"Nghĩ Hải hình thành bởi số lượng khổng lồ Hấp Ma Nghĩ. Khi Cự Nghĩ biến dị xuất hiện, hơn phân nửa số Ma tộc còn chống cự tử vong; trùng triều kéo dài khoảng nửa năm, hủy diệt bảy tám thành trì và cắn nuốt hàng triệu Ma tộc.","theLucLienQuan":["Huyết Nha Thành","Ma tộc"],"nguon":["@c2041"]},{"id":"khu-vuc-ngoai-huyet-nha-thanh-nghin-van-dam","name":"Khu vực ngoài Huyết Nha Thành nghìn vạn dặm","cn":"","capDo":"khac","parentId":"huyet-nha-thanh","blurb":"Khu vực trong Nghĩ Hải nơi ba người Hải gia và ba anh em nhà Nam Cung bị Cự Nghĩ biến dị tập kích.","detail":"Sáu Ma tộc Luyện Hư đã mở đường hơn trăm dặm và tưởng sắp tới rìa Nghĩ Hải tại khu vực này. Hàng trăm Cự Nghĩ biến dị xuất hiện, khiến ba người Hải gia bỏ chạy và ba anh em nhà Nam Cung mắc kẹt.","theLucLienQuan":["Hải gia","Nam Cung gia Ma tộc"],"nguon":["@c2041"]},{"id":"man-hoang-chi-dia-ma-gioi","name":"Man hoang chi địa Ma giới","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng hoang dã nguy hiểm của Ma giới, nơi Hàn Lập cắt đuôi Hấp Ma Nghĩ và thu thập nhiều tài nguyên hiếm.","detail":"Man hoang chi địa là vùng nguy hiểm đối với Ma tộc bình thường nhưng không gây uy hiếp lớn cho Hàn Lập. Sau khi tiến vào đây, hắn thực sự bỏ xa Hấp Ma Nghĩ, đồng thời tìm được Phong Viêm Tinh cùng hơn mười loại tài liệu và linh dược hiếm gặp tại Linh giới.","theLucLienQuan":["Ma tộc"],"nguon":["@c2041"]},{"id":"rung-dai-thu-choc-troi","name":"Rừng đại thụ chọc trời","cn":"","capDo":"khac","parentId":"man-hoang-chi-dia-ma-gioi","blurb":"Khu rừng có những cây đại thụ cao tới vài trăm trượng trong man hoang chi địa.","detail":"Một năm sau trùng triều, Hàn Lập xuất hiện trên khu rừng này trong lúc bị đàn quái điểu mặt cưu có lông đỏ truy đuổi. Hắn dùng hơn mười đạo kiếm quang chém chết những con dẫn đầu và buộc đàn còn lại dừng truy kích.","theLucLienQuan":[],"nguon":["@c2041"]},{"id":"noi-hai","name":"Nội hải","cn":"","capDo":"vuc","parentId":"ma-nguyen-hai","blurb":"Vùng biển nằm sát khu rừng biên giới, có quái ngư màu lam và những hải thú mạnh hoạt động về đêm.","detail":"Hàn Lập tiến vào nội hải sau khi rời hạp cốc. Nơi đây nguy hiểm hơn khi trời tối do khí tức của hải thú cường đại xuất hiện, nhưng mức độ nguy hiểm vẫn không thể so với ngoại hải.","theLucLienQuan":[],"nguon":["@c2042"]},{"id":"hon-dao-vo-danh","name":"Hòn đảo vô danh","cn":"","capDo":"khac","parentId":"vung-bien-vo-danh","blurb":"Một hòn đảo trong vùng biển vô danh, nơi Hàn Lập tạm dừng tu luyện trước khi tiếp tục hành trình.","detail":"Hàn Lập bố trí pháp trận trên đảo, tu luyện Bách Mạch Luyện Bảo Quyết và Luyện Thần Thuật rồi rời đi vào sáng hôm sau.","theLucLienQuan":[],"nguon":["@c2043"]},{"id":"son-mac-vo-danh-o-ma-gioi","name":"Sơn mạc vô danh ở Ma giới","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Một vùng núi rừng ẩm ướt phủ sương mù nhiều màu, có phạm vi lớn hơn dự liệu. Hàn Lập phải bay hơn mười ngày mới tiếp cận rìa bên kia.","detail":"Khu vực có ma thú ẩn trong sương mù và đại ma cầm thường hoạt động ở độ cao trên vạn trượng. Hàn Lập chọn bay ở độ cao khoảng một nghìn trượng nhưng vẫn nhiều lần bị ma thú tập kích.","theLucLienQuan":["Bạch gia"],"nguon":["@c2043"]},{"id":"tu-quang-thu-khong-lo","name":"Tử Quang Thụ khổng lồ","cn":"","capDo":"khac","parentId":"son-mac-vo-danh-o-ma-gioi","blurb":"Một Tử Quang Thụ cao hơn ba nghìn trượng nằm gần ngọn núi ở rìa sơn mạc.","detail":"Đoàn người Bạch gia bị hơn ba mươi con dơi đỏ thẫm vây khốn tại đây. Trên ngọn cây mọc nhiều Tử Linh quả quý hiếm.","theLucLienQuan":["Bạch gia"],"nguon":["@c2043"]},{"id":"ma-quan-huyen-da-thanh","name":"Ma quán Huyễn Dạ thành","cn":"","capDo":"khac","parentId":"huyen-da-thanh","blurb":"Cơ sở truyền thụ ma công cơ bản cho ma tộc cấp thấp trong Huyễn Dạ thành.","detail":"Ma quán có chức năng tương tự đạo quán truyền pháp tại Linh giới, chuyên truyền thụ ma công cơ bản cho đông đảo ma tộc cấp thấp.","theLucLienQuan":[],"nguon":["@c2046"]},{"id":"van-no-thap-cu-thap","name":"Vạn Nô Tháp","cn":"","capDo":"khac","parentId":"huyen-da-thanh","blurb":"Cự tháp thương nghiệp tại Huyễn Dạ thành, chuyên kinh doanh nô lệ, ma thú và ma tinh khôi lỗi.","detail":"Tầng đầu là điện phủ tiếp khách. Các tầng khác được kết nối bằng Truyền Tống trận và bố trí cấm chế, khôi lỗi canh cửa cùng khu pháp trận giam nô lệ.","theLucLienQuan":["Vạn Nô Tháp"],"nguon":["@c2047"]},{"id":"khu-giam-no-le-van-no-thap","name":"Khu giam nô lệ của Vạn Nô Tháp","cn":"","capDo":"khac","parentId":"van-no-thap-cu-thap","blurb":"Khu vực phía sau cửa vàng trong Vạn Nô Tháp, dùng để giam và trưng bày nô lệ.","detail":"Không gian này chứa nhiều pháp trận tạo thành các cột sáng trắng ngà. Các nô lệ Ma tộc từ Luyện Khí đến Kết Đan bị gieo cấm chế và giam riêng trong từng cột.","theLucLienQuan":["Vạn Nô Tháp"],"nguon":["@c2047"]},{"id":"thanh-linh-vien","name":"Thánh Linh viện","cn":"","capDo":"khac","parentId":"huyen-da-thanh","blurb":"Khu lưu trú cao cấp dành cho cao giai ma tộc tại Huyễn Dạ thành.","detail":"Thánh Linh viện được xây dựa vào vách núi cao hơn ngàn trượng, có nhiều lầu các và động phủ. Hàn Lập tới đây thuê chỗ ở trong thời hạn một năm.","theLucLienQuan":["Thánh Linh viện"],"nguon":["@c2049"]},{"id":"lau-cac-han-lap-thue","name":"Lầu các Hàn Lập thuê","cn":"","capDo":"khac","parentId":"thanh-linh-vien","blurb":"Lầu các có cấm chế cách ly được Hàn Lập thuê tại Thánh Linh viện.","detail":"Công trình nửa chìm trong vách đá và nửa nhô ra ngoài. Hàn Lập thuê nơi này trong một năm, mở cấm chế rồi dùng tầng cao nhất để giải cấm chế và hỏi chuyện Chu Quả Tâm.","theLucLienQuan":["Thánh Linh viện"],"nguon":["@c2049"]},{"id":"tieu-linh-thien","name":"Tiểu Linh Thiên","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một mảnh không gian vỡ đã gần hình thành tiểu giới độc lập, có kích thước xấp xỉ Quảng Hàn Giới nhưng linh khí kém hơn Linh Giới.","detail":"Tiểu Linh Thiên tách khỏi một giới diện và dịch chuyển theo quỹ tích trong hư không, khiến cửa vào xuất hiện khó lường. Nơi đây có hơn một ức Nhân tộc cùng khoảng bảy, tám dị tộc sinh sống; một bộ phận cư dân có thể là những người phi thăng từ hạ giới thất bại rồi vô tình rơi vào tiểu giới.","theLucLienQuan":["Nhân tộc tại Tiểu Linh Thiên"],"nguon":["@c2050"]},{"id":"thanh-tri-bach-gia","name":"Thành trì Bạch gia","cn":"","capDo":"thanh","parentId":"huyen-da-thanh","blurb":"Nơi ở kiên cố của Bạch gia, tọa lạc bên trong Huyễn Dạ thành.","detail":"Thành trì được xây bằng vật liệu xám nhạt mà Hàn Lập không nhận ra, có tường thành liền khối bóng như ngọc và tỏa khí tức uy nghiêm. Cự môn cao hơn trăm trượng, bên ngoài đặt hàng tượng ma thú, có tám Ma tộc hoàng bào canh giữ và nhiều tầng cấm chế bảo vệ.","theLucLienQuan":["Bạch gia","Hổ Sát vệ"],"nguon":["@c2051"]},{"id":"mach-khoang-trong-yeu-bach-gia","name":"Mạch khoáng trọng yếu của Bạch gia","cn":"","capDo":"khac","parentId":"huyen-khieu-sa-mac","blurb":"Một mạch khoáng quan trọng của Bạch gia nằm trong Huyễn Khiếu Sa Mạc, hiện bị ma thú Ma Tôn cấp chiếm giữ.","detail":"Mạch khoáng này đã bị một ma thú có thực lực Ma Tôn cấp chiếm cứ suốt vài năm. Bạch gia dự định huy động nhiều Ma Tôn đánh đuổi nó để khôi phục quyền khai thác.","theLucLienQuan":["Bạch gia"],"nguon":["@c2052"]},{"id":"mach-khoang-hoa-van-thach","name":"Mạch khoáng Hỏa Vân thạch","cn":"","aliases":["Mạch khoáng Bạch gia","Hỏa Vân Khoáng Mạch"],"capDo":"khac","parentId":"huyen-khieu-sa-mac","blurb":"Mạch khoáng lớn thuộc Bạch gia, nằm sâu trong Huyễn Khiếu sa mạc và có trữ lượng Hỏa Vân thạch đỉnh giai dồi dào. Nơi này đang bị một ma thú có pháp lực tương đương Ma Tôn hậu kỳ đại thành chiếm giữ.","detail":"Mạch khoáng chứa lượng lớn Hỏa Vân thạch có giá trị cao và tích tụ chân hỏa chi khí. Ma thú chiếm mỏ đang hấp thu nguồn hỏa khí này để tăng tiến tu vi, khiến Bạch gia phải tập hợp nhiều Ma Tôn nhằm đánh trọng thương và xua đuổi nó.","theLucLienQuan":["Bạch gia"],"nguon":["@c2053"]},{"id":"bach-gia-tai-huyen-da-thanh","name":"Bạch gia tại Huyễn Dạ Thành","cn":"","capDo":"khac","parentId":"huyen-da-thanh","blurb":"Cơ sở của Bạch gia tại Huyễn Dạ Thành, nơi Hàn Lập thường xuyên lui tới trước chuyến đi Huyễn Khiếu sa mạc.","detail":"Hàn Lập nhiều lần đến đây trao đổi với Ngũ muội về luyện thể thuật, ma công và các loại bí thuật. Bạch gia cũng tập hợp lực lượng cho hành động khu trục ma thú tại Huyễn Khiếu sa mạc.","theLucLienQuan":["Bạch gia"],"nguon":["@c2054"]},{"id":"cua-thanh-huyen-da-thanh","name":"Cửa thành Huyễn Dạ Thành","cn":"","capDo":"khac","parentId":"huyen-da-thanh","blurb":"Khu vực tập kết của đội ngũ Bạch gia trước khi tiến vào Huyễn Khiếu sa mạc.","detail":"Hàn Lập tới một sườn đất ngoài cửa thành và gặp Bạch Giao, Ngũ muội, Long Thiên quân, Hàn Kỳ, Bạch Vân Hinh cùng sáu tu sĩ Luyện Hư. Từ đây cả đoàn thi triển độn quang bay về phía Huyễn Khiếu sa mạc.","theLucLienQuan":["Bạch gia"],"nguon":["@c2054"]},{"id":"oc-dao-ngan-xuyen","name":"Ốc đảo Ngân Xuyên","cn":"","capDo":"khac","parentId":"huyen-khieu-sa-mac","blurb":"Ốc đảo rộng vài dặm trong Huyễn Khiếu sa mạc, là nơi Bạch gia thiết lập cứ điểm gần mạch khoáng.","detail":"Ốc đảo có hồ nước đường kính khoảng nửa dặm, xung quanh mọc nhiều bụi cây. Cứ điểm Bạch gia tại đây được cấm chế bảo vệ khỏi bão cát và là nơi đoàn khu trục dừng chân sau hơn nửa tháng xuyên sa mạc.","theLucLienQuan":["Bạch gia"],"nguon":["@c2056"]},{"id":"cu-diem-bach-gia-tai-ngan-xuyen","name":"Cứ điểm Bạch gia tại Ngân Xuyên","cn":"","capDo":"khac","parentId":"oc-dao-ngan-xuyen","blurb":"Cứ điểm của Bạch gia nằm cạnh hồ nước trong ốc đảo Ngân Xuyên.","detail":"Cứ điểm gồm các kiến trúc màu xám với mái hình cầu ngược và được cấm chế bao phủ. Khi đoàn khu trục đến nơi, pháp trận cùng cấm chế vẫn nguyên vẹn nhưng toàn bộ người trấn giữ đã biến mất.","theLucLienQuan":["Bạch gia"],"nguon":["@c2056"]},{"id":"lam-boc-ho","name":"Lam Bộc Hồ","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu vực xa Huyễn Dạ Thành, được điển tịch ghi nhận là nơi Huyết Nha Mễ sinh trưởng.","detail":"Hai huynh muội Bạch gia từng gặp một đạo hữu tại Lam Bộc Hồ và tình cờ trao đổi được vài viên Huyết Nha Mễ. Khoảng cách từ nơi này đến Huyễn Dạ Thành rất xa.","theLucLienQuan":["Bạch gia"],"nguon":["@c2057","@c2066","@c2115"]},{"id":"con-cat-khong-lo","name":"Cồn cát khổng lồ","cn":"","capDo":"khac","parentId":"mach-khoang-trong-yeu-bach-gia","blurb":"Cồn cát cao hàng nghìn trượng che giấu cửa dự bị dẫn vào mạch khoáng Bạch gia.","detail":"Bên trong cồn cát vọng ra tiếng quỷ khóc và tiếng gào quái dị. Sau khi lớp cát được dời đi, một cửa đồng dẫn xuống mạch khoáng hiện ra.","theLucLienQuan":["Bạch gia"],"nguon":["@c2057"]},{"id":"thong-dao-cua-du-bi","name":"Thông đạo cửa dự bị","cn":"","capDo":"khac","parentId":"mach-khoang-trong-yeu-bach-gia","blurb":"Lối bí mật chưa bố trí cấm chế, được đoàn Bạch gia sử dụng để tập kích ma thú trong mạch khoáng.","detail":"Thông đạo có vách đá xanh nhạt và chỉ hai huynh muội Bạch gia biết. Cuối lối đi là một vách núi đỏ thẫm ngăn cách với khu vực rực lửa dưới lòng đất.","theLucLienQuan":["Bạch gia"],"nguon":["@c2057"]},{"id":"the-gioi-ruc-lua-duoi-long-dat","name":"Thế giới rực lửa dưới lòng đất","cn":"","capDo":"khac","parentId":"mach-khoang-trong-yeu-bach-gia","blurb":"Khu vực nóng rực nằm sâu trong mạch khoáng Bạch gia, phía sau vách núi đỏ thẫm.","detail":"Nơi đây có nền nham thạch nóng và vô số măng đá tím hồng. Đoàn người nhận định ma thú có thể ẩn náu tại khu vực có mạch khoáng đậm đặc nhất.","theLucLienQuan":["Bạch gia"],"nguon":["@c2057"]},{"id":"ho-dung-nham-duoi-long-dat","name":"Hồ dung nham dưới lòng đất","cn":"","capDo":"khac","parentId":"mach-khoang-hoa-van-thach","blurb":"Hồ dung nham rộng khoảng ngàn mẫu nằm sâu dưới khoáng mạch Hỏa Vân Thạch.","detail":"Hồ nằm cuối hệ thống đường mỏ và các khe nứt tự nhiên. Quanh bờ tập trung hàng vạn khối cực phẩm Hỏa Vân Thạch, còn ma thú bị đoàn người nghi ngờ đang ẩn dưới lớp dung nham nóng bỏng.","theLucLienQuan":["Bạch gia"],"nguon":["@c2058"]},{"id":"ham-mo","name":"Hầm mỏ","cn":"","capDo":"khac","parentId":"mach-khoang-hoa-van-thach","blurb":"Khu hầm trong mạch khoáng từng phát hiện các di hài Bạch gia bị hút khô.","detail":"Tình trạng các di hài được tìm thấy tại đây giống hệt thi thể của những đệ tử Bạch gia bị ma linh hút sạch huyết nhục, giúp Hàn Lập nhận diện hung thủ.","theLucLienQuan":["Bạch gia"],"nguon":["@c2061"]},{"id":"hang-dong-chien-truong","name":"Hang động chiến trường","cn":"","capDo":"khac","parentId":"mach-khoang-trong-yeu-bach-gia","blurb":"Nơi năm người hội họp sau khi ma thú đầu hươu đào thoát.","detail":"Tại đây, nhóm bàn về nguồn gốc ma linh, thương lượng phần thù lao tăng thêm, điều tức rồi chia thành hai đội tìm kiếm.","theLucLienQuan":["Bạch gia"],"nguon":["@c2063"]},{"id":"tang-bao-kho-bach-gia","name":"Tàng bảo khố Bạch gia","cn":"","capDo":"khac","parentId":"huyen-da-thanh","blurb":"Bảo khố được Bạch gia đặt tại Huyễn Dạ Thành và bảo vệ bằng cấm chế cùng lực lượng canh gác tinh nhuệ.","detail":"Lối vào bảo khố nằm trong một lầu các có cấm chế bao phủ. Bên trong có tám tượng ác quỷ thanh đồng, mười hai giá chứa bảo vật và ít nhất mười đệ tử tinh nhuệ ẩn nấp bảo vệ.","theLucLienQuan":["Bạch gia"],"nguon":["@c2064"]},{"id":"dinh-nui-ngoai-huyen-da-thanh","name":"Đỉnh núi ngoài Huyễn Dạ Thành","cn":"","capDo":"khac","parentId":"huyen-da-thanh","blurb":"Điểm tập hợp nằm cách Huyễn Dạ Thành vài trăm dặm và được cấm chế sương mù che phủ.","detail":"Hàn Lập gặp Lũng gia lão tổ cùng trưởng lão họ Huy tại đây. Sau đó Diệp tiên tử cũng tới và được mở cấm chế cho hạ xuống.","theLucLienQuan":["Lũng gia","Diệp gia"],"nguon":["@c2066"]},{"id":"trieu-gia-cam-dia","name":"Triệu gia cấm địa","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một trong hai địa điểm Triệu gia dùng để nuôi Bát Túc Ma Tích.","detail":"Nơi này có cấm chế phòng hộ mạnh, khiến việc tập kích vẫn rất khó khăn ngay cả khi hai Ma Tôn Triệu gia không còn tọa trấn. Vì vậy, đoàn Lũng gia lão tổ không chọn đây làm mục tiêu ra tay.","theLucLienQuan":["Triệu gia"],"nguon":["@c2068"]},{"id":"noi-bat-tuc-ma-tich-tam-tru","name":"Nơi Bát Túc Ma Tích tạm trú","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Điểm nghỉ chân định kỳ của đàn Bát Túc Ma Tích hoạt động bên ngoài.","detail":"Mỗi nửa tháng, một đàn Bát Túc Ma Tích của Triệu gia trở về đây và lưu lại vài ngày. Lũng gia lão tổ chọn khoảng thời gian này làm cơ hội để đoàn lẻn vào đoạt đủ số ma tích cần thiết.","theLucLienQuan":["Triệu gia"],"nguon":["@c2068"]},{"id":"linh-gioi","name":"Linh Giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện quê nhà mà Lâm gia lão tổ dự định trở về sau khi rút khỏi hành trình.","detail":"Lâm gia lão tổ dự định kích phát chân nguyên còn lại để trở về Linh Giới và bế quan vài trăm năm. Ông cũng nhận lời đưa tiểu nha đầu Nhân tộc được Hàn Lập gửi gắm về đây và chăm sóc nàng.","theLucLienQuan":["Nhân tộc","Linh tộc","Lâm gia"],"nguon":["@c2068"]},{"id":"rung-ram-am-u","name":"Rừng rậm âm u","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu rừng nơi Lâm đạo hữu tỉnh lại sau khi bị bắt.","detail":"Lâm đạo hữu bị dây hoa trói và phong tỏa pháp lực tại đây. Hắc giáp đại hán canh giữ ông, còn một bạch y nữ tử xuất hiện dưới tán cây gần đó.","theLucLienQuan":["Ma tộc"],"nguon":["@c2069"]},{"id":"thiet-sa-linh","name":"Thiết Sa lĩnh","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Lãnh địa của Thanh Dực tộc tại Ma Giới.","detail":"Thiết Sa lĩnh là nơi cư trú của Thanh Dực tộc và cũng là địa điểm Diệp tiên tử xác định có người mang Thanh Loan chân huyết. Nơi đây trở thành mục tiêu riêng trong hành trình của nàng và Hàn Lập.","theLucLienQuan":["Thanh Dực tộc"],"nguon":["@c2072","@c2076","@c2080"]},{"id":"tho-long-tran","name":"Thổ Long Trấn","cn":"","aliases":[],"capDo":"thanh","parentId":"ma-gioi","blurb":"Trấn Ma tộc nằm gần rìa vùng cao nguyên và sơn mạch, đồng thời là điểm dừng chân duy nhất quanh vùng.","detail":"Thổ Long Trấn rộng khoảng mười dặm, có quảng trường, tửu lâu, cửa hàng, các đài cao cắm cờ đen và vệ sĩ canh giữ. Lạc huynh cùng Lãnh huynh chọn nơi này để phục kích nhóm mục tiêu vừa rời Huyễn Khiếu Sa Mạc.","theLucLienQuan":["Ma tộc"],"nguon":["@c2073"]},{"id":"tran-nho-tai-ma-gioi","name":"Trấn nhỏ tại Ma giới","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Một trấn nhỏ nơi Hàn Lập và Diệp tiên tử dừng lại mua Thanh Ma Tinh. Hai trưởng lão Thú Tôn Điện bí mật theo dõi họ tại đây.","detail":"Trong trấn có quảng trường, một con đường với vài cửa hàng và tửu lâu được bố trí cấm chế. Hàn Lập cùng Diệp tiên tử mua đủ Thanh Ma Tinh để vận hành phi chu rồi lập tức rời đi.","theLucLienQuan":["Thú Tôn Điện"],"nguon":["@c2074"]},{"id":"ngon-nui-ngoai-tran","name":"Ngọn núi ngoài trấn","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Ngọn núi nằm cách trấn nhỏ hàng trăm vạn dặm. Đây là nơi hai trưởng lão Thú Tôn Điện chặn phi chu của Hàn Lập và Diệp tiên tử.","detail":"Đạo sĩ họ Lãnh và đại hán họ Lạc chọn khu vực ngọn núi này để công khai ngăn đường sau khi dùng Truy Ảnh Trùng bám theo mục tiêu. Hàn Lập triển khai pháp tướng Phạm Thánh Chân Ma Công tại đây để chuẩn bị một mình giao chiến với cả hai.","theLucLienQuan":["Thú Tôn Điện"],"nguon":["@c2074"]},{"id":"ho-nuoc-xanh-den","name":"Hồ nước xanh đen","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một hồ nước xanh đen tại Ma giới, nơi nhóm Lũng gia lão tổ bị người của Thú Tôn Điện theo dõi.","detail":"Lũng gia lão tổ và nam tử họ Huy đứng tại đây nhìn hai người của Thú Tôn Điện rời đi, sau đó quyết định toàn lực tiến về Ma Nguyên Hải.","theLucLienQuan":["Thú Tôn Điện"],"nguon":["@c2076"]},{"id":"thanh-tri-ma-toc-bac-trung","name":"Thành trì Ma tộc bậc trung","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Một thành trì Ma tộc bậc trung trên đường tới Thiết Sa Lĩnh.","detail":"Hàn Lập và Diệp tiên tử bay nửa tháng mới tới nơi, sau đó chia nhau thu thập tình báo về chiến sự Linh giới. Hai ngày sau, họ rời thành và tiếp tục hành trình.","theLucLienQuan":["Ma tộc"],"nguon":["@c2076"]},{"id":"huan-huong-trai","name":"Huân Hương trại","cn":"","capDo":"khac","parentId":"thiet-sa-linh","blurb":"Một trong bốn nơi cư trú lớn nhất của Thanh Dực tộc tại Thiết Sa lĩnh.","detail":"Sơn trại nằm trên một sơn phong giữa bồn địa được ba ngọn núi bao quanh. Sương trắng có mùi thơm cùng cấm chế lợi hại che phủ toàn bộ nơi này, khiến việc đột nhập trực tiếp rất khó khăn.","theLucLienQuan":["Thanh Dực tộc"],"nguon":["@c2077"]},{"id":"khu-tu-luyen-hach-tam-de-tu-thanh-duc-toc","name":"Khu tu luyện hạch tâm đệ tử Thanh Dực tộc","cn":"","capDo":"khac","parentId":"huan-huong-trai","blurb":"Một tòa nhà trong Huân Hương trại được xác định là nơi tập trung nhiều hạch tâm đệ tử Thanh Dực tộc.","detail":"Thiết bài của Diệp tiên tử phản ứng mạnh tại đây. Nơi này được dự đoán có cấm chế mạnh và một hoặc nhiều Ma tôn phụ trách trấn giữ.","theLucLienQuan":["Thanh Dực tộc"],"nguon":["@c2078"]},{"id":"dai-dien-trung-tam-huan-huong-trai","name":"Đại điện trung tâm Huân Hương trại","cn":"","capDo":"khac","parentId":"huan-huong-trai","blurb":"Tòa đại điện có Ma tôn tóc đen mắt xanh tu luyện và một tế đàn dùng để cảnh báo khi cấm chế bị tác động.","detail":"Hàn Lập chủ động xâm nhập nơi này để thu hút và cầm chân Ma tôn trấn thủ khi Diệp tiên tử triển khai kế hoạch bắt sống hạch tâm đệ tử ở khu vực khác.","theLucLienQuan":["Thanh Dực tộc"],"nguon":["@c2078"]},{"id":"tang-linh-cac","name":"Tàng Linh Các","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm có lực lượng mà hai ma nhân định tìm đến cầu viện.","detail":"Sau khi nhận ra thần thông của Hàn Lập sâu không lường được, Thanh trưởng lão và ma nhân Thanh Dực tộc dự định cử một người tới Tàng Linh Các xin viện trợ.","theLucLienQuan":["Ma tộc","Thanh Dực tộc"],"nguon":["@c2079"]},{"id":"thanh-linh-dien","name":"Thanh Linh Điện","cn":"","capDo":"khac","parentId":"huan-huong-trai","blurb":"Khu điện trong Huân Hương Trại dành cho các đệ tử hạch tâm Thanh Dực tộc mang chân huyết.","detail":"Khi Thanh trưởng lão trở lại, đại môn của Thanh Linh Điện đã bị phá, cấm chế bị bài trừ và các thủ vệ áo xanh biếc đều ngã xuống. Một đệ tử hạch tâm mang Thanh Loan chân huyết tại đây đã bị Hàn Lập và Diệp tiên tử cướp đi.","theLucLienQuan":["Thanh Dực tộc"],"nguon":["@c2080"]},{"id":"ma-vien-san-ho","name":"Ma Viên San Hô","cn":"","aliases":["Tòa núi hình cự viên"],"capDo":"khac","parentId":"ma-nguyen-hai","blurb":"Một địa hình đá ngầm đặc thù trên Ma Nguyên Hải, có hình dáng như cự viên ngửa cổ giang tay. Đây là manh mối quan trọng để đoàn Hàn Lập tìm vị trí Tẩy Linh Trì.","detail":"Hàn Lập phát hiện Ma Viên San Hô cách cự thuyền hơn ba ngàn dặm và được Thiên Thu thánh nữ xác nhận là phù hợp với miêu tả. Khi đến gần, mọi người thấy một tòa núi đơn độc giữa biển, nửa trên chìm trong mây đen, có mắt, mũi, tai và miệng rõ ràng như một con cự viên khổng lồ.","theLucLienQuan":[],"nguon":["@c2081"]},{"id":"dao-nho-muc-tieu","name":"Đảo nhỏ mục tiêu","cn":"","capDo":"khac","parentId":"loi-hai","blurb":"Hòn đảo được nhắc đến trong di huấn của một tiền bối Đại Thừa thuộc Linh tộc.","detail":"Đảo nằm bên trong Lôi Hải và bị lôi điện bao kín bốn phương tám hướng. Từ bên ngoài, đoàn thám hiểm chỉ có thể thấy một bóng đen lớn thông qua linh mục thần thông của Hàn Lập và Bạch Thích.","theLucLienQuan":["Linh tộc"],"nguon":["@c2082"]},{"id":"kho-linh-dao","name":"Khổ Linh Đảo","cn":"","capDo":"gioi-nho","parentId":"ma-nguyen-hai","blurb":"Khu vực được lôi hải và các đảo nhỏ bao quanh, do Tam Đại Thủy Tổ canh giữ.","detail":"Đoàn Hàn Lập xông vào Khổ Linh Đảo bằng cự thuyền sau khi kích phát nhiều tầng phòng thủ. Việc xâm nhập lập tức phát tín hiệu tới các Thủy Tổ Ma giới đang ở những khu vực lân cận.","theLucLienQuan":["Tam Đại Thủy Tổ","Ma tộc"],"nguon":["@c2084","@c2093"]},{"id":"dao-nho-trong-loi-hai","name":"Đảo nhỏ trong lôi hải","cn":"","capDo":"khac","parentId":"kho-linh-dao","blurb":"Một đảo nhỏ nằm giữa lôi hải, nơi nữ tử Thủy Tổ xuất hiện bên hồ nước xanh biếc.","detail":"Nữ tử Thủy Tổ ngồi xếp bằng cạnh hồ nước trên đảo và biết đoàn người đang tiến tới. Nàng biến mất ngay sau đó, để lại hắc giáp đại hán phía sau.","theLucLienQuan":["Tam Đại Thủy Tổ","Ma tộc"],"nguon":["@c2084"]},{"id":"dao-nho-bao-phu-hac-khi","name":"Đảo nhỏ bao phủ hắc khí","cn":"","capDo":"khac","parentId":"ma-nguyen-hai","blurb":"Một đảo nhỏ ở rất xa Ma Nguyên Hải, có đỉnh núi cao vút và dược viên của hắc bào thanh niên Thủy Tổ.","detail":"Hắc bào thanh niên nghiên cứu linh dược trong dược viên trên đảo. Sau khi thí nghiệm thất bại và nhận tín hiệu Khổ Linh Đảo bị xâm nhập, hắn triệu tam thủ hắc giao rồi rời đi về phía lôi hải.","theLucLienQuan":["Tam Đại Thủy Tổ","Ma tộc"],"nguon":["@c2084"]},{"id":"cung-dien-duoi-long-dat","name":"Cung điện dưới lòng đất","cn":"","capDo":"khac","parentId":"son-mach-lien-mien","blurb":"Cung điện ngầm trong một sơn mạch liên miên, nơi trung niên kim bào nằm trong quan tài trong suốt.","detail":"Bên cạnh quan tài có ký hiệu vàng phát sáng lập lòe, nhưng trung niên kim bào vẫn nhắm mắt và không phản ứng. Tình trạng sống chết của gã chưa được xác định.","theLucLienQuan":["Tam Đại Thủy Tổ","Ma tộc"],"nguon":["@c2084"]},{"id":"son-mach-lien-mien","name":"Sơn mạch liên miên","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Một vùng sơn mạch của Ma giới, bên dưới có cung điện ngầm chứa quan tài của trung niên kim bào.","detail":"Sơn mạch là nơi ẩn giấu cung điện dưới lòng đất của vị Thủy Tổ thứ ba. Một tín hiệu vàng xuất hiện tại đây khi Khổ Linh Đảo bị xâm nhập.","theLucLienQuan":["Tam Đại Thủy Tổ","Ma tộc"],"nguon":["@c2084"]},{"id":"linh-dao","name":"Linh Đảo","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Hòn đảo xanh biếc khổng lồ nằm sau Lôi hải, là mục tiêu của đoàn thám hiểm.","detail":"Linh Đảo hiện ra cách cự thuyền hơn mười dặm sau khi đoàn người vượt khỏi vùng biển sấm chớp. Hòn đảo phát tán linh khí cực kỳ tinh thuần, được Lũng gia lão tổ xác nhận là nơi họ tìm kiếm và có khả năng tồn tại Tẩy Linh Trì cùng Tinh Linh Liên.","theLucLienQuan":["Lũng gia","Linh tộc"],"nguon":["@c2085"]},{"id":"tay-linh-tri-dia-diem","name":"Tẩy Linh Trì","cn":"","capDo":"khac","parentId":"linh-dao","blurb":"Địa điểm mục tiêu được cho là nằm trên Linh Đảo.","detail":"Lũng gia lão tổ nhận định vùng đất có linh khí tinh thuần như Linh Đảo mới có thể tồn tại Tẩy Linh Trì. Đến cuối chương, đoàn người mới nhìn thấy hòn đảo và chưa trực tiếp tìm được hồ.","theLucLienQuan":["Lũng gia","Linh tộc"],"nguon":["@c2085"]},{"id":"son-coc-linh-tieu-thien-hu","name":"Sơn cốc Linh Tiêu Thiên Hủ","cn":"","capDo":"khac","parentId":"cu-dao","blurb":"Sơn cốc bí mật nằm giữa hai cự phong xanh biếc trên cự đảo, vốn bị cảnh tượng hư không che giấu.","detail":"Sơn cốc xuất hiện sau khi Lũng gia lão tổ phá hủy ngọn núi che chắn và làm không gian dao động. Bên ngoài sơn cốc phủ một lớp lục quang không ngăn cản đoàn người tiến vào; bên trong có Linh Tiêu Thiên Hủ, khu vực linh khí tinh hóa và hồ nước xanh biếc nghi là Tẩy Linh Trì.","theLucLienQuan":["Linh Tộc","Nhân tộc"],"nguon":["@c2086"]},{"id":"linh-tieu-thien-hu","name":"Linh Tiêu Thiên Hủ","cn":"","capDo":"khac","parentId":"son-coc-linh-tieu-thien-hu","blurb":"Cột sáng trắng noãn dựng trong sơn cốc, vừa thô vừa cao và xuyên sâu lên tầng mây.","detail":"Lũng gia lão tổ nhận ra cột sáng này sau khi sơn cốc bí mật hiện ra và dựa vào dấu hiệu đó để nhận định nơi ẩn giấu Tẩy Linh Trì đã được tìm thấy.","theLucLienQuan":[],"nguon":["@c2086"]},{"id":"khu-vuc-linh-khi-tinh-hoa","name":"Khu vực linh khí tinh hóa","cn":"","capDo":"khac","parentId":"son-coc-linh-tieu-thien-hu","blurb":"Khu vực trong sơn cốc tràn ngập ngũ sắc quang điểm do thiên địa linh khí tinh hóa.","detail":"Linh khí tại đây tinh thuần hơn bên ngoài gấp mười lần và có thể trực tiếp ngưng kết thành ngũ sắc tinh thạch. Mật độ quang điểm tăng cao rõ rệt ở phía trên hồ nước xanh biếc.","theLucLienQuan":[],"nguon":["@c2086"]},{"id":"ho-nuoc-xanh-biec","name":"Hồ nước xanh biếc","cn":"","capDo":"khac","parentId":"son-coc-linh-tieu-thien-hu","blurb":"Hồ nước nằm giữa sơn cốc, phía trên tập trung dày đặc ngũ sắc linh khí quang điểm.","detail":"Lũng gia lão tổ và Huy trưởng lão tới bên hồ trước, còn Hàn Lập sau khi đáp xuống gần đó đã nghi ngờ đây chính là Tẩy Linh Trì. Chương này chưa đưa ra xác nhận trực tiếp về thân phận của hồ.","theLucLienQuan":[],"nguon":["@c2086"]},{"id":"mat-ho-giao-chien","name":"Mặt hồ giao chiến","cn":"","capDo":"khac","parentId":"thanh-gioi","blurb":"Mặt hồ nơi nhóm Lũng gia lão tổ đối đầu với hắc bào thanh niên.","detail":"Cự đại ma thủ bao phủ hơn phân nửa khu vực này, trói buộc Lũng gia lão tổ và Diệp tiên tử trong cuộc giao chiến.","theLucLienQuan":["Ma tộc","Lũng gia"],"nguon":["@c2089"]},{"id":"thanh-dia-cua-thanh-gioi","name":"Thánh địa của Thánh giới","cn":"","capDo":"khac","parentId":"thanh-gioi","blurb":"Khu vực trọng yếu của Thánh giới mà nhóm tu sĩ đã xâm nhập.","detail":"Hắc bào thanh niên trấn giữ nơi này và chất vấn nhóm tu sĩ vì dám xâm nhập thánh địa.","theLucLienQuan":["Ma tộc"],"nguon":["@c2089"]},{"id":"khon-linh-coc","name":"Khốn Linh Cốc","cn":"","capDo":"khac","parentId":"kho-linh-dao","blurb":"Sơn cốc bị phong tỏa trên Khổ Linh Đảo, nơi nhóm Hàn Lập đối đầu Ma tộc Thánh Tổ.","detail":"Khốn Linh Cốc được bao phủ bởi màn sáng xanh. Cấm chế từng cho phép nhóm tu sĩ tiến vào nhưng hiện đánh bật độn quang và ngăn mọi bí thuật không gian thoát ra, biến sơn cốc thành nơi giam giữ những người Linh giới.","theLucLienQuan":["Ma tộc","Nhân tộc"],"nguon":["@c2090"]},{"id":"son-coc-hon-dao","name":"Sơn cốc trên hòn đảo","cn":"","capDo":"khac","parentId":"dao-nho-trong-loi-hai","blurb":"Sơn cốc chịu sự tàn phá trực tiếp từ vụ tự bạo của Ngụy Tiên Khôi Lỗi.","detail":"Vụ nổ bào mất một tầng đất đá dày trên bề mặt sơn cốc và làm hồ nước biến mất hoàn toàn. Đáy hồ lộ ra một phiến đá lớn có bề mặt bị cắt bằng, trên đó khắc trận pháp mơ hồ chiếm khoảng nửa diện tích hồ; không trung còn chằng chịt khe không gian trước khi chúng dần tan đi.","theLucLienQuan":[],"nguon":["@c2094"]},{"id":"thuy-an-chi-dia","name":"Thủy Ấn chi địa","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Nơi sinh vật bí ẩn cùng tử tôn của nó bị người từ Chân Tiên Giới phong ấn từ thời thượng cổ.","detail":"Phong ấn tại đây đã suy yếu rõ rệt. Sinh vật bị giam từng thức tỉnh lần thứ hai khoảng sáu ngàn năm trước, còn những sinh vật tràn ra gần đây đã mạnh lên và gây thương vong lớn cho lực lượng trấn giữ.","theLucLienQuan":["Ma tộc","Thú Tôn điện","Chân Tiên Giới"],"nguon":["@c2101"]},{"id":"khong-gian-tay-linh-tri","name":"Không gian Tẩy Linh Trì","cn":"","capDo":"gioi-nho","parentId":"linh-tieu-thien-hu","blurb":"Không gian bí cảnh rộng khoảng trăm dặm, nơi Hàn Lập tìm thấy hồ nước bạc nghi là Tẩy Linh Trì.","detail":"Không gian có đại thụ cao hàng trăm trượng, hoa cỏ phát ra ánh sáng năm màu và nhiều quang cầu ngũ sắc trôi nổi trong hư không.","theLucLienQuan":[],"nguon":["@c2101"]},{"id":"day-tay-linh-tri","name":"Đáy Tẩy Linh Trì","cn":"","capDo":"khac","parentId":"tay-linh-tri-dia-diem","blurb":"Đáy hồ phủ cát trắng, nằm ở độ sâu hơn mười trượng trong Tẩy Linh Trì.","detail":"Hai góc hẻo lánh dưới đáy hồ mọc tổng cộng bảy gốc Tịnh Linh Liên. Nơi này không có linh dược nào khác, trong khi áp lực nước và linh lực tinh thuần khiến khôi lỗi thông thường khó tiếp cận.","theLucLienQuan":[],"nguon":["@c2102"]},{"id":"khong-gian-chua-tay-linh-tri","name":"Không gian chứa Tẩy Linh Trì","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian rộng hơn trăm dặm với linh khí cực kỳ nồng đậm, là nơi tọa lạc của Tẩy Linh Trì.","detail":"Nơi này vốn có nhiều linh thảo, linh mộc lâu năm và một số mỏ linh quáng nhỏ. Hàng vạn Phệ Kim Trùng đã ăn sạch các tài nguyên ấy, khiến toàn bộ không gian biến thành vùng đất hoang trơ trụi.","theLucLienQuan":[],"nguon":["@c2104"]},{"id":"vach-da-ven-tay-linh-tri","name":"Vách đá ven Tẩy Linh Trì","cn":"","capDo":"khac","parentId":"khong-gian-chua-tay-linh-tri","blurb":"Vách đá cạnh Tẩy Linh Trì mang những hình vẽ tự nhiên giống ký hiệu hoặc thượng cổ văn tự.","detail":"Hàn Lập quan sát những hình vẽ trên vách đá trước lúc rời đi, nhưng không có đủ thời gian để tham ngộ huyền cơ ẩn chứa trong đó.","theLucLienQuan":[],"nguon":["@c2104"]},{"id":"dai-cao-truyen-tong","name":"Đài cao truyền tống","cn":"","capDo":"khac","parentId":"khong-gian-tay-linh-tri","blurb":"Một tế đàn nằm ở góc không gian Tẩy Linh Trì, trên mặt khắc trận pháp truyền tống.","detail":"Hàn Lập đi tới đài cao và kích hoạt trận pháp trên đó để rời khỏi không gian trước khi lực lượng thiên địa áp chế hoàn toàn.","theLucLienQuan":[],"nguon":["@c2105"]},{"id":"phi-thuy-ma-thanh","name":"Phỉ Thúy Ma Thành","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Một đại thành thị tại Ma giới có truyền tống trận.","detail":"Bốn Ma Tôn chặn nhóm Hàn Lập gần truyền tống trận nhưng bị Giải Đạo Nhân giết bằng một kích, giúp cả nhóm công khai rời thành.","theLucLienQuan":["Ma tộc"],"nguon":["@c2112"]},{"id":"thuoc-kim-ha-coc","name":"Thước Kim Hà Cốc","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một hiểm địa nổi danh tại Ma giới.","detail":"Hóa thân Thiên Nha Thánh Tổ cùng ba Ma Tôn chặn bắt Hàn Lập tại đây. Hóa thân và hai Ma Tôn bị giết, chỉ một Ma Tôn tinh thông độn thuật trốn thoát.","theLucLienQuan":["Ma tộc"],"nguon":["@c2112"]},{"id":"tram-thuy-tran","name":"Trầm Thủy Trấn","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Tiểu trấn tại Ma giới, nơi diễn ra trận chiến giữa nhóm Hàn Lập và Huyết Quang.","detail":"Hàn Lập cùng Giải Đạo Nhân giao chiến với bản thể Huyết Quang, hai hóa thân và thuộc hạ suốt một ngày một đêm. Trận chiến khiến trấn gần như bị hủy diệt hoàn toàn.","theLucLienQuan":["Ma tộc"],"nguon":["@c2112"]},{"id":"day-hoang-son-gan-tram-thuy-tran","name":"Dãy hoang sơn gần Trầm Thủy Trấn","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu hoang sơn cách Trầm Thủy Trấn khoảng trăm vạn dặm.","detail":"Thi thể không trọn vẹn của Huyết Quang được phát hiện tại đây, với đỉnh đầu bị xé mở và nguyên anh đã biến mất.","theLucLienQuan":[],"nguon":["@c2112"]},{"id":"dong-phu-trong-tieu-son-hoang-vang","name":"Động phủ trong tiểu sơn hoang vắng","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Nơi ẩn náu của Xa Kỵ Cung và Phong Tà tại Ma giới.","detail":"Xa Kỵ Cung và Phong Tà giam nguyên anh Huyết Quang trong Luyện Hồn Đỉnh tại động phủ này để tra khảo vị trí kho báu bí mật.","theLucLienQuan":[],"nguon":["@c2112"]},{"id":"dong-phu-bi-mat-cua-huyet-quang","name":"Động phủ bí mật của Huyết Quang","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Động phủ bí mật cất giữ tài sản của Huyết Quang.","detail":"Bảo vật tại đây có thể giúp Xa Kỵ Cung và Phong Tà khôi phục thần thông nhanh hơn, nhưng Huyết Quang không chịu tiết lộ vị trí.","theLucLienQuan":[],"nguon":["@c2112"]},{"id":"sa-mac-vo-tan","name":"Sa mạc vô tận","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Vùng sa mạc rộng lớn không thấy bờ tại Ma giới.","detail":"Bảo Hoa và Hắc Ngạc bị hơn trăm Ma tộc song giác thân đỏ vây công tại đây, giữa bãi thi thể và máu.","theLucLienQuan":["Ma tộc song giác thân đỏ"],"nguon":["@c2112"]},{"id":"hoa-gioi-huyen-thien","name":"Huyền Thiên Hoa giới","cn":"","capDo":"gioi-nho","parentId":"ma-gioi","blurb":"Linh vực màu phấn hồng do Bảo Hoa tạo ra để vây khốn và luyện hóa đối thủ.","detail":"Bên trong Hoa giới có nhiều tầng hoa ảnh, năng lực na di và biển ma diễm. Người bị bao phủ không thể vay mượn thiên địa nguyên khí từ bên ngoài; đến ngày thứ bảy, Hoa giới xuất hiện bất ổn và để Thiên Khấp cùng Hạc Nhan thoát ra.","theLucLienQuan":[],"nguon":["@c2114"]},{"id":"tieu-dao-trung-chuyen-tren-lam-boc-ho","name":"Tiểu đảo trung chuyển trên Lam Bộc hồ","cn":"","capDo":"khac","parentId":"lam-boc-ho","blurb":"Tiểu đảo có các kiến trúc đơn giản và nhiều thuyền đen chuyên chở khách đi sâu vào Lam Bộc hồ.","detail":"Hàn Lập chủ động đáp xuống đảo để thuê thuyền, qua đó tránh phô bày việc mình không bị cấm chế cấm không hạn chế.","theLucLienQuan":["Ma tộc"],"nguon":["@c2115"]},{"id":"lam-boc-thanh","name":"Lam Bộc thành","cn":"","capDo":"thanh","parentId":"lam-boc-ho","blurb":"Đại thành Ma tộc xây dọc ven một đảo lớn trong Lam Bộc hồ, là nơi Hàn Lập tìm kiếm thượng phẩm Huyết Nha mễ.","detail":"Thành được xây bằng cự thạch màu lam nhạt, có tường cao hơn mười trượng, nhiều vệ sĩ vũ trang trên thành và một đội Ma tộc canh giữ đại môn. Hoạt động mua Huyết Nha mễ tại đây chịu giới hạn về tu vi, số lượng và thời gian cư trú.","theLucLienQuan":["Ma tộc"],"nguon":["@c2115"]},{"id":"cua-hang-do-lieu-chuong-quay-quan-ly","name":"Cửa hàng do Liêu chưởng quầy quản lý","cn":"","capDo":"khac","parentId":"lam-boc-thanh","blurb":"Cửa hàng tại Lam Bộc thành từng do Liêu chưởng quầy quản lý.","detail":"Đây là nơi Mộ Tịch giả làm tiểu nhị để bí mật thu thập sổ giao dịch trong vài chục năm. Sau khi hành vi tham ô của Liêu chưởng quầy bị phơi bày và lão bị xử tử, Mộ Tịch được bổ nhiệm tiếp quản.","theLucLienQuan":[],"nguon":["@c2116"]},{"id":"thien-hai-cac","name":"Thiên Hải các","cn":"","capDo":"khac","parentId":"lam-boc-thanh","blurb":"Lầu các kinh doanh lớn tại Lam Bộc thành, có bề ngoài cổ xưa nhưng không gian nội bộ rộng lớn.","detail":"Bên trong Thiên Hải các là một tiểu Tu Di không gian được mở bằng không gian ma khí, tạo thành đại sảnh rộng vài mẫu.","theLucLienQuan":["Thiên Hải các"],"nguon":["@c2116"]},{"id":"thai-hien-cac","name":"Thải Hiên Các","cn":"","capDo":"khac","parentId":"lam-boc-thanh","blurb":"Cửa hàng lớn nổi tiếng về độ đa dạng hàng hóa tại Lam Bộc thành.","detail":"Đại sảnh Thải Hiên Các được chia thành khu hàng thông thường và khu bảo vật giá trị cao có quang tráo xanh bao phủ. Tầng hai có phòng khách quý dùng để tiếp đãi tu sĩ cấp cao.","theLucLienQuan":["Thải Hiên Các"],"nguon":["@c2117"]},{"id":"tien-cu-lau","name":"Tiên Cư Lâu","cn":"","capDo":"khac","parentId":"lam-boc-thanh","blurb":"Địa điểm nổi tiếng trong Lam Bộc thành, được chọn làm nơi tiến hành một cuộc gặp kín liên quan đến Dị Ma Kim.","detail":"Nam tử Ma tộc râu cá trê đưa Hàn Lập tới Tiên Cư Lâu bằng thú xa. Trong một gian phòng tương đối bí ẩn tại đây, Hàn Lập gặp vài nam nữ Ma tộc xa lạ được cho là đang nắm giữ nhiều Dị Ma Kim.","theLucLienQuan":[],"nguon":["@c2117"]},{"id":"mo-quang-bi-mat-tai-lam-boc-thanh","name":"Mỏ quặng bí mật tại Lam Bộc thành","cn":"","capDo":"khac","parentId":"lam-boc-thanh","blurb":"Mỏ quặng bị nhóm Vô Ưu bí mật khai thác trái phép tại Lam Bộc thành.","detail":"Mỏ xuất hiện nhiều loại khoáng thạch quý hiếm, trong đó có hơn hai nghìn miếng Dị Ma kim cực phẩm. Thiết Hổ đã giết những người biết nội tình và phong kín toàn bộ mỏ để ngăn người sống sót thoát ra.","theLucLienQuan":["Nhóm khai mỏ của Vô Ưu"],"nguon":["@c2118"]},{"id":"cua-dong-lam-boc-thanh","name":"Cửa thành phía đông","cn":"","capDo":"khac","parentId":"lam-boc-thanh","blurb":"Cửa thành mà Hàn Lập đi qua khi rời Lam Bộc thành để tìm Quảng Nguyên Trai.","detail":"Hàn Lập đi xe thú theo hướng cửa đông, rời khỏi thành rồi tiếp tục đến khu rừng có lối vào Quảng Nguyên Trai.","theLucLienQuan":["Phủ thành chủ Lam Bộc thành","Quảng Nguyên Trai"],"nguon":["@c2119"]},{"id":"khu-rung-ngoai-lam-boc-thanh","name":"Khu rừng ngoài thành","cn":"","capDo":"khac","parentId":"lam-boc-thanh","blurb":"Khu rừng xanh bên ngoài Lam Bộc thành, nơi có lối nhỏ kín đáo dẫn đến Quảng Nguyên Trai.","detail":"Trong rừng có mộc bài đánh dấu đường đi và người của Quảng Nguyên Trai bí mật sàng lọc khách trước khi họ tới lầu các.","theLucLienQuan":["Quảng Nguyên Trai"],"nguon":["@c2119"]},{"id":"lau-cac-quang-nguyen-trai","name":"Lầu các Quảng Nguyên Trai","cn":"","capDo":"khac","parentId":"khu-rung-ngoai-lam-boc-thanh","blurb":"Tòa lầu năm tầng bằng gỗ trắng cổ xưa, là cơ sở chính của Quảng Nguyên Trai ngoài Lam Bộc thành.","detail":"Tầng một bố trí Tứ Tượng Trận và một sát trận bí mật. Tầng hai trồng nhiều hoa cùng linh thảo và là nơi Chu Di xuất hiện, còn tiểu thư Quảng Nguyên Trai chờ Hàn Lập tại tầng ba.","theLucLienQuan":["Quảng Nguyên Trai"],"nguon":["@c2119"]},{"id":"toa-lau-quang-nguyen-trai","name":"Tòa lầu Quảng Nguyên Trai","cn":"","capDo":"khac","parentId":"lam-boc-thanh","blurb":"Trụ sở giao dịch tình báo của Quảng Nguyên Trai tại Lam Bộc thành. Các tầng trên được bố trí riêng cho việc tiếp khách thường và khách quan trọng.","detail":"Tầng ba là phòng tiếp khách hoa lệ với bàn thờ bạch ngọc, bản đồ bát quái và lư hương, nơi thiếu nữ áo vàng làm người thế thân. Tầng bốn mô phỏng một căn nhà nông dân thế tục và là nơi Lam Dĩnh trực tiếp tiếp khách quan trọng.","theLucLienQuan":["Quảng Nguyên Trai"],"nguon":["@c2120"]},{"id":"phu-thanh-chu","name":"Phủ thành chủ","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi có một người địa vị không thấp đang bí mật bán ra lượng lớn Huyết Nha Mễ.","detail":"Hàn Lập mua từ Quảng Nguyên Trai phương thức liên lạc với người bán Huyết Nha Mễ trong phủ thành chủ. Chương này chưa nêu danh tính người bán hoặc thành trì cụ thể.","theLucLienQuan":["Phủ thành chủ Lam Bộc thành"],"nguon":["@c2121"]},{"id":"lau-bon-quang-nguyen-trai","name":"Lầu bốn Quảng Nguyên Trai","cn":"","capDo":"khac","parentId":"toa-lau-quang-nguyen-trai","blurb":"Tầng lầu nơi Hàn Lập giao dịch với Lam Dĩnh và bất ngờ gặp lại Tử Linh.","detail":"Tại đây Hàn Lập mua đầu mối về Huyết Nha Mễ, đưa đoàn lục khí ra để Lam Dĩnh giám định và khôi phục chân diện khi nhận ra Tử Linh.","theLucLienQuan":["Quảng Nguyên Trai"],"nguon":["@c2121"]},{"id":"tang-nam-quang-nguyen-trai","name":"Tầng năm Quảng Nguyên Trai","cn":"","capDo":"khac","parentId":"lau-cac-quang-nguyen-trai","blurb":"Tầng lầu nơi Lam Dĩnh và Chu Di lui xuống để dành không gian riêng cho Hàn Lập cùng Tử Linh.","detail":"Sau khi giao lệnh bài cấm chế cho Tử Linh, Lam Dĩnh cùng Chu Di xuống tầng năm. Tại đây, hai người đánh giá thực lực của Hàn Lập và bàn cách lôi kéo hắn.","theLucLienQuan":["Quảng Nguyên Trai"],"nguon":["@c2122"]},{"id":"cac-hiem-dia-bi-canh-ma-gioi","name":"Các hiểm địa bí cảnh Ma giới","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Những khu vực nguy hiểm và bí cảnh tại Ma giới được hình thành từ trận đại chiến thời thượng cổ.","detail":"Các hiểm địa và bí cảnh này là di tích do cuộc giao chiến giữa Minh Trùng Mẫu với hai vị Chân Tiên tạo ra, khi trời đất Ma giới bị tàn phá nghiêm trọng.","theLucLienQuan":["Ma tộc"],"nguon":["@c2125"]},{"id":"su-nhai-thanh","name":"Sư Nhai Thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Điểm hội họp do Vô Ưu ấn định cho nhóm thuộc hạ sau khi họ chia nhỏ rời Lam Bộc Thành.","detail":"Vô Ưu yêu cầu đồng bọn chạy theo lộ trình đã định và chỉ gặp lại tại Sư Nhai Thành sau khi tình hình trở nên an toàn.","theLucLienQuan":["Nhóm khai mỏ của Vô Ưu"],"nguon":["@c2126"]},{"id":"mo-quang-bi-khai-thac-trom","name":"Mỏ quặng bị khai thác trộm","cn":"","capDo":"khac","parentId":null,"blurb":"Mỏ quặng bí mật cung cấp Dị Ma Kim cho nhóm Vô Ưu, chưa rõ vị trí cụ thể.","detail":"Nhóm Vô Ưu khai thác trái phép mỏ quặng này và bán Dị Ma Kim thu được. Hàn Lập tìm cách truy bắt cả nhóm để lấy vị trí cùng thông tin liên quan đến các khối Dị Ma Kim biến dị.","theLucLienQuan":["Nhóm khai mỏ của Vô Ưu"],"nguon":["@c2126"]},{"id":"khoang-mach-kem-chat-luong","name":"Khoáng mạch kém chất lượng","cn":"","capDo":"khac","parentId":"lam-boc-ho","blurb":"Khoáng mạch bị nhóm Vô Ưu bí mật khai thác trong thời gian dài tại khu vực Lam Bộc hồ.","detail":"Bề ngoài đây là khoáng mạch có phẩm chất thấp, nhưng đôi vợ chồng phụ trách khai thác đã phát hiện Dị Ma Kim ở nơi sâu và xa xôi nhất. Vị trí quặng rất khó tìm nếu không tiến hành dò xét cẩn thận.","theLucLienQuan":["Nhóm khai mỏ của Vô Ưu"],"nguon":["@c2127"]},{"id":"hon-dao-co-mo-quang","name":"Hòn đảo có mỏ quặng","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo nơi Hàn Lập tìm đến một mỏ quặng nằm cách xa chỗ ở của hắn.","detail":"Mỏ quặng trên đảo nằm ở vị trí xa đến mức Hàn Lập phải bay bằng độn quang suốt ba ngày mới tới khu vực ngọn núi chứa mỏ.","theLucLienQuan":[],"nguon":["@c2128"]},{"id":"son-mach-xanh-sam","name":"Sơn mạch xanh sẫm","cn":"","capDo":"vuc","parentId":"hon-dao-co-mo-quang","blurb":"Dãy núi liên miên màu xanh sẫm nằm trên đường Hàn Lập bay tới mỏ quặng.","detail":"Sau khi cảnh mặt hồ phía dưới biến mất, một dãy núi xanh sẫm liên miên xuất hiện trên tuyến đường dẫn Hàn Lập đến ngọn núi chứa mỏ.","theLucLienQuan":[],"nguon":["@c2128"]},{"id":"ngon-nui-hinh-cu-kiem","name":"Ngọn núi hình cự kiếm","cn":"","capDo":"khac","parentId":"son-mach-xanh-sam","blurb":"Ngọn núi cao vạn trượng, có hình dáng thẳng đứng như một thanh cự kiếm và chứa mỏ quặng trong lòng.","detail":"Đây là đích đến của Hàn Lập sau ba ngày phi hành. Hắn dò xét bề mặt ngọn núi bằng thần niệm trước khi thi triển pháp quyết tiến vào hệ thống đường hầm nằm sâu bên dưới.","theLucLienQuan":[],"nguon":["@c2128"]},{"id":"mo-quang-bo-hoang-trong-long-nui","name":"Mỏ quặng bỏ hoang trong lòng núi","cn":"","capDo":"khac","parentId":"ngon-nui-hinh-cu-kiem","blurb":"Hệ thống đường hầm sâu trong ngọn núi hình cự kiếm, có nhiều nhánh rẽ ngoằn ngoèo như mạng nhện.","detail":"Các đường hầm dài, hẹp và phân nhánh phức tạp, trong đó có nhiều lá phù màu đen được bố trí để chỉ đường. Càng xuống sâu, dấu vết khai thác và các nhánh rẽ càng thưa, nhưng khoáng thạch vụn còn lại cho thấy chủng loại và phẩm chất tại đây cao hơn nhiều so với khu vực bên ngoài.","theLucLienQuan":[],"nguon":["@c2128"]},{"id":"duong-ham-bi-pha-sap","name":"Đường hầm bị phá sập","cn":"","capDo":"khac","parentId":"mo-di-ma-kim-bi-mat","blurb":"Đoạn đường hầm bị người khác chủ động phá sụp và dùng đất đá lấp kín.","detail":"Đất đá chắn kín đường đi khiến Hàn Lập phải vận dụng độn thuật xuyên qua. Phía sau chướng ngại là khu đường hầm từng được dùng để khai thác Dị Ma Kim.","theLucLienQuan":[],"nguon":["@c2129"]},{"id":"mo-di-ma-kim-bi-mat","name":"Mỏ Dị Ma Kim bí mật","cn":"","capDo":"khac","parentId":"mo-quang-bo-hoang-trong-long-nui","blurb":"Khu mỏ bí mật có vỉa Dị Ma Kim kéo dài cùng hệ thống đường hầm nhỏ, hẹp và thô ráp.","detail":"Trong mỏ còn cặn Dị Ma Kim màu trắng đen và một cấm chế nằm sâu phía trước có thể ngăn thần niệm dò xét. Hơn một trăm quặng nô từng khai thác nơi này suốt hai tháng, trong đó vài người đột ngột hóa thành tro bụi. Sau hoạt động khai thác, những kẻ đứng sau đã tiến hành diệt khẩu và phá sập đường hầm.","theLucLienQuan":[],"nguon":["@c2129"]},{"id":"dong-quat-khai-thac-tam-thoi","name":"Động quật khai thác tạm thời","cn":"","capDo":"khac","parentId":"mo-di-ma-kim-bi-mat","blurb":"Động quật nhỏ nằm trong mỏ Dị Ma Kim, nơi ba quặng nô Ma tộc có sừng ẩn náu.","detail":"Hàn Lập tìm thấy ba người khai thác còn sống trong động quật này sau khi thần niệm của hắn bị cấm chế phía trước ngăn lại. Tại đây, hắn thẩm vấn họ về Dị Ma Kim và những cái chết hóa tro từng xảy ra trong mỏ.","theLucLienQuan":[],"nguon":["@c2129"]},{"id":"chien-truong-tu-quang-thu","name":"Chiến trường Từ Quang Thú","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu vực tại Ma giới nơi Hàn Lập giao chiến và tiêu diệt Từ Quang Thú.","detail":"Đại chiến phá hủy phạm vi khoảng trăm dặm, khiến mặt đất đầy hố và đá, còn những ngọn núi nhỏ xung quanh bị đánh xiêu vẹo, bạt ngang hoặc xẻ dọc. Sau khi Hàn Lập rời đi, Lam Bộc thánh tổ và hóa thân Lục Cực lần lượt tới khu vực này.","theLucLienQuan":["Ma tộc"],"nguon":["@c2131"]},{"id":"thong-dao-bi-mat-ma-gioi-linh-gioi","name":"Thông đạo bí mật Ma giới–Linh giới","cn":"","capDo":"khac","parentId":null,"blurb":"Thông đạo nối một địa phương hẻo lánh của Ma giới với địa bàn Mộc tộc tại Linh giới. Đây là lộ trình Hàn Lập chọn để trở về Linh giới.","detail":"Thông đạo từng được nhóm Lũng gia lão tổ kiểm tra kỹ trước khi toàn bộ nhóm ngã xuống. Cửa ra không nằm trong khu vực Nhân–Yêu mà thuộc địa bàn Mộc tộc, nhưng điểm đến đã được xác định nên an toàn hơn việc sử dụng một thông đạo không rõ phương hướng.","theLucLienQuan":["Mộc tộc"],"nguon":["@c2134"]},{"id":"trung-tam-luc-tuyet-thanh-loi-tran","name":"Trung tâm Lục Tuyệt Thanh Lôi Trận","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực có uy lực mạnh nhất trong Lục Tuyệt Thanh Lôi Trận nhưng đồng thời cũng là nơi có thể tìm đường thoát. Bảo Hoa đang bị một thiếu nữ chưa rõ danh tính vây ép tại vùng phía trước.","detail":"Càng đến gần trung tâm, thanh lôi càng dày đặc và xuất hiện nhiều lôi cầu xanh chưa phát động. Từ vùng sương mù loãng tại đây truyền ra lời của một thiếu nữ đang ép Bảo Hoa chịu trói.","theLucLienQuan":[],"nguon":["@c2134"]},{"id":"ma-nguyen-thanh-hai","name":"Ma Nguyên Thánh Hải","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Khu vực gắn với danh tiếng Hoàng Kim Thánh Giải của Giải Đạo Nhân.","detail":"Giải Đạo Nhân từng mang danh Hoàng Kim Thánh Giải tại đây và đã gặp nhiều Thánh Tổ thành danh. Xuất thân này khiến Lam Bộc nhận ra y và sinh lòng kiêng kị.","theLucLienQuan":["Ma tộc"],"nguon":["@c2135"]},{"id":"the-gioi-loi-dien-luc-tuyet-thanh-loi-tran","name":"Thế giới lôi điện của Lục Tuyệt Thanh Lôi trận","cn":"","capDo":"gioi-nho","parentId":"ma-gioi","blurb":"Không gian trận pháp nơi Bảo Hoa và Hắc Ngạc bị Lam Bộc Thánh Tổ cùng đồng minh vây công.","detail":"Thế giới bên trong Lục Tuyệt Thanh Lôi trận tràn ngập lôi điện và biển mây, đồng thời ngăn cách người bị vây với bên ngoài. Đòn toàn lực của Giải Đạo Nhân xuyên vào không gian này, tạo hai lỗ trắng lớn tại khu vực hai ma nữ đang đứng và mở cơ hội cho Bảo Hoa thoát đi.","theLucLienQuan":["Thế lực thành chủ Lam Bộc hồ"],"nguon":["@c2136"]},{"id":"dinh-nui-noi-bao-hoa-cho-thu-ha","name":"Đỉnh núi nơi Bảo Hoa chờ thủ hạ","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Đỉnh núi nơi Bảo Hoa và Hắc Ngạc hội hợp với một thuộc hạ cũ.","detail":"Bảo Hoa và Hắc Ngạc chờ tại đây trước khi được ma thuyền đưa đi. Nửa ngày sau, Lam Bộc, hóa thân Lục Cực và những người đi cùng tới đỉnh núi để lần dấu họ.","theLucLienQuan":["Ma tộc","Thủ hạ cũ bí mật của Bảo Hoa"],"nguon":["@c2139"]},{"id":"dong-phu-cua-bong-nguoi-trong-hao-quang-mau-vang","name":"Động phủ của bóng người trong hào quang màu vàng","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Nơi Bảo Hoa dự định tạm lánh cuộc truy tìm của Lục Cực và Lam Bộc.","detail":"Chủ nhân động phủ từng công khai thù địch Bảo Hoa và duy trì quan hệ tốt với Lam Bộc, khiến nơi này trở thành chỗ ẩn náu khó bị nghi ngờ.","theLucLienQuan":["Thủ hạ cũ bí mật của Bảo Hoa"],"nguon":["@c2139"]},{"id":"dong-la-son","name":"Đồng La Sơn","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một ngọn núi gần nơi phe Lam Bộc phát hiện dấu vết của Bảo Hoa.","detail":"Tại đây có động phủ của một Ma tôn đáng nghi. Lam Bộc và Lục Cực quyết định kiểm tra nơi này trước trong quá trình truy bắt Bảo Hoa.","theLucLienQuan":["Ma tộc"],"nguon":["@c2139"]},{"id":"vung-doi-nui-mau-vang","name":"Vùng đồi núi màu vàng","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng đồi núi vàng kéo dài tại Ma giới, nơi nhóm Hàn Lập xuất hiện sau nửa năm.","detail":"Trong vùng có một tòa thành nhỏ bên sườn núi được phòng bị bằng tường cao, quân tuần tra, ma vân và nhiều pháp trận cấm chế.","theLucLienQuan":["Ma tộc"],"nguon":["@c2139"]},{"id":"toa-thanh-nho-ben-suon-nui","name":"Tòa thành nhỏ bên sườn núi","cn":"","capDo":"thanh","parentId":"vung-doi-nui-mau-vang","blurb":"Tòa thành Ma tộc có hệ thống phòng bị nghiêm ngặt khác thường.","detail":"Thành có tường cao hơn trăm trượng, lính tuần tra, ma vân và pháp trận cấm chế dày đặc. Tình trạng này trái với thông tin Hàn Lập từng biết về nơi đây.","theLucLienQuan":["Ma tộc"],"nguon":["@c2139"]},{"id":"cu-diem-ma-toc-bao-ve-thong-dao","name":"Cứ điểm Ma tộc bảo vệ thông đạo","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Cứ điểm quy mô lớn được Ma tộc xây dựng để bảo vệ thông đạo nối với Linh Giới.","detail":"Cứ điểm có tường thành được xây thêm trong vài chục năm gần đây, nhiều tầng cấm chế bao phủ khu vực xung quanh và nhiều Ma tôn trấn giữ. Giải Đạo Nhân phá thủng phần lớn hệ thống phòng ngự, tạo điều kiện để phi xa của Hàn Lập tiến vào vùng trời bên trong.","theLucLienQuan":["Ma tộc"],"nguon":["@c2140"]},{"id":"thong-dao-noi-ma-gioi-voi-linh-gioi","name":"Thông đạo nối Ma giới với Linh Giới","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Thông đạo được nhóm Hàn Lập lựa chọn để rời Ma giới và trở về Linh Giới.","detail":"Lối vào thông đạo nằm phía sau hệ thống phòng thủ của cứ điểm và một lớp ma vân. Hàn Lập quyết định tiếp tục tiến vào đây thay vì tốn thời gian tìm kiếm một thông đạo khác.","theLucLienQuan":["Ma tộc","Linh Giới"],"nguon":["@c2140"]},{"id":"ma-van","name":"Ma vân","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Vùng sương đen bao phủ cửa thông đạo phía Ma giới. Hai Ma tôn ẩn trong hai bên sườn ma vân để ngăn người xông vào.","detail":"Ma vân che phủ khu vực cửa vào của thông đạo nối Ma giới với Linh giới. Hàn Lập điều khiển phi xa tiến vào trung tâm vùng sương và bị hai Ma tôn từ hai bên phát động công kích.","theLucLienQuan":["Ma tộc","Ma tộc tại cứ điểm"],"nguon":["@c2141"]},{"id":"khu-vuc-moc-toc","name":"Khu vực Mộc tộc","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Địa vực của Mộc tộc nằm quanh cửa ra phía Linh giới của thông đạo. Đây là nơi nhóm Hàn Lập dự kiến sẽ đến sau vài canh giờ di chuyển.","detail":"Cửa ra của thông đạo phía Linh giới nằm trong khu vực thuộc Mộc tộc. Hàn Lập biết rõ vị trí này nhưng không xem đó là trở ngại đáng kể đối với hành trình trở về Linh giới.","theLucLienQuan":["Mộc tộc"],"nguon":["@c2141"]},{"id":"dau-thong-dao-phia-moc-toc","name":"Đầu thông đạo phía Mộc tộc","cn":"","capDo":"khac","parentId":"thong-dao-noi-ma-gioi-voi-linh-gioi","blurb":"Đầu ra của thông đạo nằm trong lãnh thổ Mộc tộc và đang bị quân Ma tộc kiểm soát.","detail":"Khu vực có các đội vệ sĩ Ma tộc tuần tra cùng ba tòa tháp thấp xếp thành hình chữ “phẩm”. Khi phi xa của Hàn Lập lao ra, lực lượng tại đây phát báo động và truy đuổi nhưng không thể bắt kịp.","theLucLienQuan":["Ma tộc","Mộc tộc"],"nguon":["@c2142"]},{"id":"vung-duoc-bao-ve-cua-moc-toc","name":"Vùng được bảo vệ của Mộc tộc","cn":"","capDo":"vuc","parentId":"khu-vuc-moc-toc","blurb":"Phần lãnh thổ Mộc tộc còn lại do tàn quân bản địa và viện quân các tộc miễn cưỡng giữ vững.","detail":"Sau khi phần lớn lực lượng và lãnh thổ Mộc tộc thất thủ, tàn quân cùng viện quân các tộc tập trung bảo vệ khu vực này. Những bộ lạc còn mắc kẹt bên ngoài tìm cách rút về đây.","theLucLienQuan":["Mộc tộc","Liên minh"],"nguon":["@c2143"]},{"id":"vung-ma-toc-chiem-dong","name":"Vùng Ma tộc chiếm đóng","cn":"","capDo":"vuc","parentId":"khu-vuc-moc-toc","blurb":"Phần lãnh địa Mộc tộc đã rơi vào tay đại quân Ma tộc.","detail":"Các bộ lạc nhận tin chậm hoặc không kịp rút lui bị mắc kẹt trong khu vực này, phải ẩn náu và liên tục đối mặt với những cuộc truy tìm, tiêu diệt của Ma tộc.","theLucLienQuan":["Đại quân Ma tộc","Mộc tộc"],"nguon":["@c2143"]},{"id":"day-nui-tai-chien-truong","name":"Dãy núi tại chiến trường","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Dãy núi nơi Ngao Khiếu và Ngân Nguyệt ẩn thân trong lúc Hàn Lập cùng Giải Đạo Nhân đối đầu Nguyên Sát.","detail":"Nguyên Sát dùng bóng chùy trắng đánh xuống một ngọn núi nhỏ trong dãy núi để buộc Ngao Khiếu và Ngân Nguyệt hiện thân. Va chạm giữa bóng chùy và cầu vồng bạc san phẳng nhiều đỉnh núi cùng rừng cây trong một vùng rộng lớn.","theLucLienQuan":["Ma tộc","Yêu tộc"],"nguon":["@c2145"]},{"id":"thanh-moc-mien","name":"Thành Mộc Miên","cn":"","aliases":["Mộc Miên Thành","Mộc Miên thành"],"capDo":"thanh","parentId":"khu-vuc-moc-toc","blurb":"Thành trì được chọn làm đích quay về của chiếc thuyền bạc chở đoàn Ngao Khiếu.","detail":"Sau khi nhận định khu vực Ma tộc chiếm đóng không thể ở lâu, Ngao Khiếu ra lệnh cho môn hạ điều khiển thuyền bạc quay về Thành Mộc Miên.","theLucLienQuan":["Liên quân","Mộc tộc"],"nguon":["@c2147"]},{"id":"dai-doanh-lien-quan","name":"Đại doanh liên quân","cn":"","capDo":"khac","parentId":"thanh-moc-mien","blurb":"Đại doanh của lực lượng liên quân, nơi Ngao Khiếu định đưa Hàn Lập và Giải Đạo Nhân trở về.","detail":"Ngao Khiếu mời Hàn Lập cùng Giải Đạo Nhân trở về đại doanh liên quân và dự định giải thích tình trạng của Ngân Nguyệt trên đường.","theLucLienQuan":["Liên quân"],"nguon":["@c2147"]},{"id":"thuyen-cua-ngao-khieu","name":"Thuyền của Ngao Khiếu","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Nơi Hàn Lập mật đàm với Ngao Khiếu rồi gặp riêng Ngân Nguyệt.","detail":"Trong một căn phòng trên thuyền, Ngao Khiếu bí mật bàn bạc với Hàn Lập suốt vài canh giờ về phương pháp giảm ảnh hưởng của Vong Tình quyết. Sau đó Ngân Nguyệt tới gặp Hàn Lập và cùng hắn ôn lại những trải nghiệm từ thời Nhân giới.","theLucLienQuan":[],"nguon":["@c2148"]},{"id":"quang-truong-thanh-moc-mien","name":"Quảng trường thành Mộc Miên","cn":"","capDo":"khac","parentId":"thanh-moc-mien","blurb":"Quảng trường được canh giữ nghiêm mật bên trong thành Mộc Miên.","detail":"Thuyền bạc của Ngao Khiếu hạ xuống tại đây. Một góc quảng trường có pháp trận truyền tống được Mạc Giản Ly và cả đoàn sử dụng.","theLucLienQuan":["Yêu tộc","Nhân tộc"],"nguon":["@c2150"]},{"id":"dong-phu-tam-thoi-cua-mac-gian-ly","name":"Động phủ tạm thời của Mạc Giản Ly","cn":"","capDo":"khac","parentId":"thanh-moc-mien","blurb":"Nơi ở tạm thời của Mạc Giản Ly tại thành Mộc Miên.","detail":"Đoàn Ngao Khiếu được khoản đãi Tiên Diệp Tửu tại đây, đồng thời trao đổi về tình thế Mộc tộc và thành tựu của Hàn Lập trong Ma giới.","theLucLienQuan":["Nhân tộc","Yêu tộc","Mộc tộc"],"nguon":["@c2150"]},{"id":"cam-dia-moc-toc","name":"Cấm địa Mộc tộc","cn":"","capDo":"khac","parentId":"khu-vuc-moc-toc","blurb":"Nơi thánh thụ Mộc tộc vốn sinh trưởng trước cuộc xâm lấn của Ma tộc.","detail":"Mộc tộc buộc phải chuyển bản thể thánh thụ khỏi cấm địa đến thành Mộc Miên, khiến cây tổn thương nguyên khí.","theLucLienQuan":["Mộc tộc"],"nguon":["@c2150"]},{"id":"thuong-gioi","name":"Thượng giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện được nhắc trong dị bản cổ thư về cuộc đối đầu giữa Minh Trùng Mẫu và chân tiên.","detail":"Ngao Khiếu nhắc đến Thượng giới khi hồi tưởng ghi chép cổ liên quan đến Minh Trùng Mẫu.","theLucLienQuan":[],"nguon":["@c2152"]},{"id":"lau-cac-tren-nhanh-dai-thu-gan-dong-phu-mac-gian-ly","name":"Lầu các trên nhánh đại thụ gần động phủ Mạc Giản Ly","cn":"","capDo":"khac","parentId":"thanh-moc-mien","blurb":"Nơi tạm trú và bế quan của Hàn Lập tại Mộc Miên thành.","detail":"Lầu các nằm trên một nhánh đại thụ, cách động phủ của Mạc Giản Ly mấy chục dặm. Linh khí tại đây nồng đậm hơn nhiều khu vực khác trong thành, phù hợp để Hàn Lập bế quan tu luyện thần niệm bí thuật.","theLucLienQuan":["Nhân tộc","Liên quân"],"nguon":["@c2153"]},{"id":"ba-dai-tran-nhan-cua-moc-gioi-ba-muoi-sau-thien-tuyet-tran","name":"Ba đại trận nhãn của Mộc Giới Ba Mươi Sáu Thiên Tuyệt Trận","cn":"","capDo":"khac","parentId":null,"blurb":"Ba vị trí phòng thủ căn bản duy trì Mộc Giới Ba Mươi Sáu Thiên Tuyệt Trận.","detail":"Mỗi trận nhãn đều được bảo vệ bằng nhiều tầng pháp trận và cấm chế. Chỉ một nơi thất thủ cũng khiến uy năng toàn trận giảm mạnh, còn cả ba nơi bị phá sẽ làm đại trận hoàn toàn mất tác dụng; Hàn Lập được giao bảo vệ một trong ba vị trí này.","theLucLienQuan":["Mộc tộc","Nhân tộc","Dạ Xoa tộc","Liên quân"],"nguon":["@c2153"]},{"id":"cung-dien-mau-xanh-biec-cua-moc-toc","name":"Cung điện màu xanh biếc của Mộc tộc","cn":"","capDo":"khac","parentId":"thanh-moc-mien","blurb":"Tòa cung điện cao hơn trăm trượng nằm cuối một khoảng sân lớn trong Mộc Miên thành.","detail":"Tử Hàn triệu tập Hàn Lập, Thảo Tật và Phỉ Tiểu Tịch tại đây để phân công nhiệm vụ bảo vệ trận nhãn của đại trận Mộc Giới.","theLucLienQuan":["Mộc tộc"],"nguon":["@c2154"]},{"id":"tran-nhan-cua-dai-tran-moc-gioi","name":"Trận nhãn của đại trận Mộc Giới","cn":"","capDo":"khac","parentId":"khu-vuc-moc-toc","blurb":"Vị trí chiến lược thuộc đại trận Mộc Giới và là mục tiêu cần được bảo vệ trước sự phá hoại của Ma tộc.","detail":"Hàn Lập, Thảo Tật và Phỉ Tiểu Tịch được phân thành một tổ trấn giữ nơi này. Thảo Tật phụ trách vận dụng pháp quyết phối hợp với người điều khiển đại trận, còn hai người kia bảo vệ hắn trong lúc thi pháp.","theLucLienQuan":["Mộc tộc","Liên quân","Ma tộc"],"nguon":["@c2154"]},{"id":"khu-vuc-moc-gioi-ba-muoi-sau-thien-tuyet-tran","name":"Khu vực Mộc Giới Ba Mươi Sáu Thiên Tuyệt Trận","cn":"","capDo":"vuc","parentId":"khu-vuc-moc-toc","blurb":"Khu vực rộng hàng trăm vạn dặm, nơi ba mươi sáu cụm pháp trận được liên kết thành một tuyệt trận siêu cấp.","detail":"Khu vực gồm khoảng ba mươi sáu dãy núi nhỏ và các mắt trận được bố trí theo những vị trí liên kết huyền diệu. Sau khi toàn trận được kích hoạt, nơi đây trở thành bẫy sát thương nhằm tiêu diệt đại quân Ma tộc.","theLucLienQuan":["Mộc tộc","Liên quân","Ma tộc"],"nguon":["@c2155"]},{"id":"day-nui-dat-mat-tran-thu-hai","name":"Dãy núi đặt mắt trận thứ hai","cn":"","capDo":"khac","parentId":"khu-vuc-moc-gioi-ba-muoi-sau-thien-tuyet-tran","blurb":"Dãy núi rộng hơn trăm dặm, nơi đặt mắt trận do Hàn Lập, Phỉ Tiểu Tịch và Thảo Tật trấn giữ.","detail":"Trên dãy núi có nhiều lâu đài khắc linh văn, cờ trận và pháp trận. Một thung lũng bên trong chứa thánh thụ cao hàng nghìn trượng, đóng vai trò hạch tâm của mắt trận thứ hai.","theLucLienQuan":["Mộc tộc","Liên quân"],"nguon":["@c2155"]},{"id":"thung-lung-thanh-thu","name":"Thung lũng thánh thụ","cn":"","capDo":"khac","parentId":"day-nui-dat-mat-tran-thu-hai","blurb":"Thung lũng trung tâm của mắt trận thứ hai, nơi một thánh thụ dự phòng được nuôi dưỡng và bảo vệ.","detail":"Quanh gốc đại thụ có hàng trăm mẫu pháp trận xanh nhạt. Hơn trăm tu sĩ Nguyên Anh Mộc tộc vận hành các pháp trận để thúc đẩy thánh thụ sinh trưởng và chuẩn bị kích hoạt mắt trận.","theLucLienQuan":["Mộc tộc"],"nguon":["@c2155"]},{"id":"dai-thu-cao-choc-troi","name":"Đại thụ cao chọc trời","cn":"","capDo":"khac","parentId":"thung-lung-thanh-thu","blurb":"Đại thụ nằm trên trận nhãn do Hàn Lập cùng hai người khác trực tiếp canh giữ.","detail":"Ba người Hàn Lập ngồi dưới gốc đại thụ để đề phòng cao giai Ma tộc tập kích. Trận nhãn vẫn an toàn chừng nào thánh thụ chưa bị phá hủy.","theLucLienQuan":["Liên quân","Mộc tộc"],"nguon":["@c2156"]},{"id":"cong-trinh-trong-dam-may","name":"Công trình trong đám mây","cn":"","capDo":"khac","parentId":"thung-lung-thanh-thu","blurb":"Kiến trúc tạm thời nằm trong đám mây lớn phía trên khu vực trận nhãn.","detail":"Giải Đạo Nhân được Hàn Lập bố trí ẩn thân tại đây và ngụy trang thành trung giai Nhân tộc nhằm tránh sự chú ý của người ngoài.","theLucLienQuan":["Liên quân"],"nguon":["@c2156"]},{"id":"moc-gioi-dai-tran","name":"Mộc giới đại trận","cn":"","capDo":"vuc","parentId":"khu-vuc-moc-toc","blurb":"Siêu cấp đại trận được Mộc tộc dùng làm trung tâm cho kế hoạch tiêu diệt đại quân Ma tộc.","detail":"Liên quân vừa đánh vừa rút để dẫn đối phương tiến sát phạm vi đại trận. Việc đại quân Ma tộc không có bản thể Thánh Tổ tọa trấn khiến nơi này trở thành mối đe dọa đặc biệt nghiêm trọng đối với họ.","theLucLienQuan":["Mộc tộc","Liên quân","Ma tộc"],"nguon":["@c2156"]},{"id":"khu-vuc-tran-dia-moc-toc","name":"Khu vực trận địa Mộc tộc","cn":"","capDo":"vuc","parentId":"khu-vuc-moc-toc","blurb":"Vùng núi cao nằm trong phạm vi đại trận của Mộc tộc, nơi tổ chức hoạt động bói toán chiến cục.","detail":"Đại trưởng lão tạm thời cùng các trưởng lão hiện diện tại đây để tiếp nhận kết quả suy đoán từ Mộc Linh Bát Tử.","theLucLienQuan":["Mộc tộc"],"nguon":["@c2156"]},{"id":"bien-gioi-moc-toc-ma-toc","name":"Biên giới Mộc tộc — Ma tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Ranh giới chiến trường cũ giữa khu vực Mộc tộc và vùng do Ma tộc kiểm soát.","detail":"Các cuộc đối kháng cấp cao vẫn diễn ra tại vùng biên giới này. Một đội hơn ngàn phi xa Ma tộc cũng bí mật áp sát chiến trường từ đây.","theLucLienQuan":["Mộc tộc","Ma tộc","Liên quân"],"nguon":["@c2156"]},{"id":"chien-truong-trong-dai-tran-moc-toc","name":"Chiến trường trong đại trận Mộc tộc","cn":"","capDo":"khac","parentId":"khu-vuc-moc-gioi-ba-muoi-sau-thien-tuyet-tran","blurb":"Chiến trường nơi hơn nửa đại quân Ma tộc bị giam trong đại trận.","detail":"Sau gần nửa ngày giao chiến, ma trận phòng thủ của Ma quân bị liên quân các tộc đánh tan. Khu vực này sau đó trở thành nơi liên quân truy sát số Ma tộc đang rút lui.","theLucLienQuan":["Mộc tộc","Ma tộc","Liên quân"],"nguon":["@c2158"]},{"id":"can-phong-bi-mat-duoi-dat","name":"Căn phòng bí mật dưới đất","cn":"","capDo":"khac","parentId":null,"blurb":"Căn phòng ngầm nơi Nguyên Sát duy trì cuộc đấu pháp từ xa.","detail":"Nguyên Sát giao chiến với Ngao Khiếu thông qua hình ảnh sói ma tại đây và nhận được tin khẩn báo đại quân Ma tộc thất thế.","theLucLienQuan":["Ma tộc"],"nguon":["@c2158"]},{"id":"dam-lay-ngao-khieu-chan-nguyen-sat","name":"Đầm lầy","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực đầm lầy nơi Ngao Khiếu chặn đường Nguyên Sát.","detail":"Nguyên Sát đang bay về phía Mộc tộc thì bị Ngao Khiếu xuất hiện ngăn lại trên không. Hai người tiếp tục đại chiến tại khu vực này.","theLucLienQuan":["Ma tộc","Liên quân"],"nguon":["@c2158"]},{"id":"mang-rung-trong-moc-gioi","name":"Mảng rừng trong Mộc Giới","cn":"","capDo":"khac","parentId":"khu-vuc-moc-gioi-ba-muoi-sau-thien-tuyet-tran","blurb":"Một khu rừng chứa cấm chế mộc kiếm nguy hiểm trong Mộc Giới.","detail":"Đội quân do Ma Tôn đầu trâu dẫn đầu bị hơn trăm mộc kiếm tập kích tại đây. Toàn bộ thuộc hạ Luyện Hư bị tiêu diệt, còn Ma Tôn đầu trâu sống sót nhưng bị thương và hư hại pháp bảo.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c2158"]},{"id":"dai-nui-trong-dai-tran","name":"Dải núi trong đại trận","cn":"","capDo":"khac","parentId":"khu-vuc-moc-gioi-ba-muoi-sau-thien-tuyet-tran","blurb":"Một dải núi nơi ba Ma Tôn bị pháp trận ánh sáng vàng công kích.","detail":"Ba Ma Tôn dùng ma khí hợp thành thái cực đồ phòng hộ tại đây. Các cột sáng vàng phá tan phòng ngự, sau đó cả ba đều mất tung tích.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c2158"]},{"id":"trung-tam-day-nui","name":"Trung tâm dãy núi","cn":"","capDo":"khac","parentId":"day-nui-tai-chien-truong","blurb":"Khu vực trọng yếu có gốc cây chọc trời và pháp trận do người Mộc tộc vận hành.","detail":"Hàn Lập trấn giữ dưới gốc cây lớn tại đây. Thân cây có thể phát sáng, hiện ký hiệu năm màu và rung lên để cảnh báo khi Ma tộc có tu vi cao tiến đến gần.","theLucLienQuan":["Mộc tộc","Liên quân"],"nguon":["@c2158"]},{"id":"mat-tran-trong-day-nui-moc-toc","name":"Mắt trận trong dãy núi Mộc tộc","cn":"","capDo":"khac","parentId":"dai-nui-trong-dai-tran","blurb":"Mắt trận trọng yếu nằm trong dãy núi Mộc tộc, có gốc cây khổng lồ và pháp trận giám sát.","detail":"Nơi đây đang tích lũy năng lượng cho toàn bộ đại trận nên các cấm chế mạnh nhất không thể tùy tiện sử dụng. Thảo Tật cùng hơn trăm người Mộc tộc ở lại bảo vệ và vận hành trận pháp, trong khi nhóm Hàn Lập xuất kích ngăn quân địch.","theLucLienQuan":["Mộc tộc","Lực lượng phòng thủ mắt trận Mộc tộc"],"nguon":["@c2159"]},{"id":"mang-rung-gan-day-nui","name":"Mảng rừng gần dãy núi","cn":"","capDo":"khac","parentId":"dai-nui-trong-dai-tran","blurb":"Mảng rừng nằm gần dãy núi và trên tuyến tiến quân của nhóm Ma tộc.","detail":"Bảy Ma tộc bị cấm chế sấm chớp tấn công tại khu vực này và bị pháp trận giám sát phát hiện trước khi chúng tiếp tục tiến về trung tâm dãy núi.","theLucLienQuan":["Nhóm bảy Ma tộc xâm nhập dãy núi","Mộc tộc"],"nguon":["@c2159"]},{"id":"chien-truong-moc-toc","name":"Chiến trường Mộc tộc","cn":"","capDo":"khac","parentId":"khu-vuc-moc-toc","blurb":"Chiến trường nơi nhiều cuộc giao tranh giữa lực lượng Mộc tộc và Ma tộc đồng thời diễn ra.","detail":"Tại một khu vực, Hàn Lập truy sát rồi tiêu diệt Ma Tôn mặt xanh. Ở khu vực khác, Phỉ Tiểu Tịch cùng hơn mười tu sĩ Mộc tộc bao vây bốn Ma tu Luyện Hư.","theLucLienQuan":["Mộc tộc","Ma tộc","Dạ Xoa tộc"],"nguon":["@c2160","@c2164","@c2167"]},{"id":"rung-ram-phu-hao-quang-nam-mau","name":"Rừng rậm phủ hào quang năm màu","cn":"","capDo":"khac","parentId":"chien-truong-moc-toc","blurb":"Một khu rừng được hào quang năm màu bao phủ tại chiến trường Mộc tộc.","detail":"Không trung phía trên khu rừng là nơi Phỉ Tiểu Tịch cùng hơn mười tu sĩ Mộc tộc bao vây bốn Ma tu Luyện Hư tu luyện Huyết Kha Vô Lượng Ma Công.","theLucLienQuan":["Mộc tộc","Ma tộc","Dạ Xoa tộc"],"nguon":["@c2160"]},{"id":"chien-truong-trong-may-nam-mau","name":"Chiến trường trong mây năm màu","cn":"","capDo":"khac","parentId":"chien-truong-moc-toc","blurb":"Khu vực giao chiến được Phỉ Tiểu Tịch phủ kín bằng mây mù năm màu và cấm chế vô hình.","detail":"Quân Mộc tộc dựa vào cấm chế tại đây để chống lại sóng khí màu máu và phối hợp nhiều bảo vật vây đánh người khổng lồ lông đỏ do bốn Ma tộc Luyện Hư hợp nhất.","theLucLienQuan":["Mộc tộc","Ma tộc","Dạ Xoa tộc"],"nguon":["@c2161"]},{"id":"bai-chien-cua-giai-dao-nhan","name":"Bãi chiến của Giải Đạo Nhân","cn":"","capDo":"khac","parentId":"chien-truong-moc-toc","blurb":"Khoảng không nơi Giải Đạo Nhân kết liễu hai Ma tộc cao cấp trước khi hội hợp với Hàn Lập.","detail":"Khu vực không có mây, mặt đất chi chít hố lớn nhỏ và gần Giải Đạo Nhân có hai thi thể Ma tộc cao cấp đã tan nát.","theLucLienQuan":["Ma tộc"],"nguon":["@c2161"]},{"id":"mat-tran-so-ba","name":"Mắt trận số ba","cn":"","capDo":"khac","parentId":"tran-nhan-cua-dai-tran-moc-gioi","blurb":"Một mắt trận trọng yếu của Mộc Giới đại trận, bị sáu hóa thân Thánh tổ Ma tộc công phá.","detail":"Sáu hóa thân Thánh tổ giết toàn bộ những người trấn giữ rồi phá hủy mắt trận. Việc nơi này thất thủ khiến một số cấm chế của Mộc Giới đại trận không thể vận dụng và những cấm chế khác suy yếu.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c2162"]},{"id":"mat-tran-so-mot","name":"Mắt trận số một","cn":"","capDo":"khac","parentId":"tran-nhan-cua-dai-tran-moc-gioi","blurb":"Mắt trận thuộc Mộc Giới đại trận do Hàn Lập tham gia bảo vệ.","detail":"Sau khi mắt trận số ba thất thủ, Hàn Lập dự đoán mắt trận số một cũng có thể sớm bị các hóa thân Thánh tổ tập kích nếu Ma tộc đã nắm rõ bố trí đại trận.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c2162","@c2169"]},{"id":"day-nui-dat-mat-tran-moc-toc","name":"Dãy núi đặt mắt trận Mộc tộc","cn":"","capDo":"khac","parentId":"chien-truong-moc-toc","blurb":"Khu vực phòng thủ mà nhóm năm Ma tộc cao cấp đang tiến tới. Hàn Lập và Giải Đạo Nhân được truyền tống tới vị trí cách dãy núi hơn trăm dặm để chặn đường.","detail":"Dãy núi chứa mắt trận Mộc tộc và là mục tiêu tiến công của nhóm hóa thân Thánh Tổ. Cuộc đối đầu giữa Hàn Lập, Giải Đạo Nhân và năm Ma tộc cao cấp diễn ra trên đường tiến tới khu vực này.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c2163"]},{"id":"mat-tran-do-thao-tat-tran-giu","name":"Mắt trận do Thảo Tật trấn giữ","cn":"","capDo":"khac","parentId":"day-nui-dat-mat-tran-moc-toc","blurb":"Mắt trận Mộc tộc do Thảo Tật phụ trách, đang bị năm kẻ có tu vi Hợp Thể Hậu Kỳ tiến công. Nơi đây có gốc thánh thụ dự phòng dùng để chuẩn bị cấm chế giam địch.","detail":"Thảo Tật dự định đảo ngược uy lực đại trận, hấp thu năng lượng vào gốc thánh thụ dự phòng và kích hoạt cấm chế nếu Hàn Lập có thể cầm chân nhóm hóa thân Thánh Tổ thêm nửa canh giờ.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c2163"]},{"id":"khu-vuc-giua-hai-qua-nui-cach-chien-truong-hon-van-dam","name":"Khu vực giữa hai quả núi cách chiến trường hơn vạn dặm","cn":"","capDo":"khac","parentId":null,"blurb":"Điểm đến của lôi trận truyền tống do Hàn Lập dựng lên.","detail":"Hàn Lập xuất hiện lơ lửng giữa hai quả núi cùng pháp tướng ba đầu sáu tay và bảy mươi hai thanh kiếm xanh, đối diện lão già mặc áo bào cùng Linh tiên tử.","theLucLienQuan":["Ma tộc"],"nguon":["@c2165"]},{"id":"chien-truong-rung-moc-toc","name":"Chiến trường rừng Mộc tộc","cn":"","capDo":"khac","parentId":"chien-truong-moc-toc","blurb":"Khu rừng nơi Hàn Lập truy sát lão già Ma tộc và Ma nữ có cánh.","detail":"Một quyền kích đánh Ma nữ có cánh xuống rừng tạo thành hố hình người. Sau đó, một chưởng của Hàn Lập xóa sạch mọi vật trong phạm vi một dặm và để lại dấu tay khổng lồ.","theLucLienQuan":["Mộc Tộc","Ma tộc"],"nguon":["@c2168"]},{"id":"chien-truong-cua-giai-dao-nhan","name":"Chiến trường của Giải Đạo Nhân","cn":"","capDo":"khac","parentId":"chien-truong-moc-toc","blurb":"Khu vực Giải Đạo Nhân một mình cầm chân ba Ma tộc.","detail":"Nơi này cách chỗ Hàn Lập giao chiến hơn vạn dặm. Giải Đạo Nhân dựng pháp trận sấm chớp tại đây để giữ ba Ma tộc cho tới khi Hàn Lập trở lại.","theLucLienQuan":["Mộc Tộc","Ma tộc"],"nguon":["@c2168"]},{"id":"mat-tran-so-hai-cua-dai-tran-moc-gioi","name":"Mắt trận số hai của đại trận Mộc Giới","cn":"","capDo":"khac","parentId":null,"blurb":"Mắt trận do nhóm Thảo Tật trấn giữ và được Hàn Lập cùng Giải Đạo Nhân hỗ trợ. Đây là nơi hai nhóm hóa thân Thánh Tổ của Ma tộc lần lượt bị tiêu diệt hoặc chia cắt.","detail":"Cấm chế tại mắt trận được bảo lưu sau trận đầu rồi kích phát khi nhóm bảy Ma tộc tiến vào. Bốn kẻ bị nhốt trong quang cầu, còn ba kẻ thoát ra bị Hàn Lập và Giải Đạo Nhân chặn đường.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c2169"]},{"id":"day-nui-quanh-mat-tran-so-hai","name":"Dãy núi quanh mắt trận số hai","cn":"","capDo":"vuc","parentId":"mat-tran-so-hai-cua-dai-tran-moc-gioi","blurb":"Khu vực phục kích quanh mắt trận số hai, nơi Mộc tộc bố trí nhiều cấm chế. Thảm thực vật tại đây có khả năng tái sinh nhanh chóng.","detail":"Sau khi Hàn Lập và Giải Đạo Nhân rời đi, hào quang xanh khiến cây cối mọc lại thành những cổ thụ cao hàng trăm trượng, che kín toàn bộ dấu vết chiến đấu.","theLucLienQuan":["Mộc tộc"],"nguon":["@c2169"]}]};
